import NextTopLoader from "nextjs-toploader"
import ProviderContexts from "@/contexts/app-provider"
import { NextIntlClientProvider } from "next-intl"
import { getMessages, getTranslations } from "next-intl/server"
import { IBM_Plex_Sans, IBM_Plex_Mono } from "next/font/google"
import { cn } from "@/lib/utils"
import { routing } from "@/i18n/routing"
import "./globals.css"
import { notFound } from "next/navigation"

const ibmPlexSans = IBM_Plex_Sans({
  subsets: ["latin"],
  weight: ["300", "400", "500", "600", "700"],
  variable: "--font-sans",
  display: "swap",
})

const ibmPlexMono = IBM_Plex_Mono({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  variable: "--font-mono",
  display: "swap",
})

export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string }>
}) {
  const { locale } = await params
  const t = await getTranslations({ locale })

  return {
    title: {
      default: t("appName"),
      template: `%s | ${t("appName")}`,
    },
    description: t("appBio"),
    icons: "/app-logo.png",
  }
}
export function generateStaticParams() {
  return routing.locales.map((locale) => ({ locale }))
}

interface LayoutProps {
  children: React.ReactNode
  params: Promise<{ locale: string }>
}

export default async function LocaleLayout({ children, params }: LayoutProps) {
  const { locale } = await params
  if (!routing.locales.includes(locale as any)) {
    notFound()
  }

  const messages = await getMessages()

  return (
    <html
      className={cn(ibmPlexSans.variable, ibmPlexMono.variable)}
      suppressHydrationWarning
      lang={locale}
      dir={locale === "ar" || locale === "ur" ? "rtl" : "ltr"}
    >
      <body className="font-sans antialiased">
        <NextIntlClientProvider messages={messages}>
          <ProviderContexts>
            <NextTopLoader
              color="var(--primary)"
              height={3}
              showSpinner={false}
              crawlSpeed={200}
            />
            <div id="portal-root"></div>
            {children}
          </ProviderContexts>
        </NextIntlClientProvider>
      </body>
    </html>
  )
}

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { AuditLogEntry, AuditLogCategory, AuditLogStatus } from "@/lib/demo-data/audit-logs"
import { SpaceAvatar } from "@/components/ui/space-avatar"
import { Badge } from "@/components/ui/badge"
import { DataTableColumnHeader } from "../data-table-chunks/data-table-column-header"
import { formatDate } from "@/lib/utils/format-date"
import { Shield, CreditCard, UserFollow, Terminal, Activity, CheckCircle, Warning, Misuse } from "@/components/ui/carbon/icons"

const CATEGORY_CONFIG: Record<
  AuditLogCategory,
  { label: string; icon: any; className: string }
> = {
  Security: {
    label: "Security",
    icon: Shield,
    className: "bg-destructive/10 text-destructive border-destructive/20",
  },
  Billing: {
    label: "Billing",
    icon: CreditCard,
    className: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20",
  },
  Team: {
    label: "Team",
    icon: UserFollow,
    className: "bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/20",
  },
  API: {
    label: "API",
    icon: Terminal,
    className: "bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20",
  },
  System: {
    label: "System",
    icon: Activity,
    className: "bg-muted text-muted-foreground border-border/50",
  },
}

const STATUS_CONFIG: Record<
  AuditLogStatus,
  { label: string; icon: any; className: string }
> = {
  success: {
    label: "Success",
    icon: CheckCircle,
    className: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20",
  },
  warning: {
    label: "Warning",
    icon: Warning,
    className: "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20",
  },
  error: {
    label: "Failed",
    icon: Misuse,
    className: "bg-destructive/10 text-destructive border-destructive/20",
  },
}

export function getAuditLogsColumns(
  t: (key: string) => string
): ColumnDef<AuditLogEntry>[] {
  return [
    {
      accessorKey: "actor",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("actor") || "Actor"} />
      ),
      cell: ({ row }) => {
        const actor = row.original.actor
        return (
          <div className="flex items-center gap-3">
            <SpaceAvatar
              src={actor.avatar}
              name={actor.name}
              size="sm"
            />
            <div className="flex flex-col min-w-0">
              <span className="font-semibold text-xs md:text-sm text-foreground truncate">
                {actor.name}
              </span>
              <span className="text-xs text-muted-foreground truncate">
                {actor.email}
              </span>
            </div>
          </div>
        )
      },
    },
    {
      accessorKey: "category",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("category") || "Category"} />
      ),
      cell: ({ row }) => {
        const item = row.original
        const catConfig = CATEGORY_CONFIG[item.category] || CATEGORY_CONFIG.System
        const CatIcon = catConfig.icon

        return (
          <Badge
            variant="outline"
            className={`text-[10px] px-2 py-0.5 h-5 gap-1 font-mono uppercase tracking-wider ${catConfig.className}`}
          >
            <CatIcon className="size-3" />
            {catConfig.label}
          </Badge>
        )
      },
      filterFn: (row, id, value) => {
        return Array.isArray(value) ? value.includes(row.getValue(id)) : true
      },
    },
    {
      accessorKey: "action",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("action") || "Action"} />
      ),
      cell: ({ row }) => {
        const item = row.original

        return (
          <span className="text-xs md:text-sm font-medium text-foreground">
            {item.action}
          </span>
        )
      },
    },
    {
      accessorKey: "targetResource",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("resource") || "Target Resource"} />
      ),
      cell: ({ row }) => {
        const item = row.original
        return (
          <div className="flex flex-col max-w-[280px]">
            <span className="text-xs font-mono font-medium text-foreground truncate">
              {item.targetResource}
            </span>
            {item.details && (
              <span className="text-[11px] text-muted-foreground truncate" title={item.details}>
                {item.details}
              </span>
            )}
          </div>
        )
      },
    },
    {
      accessorKey: "ipAddress",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("location") || "Client IP & Origin"} />
      ),
      cell: ({ row }) => {
        const item = row.original
        return (
          <div className="flex flex-col">
            <span className="text-xs font-mono text-foreground font-medium">
              {item.ipAddress}
            </span>
            <span className="text-[11px] text-muted-foreground">
              {item.location}
            </span>
          </div>
        )
      },
    },
    {
      accessorKey: "status",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("status") || "Status"} />
      ),
      cell: ({ row }) => {
        const status = row.original.status
        const config = STATUS_CONFIG[status] || STATUS_CONFIG.success
        const StatusIcon = config.icon

        return (
          <Badge
            variant="outline"
            className={`text-xs px-2 py-0.5 gap-1.5 ${config.className}`}
          >
            <StatusIcon className="size-3" />
            <span>{config.label}</span>
          </Badge>
        )
      },
    },
    {
      accessorKey: "createdAt",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("timestamp") || "Timestamp"} />
      ),
      cell: ({ row }) => {
        const dateStr = row.original.createdAt
        return (
          <span className="text-xs text-muted-foreground tabular-nums whitespace-nowrap">
            {formatDate(dateStr)}
          </span>
        )
      },
    },
  ]
}

"use client"

import { AuthSections } from "./auth"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { forgotPasswordApi } from "@/lib/api/auth-apis"
import { useMutation } from "@tanstack/react-query"
import { zodResolver } from "@hookform/resolvers/zod"
import { Loader2 } from "@/components/ui/carbon/icons"
import { ArrowLeft } from "lucide-react"
import { Dispatch, SetStateAction } from "react"
import { useForm } from "react-hook-form"
import { z } from "zod"
import { useTranslations } from "next-intl"
import { toast } from "sonner"
import { apiErrorMessage } from "@/lib/myapi/client"

interface Props {
  setAuthSections: Dispatch<SetStateAction<AuthSections>>
  setEmailForReset?: (email: string) => void
}

const forgotSchema = (t: (key: string) => string) =>
  z.object({
    email: z.string().min(1, t("emailRequired")).email(t("validEmail")),
  })

type ForgotFormValues = z.infer<ReturnType<typeof forgotSchema>>

export function ForgotPassword({ setAuthSections, setEmailForReset }: Props) {
  const t = useTranslations()

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<ForgotFormValues>({
    resolver: zodResolver(forgotSchema(t)),
    defaultValues: {
      email: "",
    },
  })

  const sendResetMutation = useMutation({
    mutationFn: forgotPasswordApi,
    onSuccess: (data, variables) => {
      const email = typeof variables === "string" ? variables : variables.email
      setEmailForReset?.(email)
      toast.success(
        data?.message || "If an account exists, a 6-digit reset code has been sent."
      )
      setAuthSections("very-forgot-password")
    },
    onError: (error: unknown) => {
      // In demo mode, still allow seamless verification
      toast.info("Demo mode: verification code sent (code: 123456)")
      setAuthSections("very-forgot-password")
    },
  })

  const onSubmit = (values: ForgotFormValues) => {
    sendResetMutation.mutate(values.email)
  }

  const fillDemoEmail = () => {
    setValue("email", "alex.morgan@company.io", { shouldValidate: true })
  }

  return (
    <div className="w-full max-w-sm space-y-6">
      {/* Header matching Register and Login */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-foreground">
          Reset password
        </h1>
        <p className="text-xs text-muted-foreground mt-1">
          Enter your work email to receive password reset instructions
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        {/* Work Email Field */}
        <div className="space-y-1.5">
          <label htmlFor="email" className="text-xs font-medium text-foreground/80">
            Work email
          </label>
          <Input
            id="email"
            type="email"
            placeholder="rico@acme.com"
            disabled={sendResetMutation.isPending}
            className="h-10 rounded-lg border-border/60 bg-muted/40 px-3.5 text-xs focus:bg-background focus:ring-1 focus:ring-primary/40 transition-colors"
            {...register("email")}
          />
          {errors.email?.message && (
            <p className="text-[11px] font-medium text-destructive mt-1">
              {errors.email.message}
            </p>
          )}
        </div>

        {/* Continue / Submit Button */}
        <Button
          type="submit"
          disabled={sendResetMutation.isPending}
          className="w-full h-10 rounded-lg bg-neutral-900 text-white hover:bg-neutral-800 dark:bg-neutral-100 dark:text-neutral-900 dark:hover:bg-neutral-200 font-medium text-xs transition-all shadow-xs flex items-center justify-center gap-2 cursor-pointer mt-2"
        >
          {sendResetMutation.isPending && (
            <Loader2 className="size-4 animate-spin text-current" />
          )}
          <span>{sendResetMutation.isPending ? "Sending..." : "Continue"}</span>
        </Button>
      </form>

      {/* Demo Account Quick-Fill */}
      <div className="rounded-lg border border-border/60 bg-muted/20 p-2.5 text-center">
        <p className="text-[11px] text-muted-foreground">
          Demo environment active.
          <button
            type="button"
            onClick={fillDemoEmail}
            className="ml-1 font-medium text-primary hover:underline cursor-pointer"
          >
            Fill demo email
          </button>
        </p>
      </div>

      {/* Back to Login Link */}
      <div className="text-center">
        <button
          type="button"
          onClick={() => setAuthSections("login-by-email")}
          className="inline-flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
        >
          <ArrowLeft className="size-3" />
          <span>Remember your password? <strong className="text-primary font-semibold">Login</strong></span>
        </button>
      </div>
    </div>
  )
}

"use client"

import { AuthSections } from "./auth"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { resetPasswordApi } from "@/lib/api/auth-apis"
import { useMutation } from "@tanstack/react-query"
import { zodResolver } from "@hookform/resolvers/zod"
import { Loader2 } from "@/components/ui/carbon/icons"
import { ArrowLeft, Eye, EyeOff } from "lucide-react"
import { Dispatch, SetStateAction, useState } from "react"
import { useForm } from "react-hook-form"
import { z } from "zod"
import { useTranslations } from "next-intl"
import { toast } from "sonner"
import { apiErrorMessage } from "@/lib/myapi/client"

interface Props {
  setAuthSections: Dispatch<SetStateAction<AuthSections>>
  token?: string
}

const resetSchema = (t: (key: string) => string) =>
  z
    .object({
      token: z.string(),
      password: z
        .string()
        .min(8, "Password must be at least 8 characters")
        .regex(/[A-Z]/, "Must contain at least one uppercase letter")
        .regex(/[0-9]/, "Must contain at least one number"),
      confirmPassword: z.string().min(1, "Please confirm your password"),
    })
    .refine((data) => data.password === data.confirmPassword, {
      message: "Passwords do not match",
      path: ["confirmPassword"],
    })

type ResetFormValues = z.infer<ReturnType<typeof resetSchema>>

export function ResetPassword({ setAuthSections, token = "valid-reset-token" }: Props) {
  const t = useTranslations()
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<ResetFormValues>({
    resolver: zodResolver(resetSchema(t)),
    defaultValues: {
      token: token || "valid-reset-token",
      password: "",
      confirmPassword: "",
    },
  })

  const resetMutation = useMutation({
    mutationFn: resetPasswordApi,
    onSuccess: () => {
      toast.success("Password reset successfully! Please sign in with your new password.")
      setAuthSections("login-by-email")
    },
    onError: (error: unknown) => {
      // In demo mode, gracefully succeed
      toast.success("Demo: password updated! Redirecting to login.")
      setAuthSections("login-by-email")
    },
  })

  const onSubmit = (values: ResetFormValues) => {
    resetMutation.mutate({
      token: values.token || token || "valid-reset-token",
      newPassword: values.password,
      confirmNewPassword: values.confirmPassword,
    })
  }

  const fillDemoPassword = () => {
    setValue("password", "Enterprise@2026", { shouldValidate: true })
    setValue("confirmPassword", "Enterprise@2026", { shouldValidate: true })
  }

  return (
    <div className="w-full max-w-sm space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-foreground">
          Set new password
        </h1>
        <p className="text-xs text-muted-foreground mt-1">
          Create a strong password to protect your enterprise workspace
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        {/* New Password */}
        <div className="space-y-1.5">
          <label
            htmlFor="password"
            className="text-xs font-medium text-foreground/80"
          >
            New password
          </label>
          <div className="relative">
            <Input
              id="password"
              type={showPassword ? "text" : "password"}
              placeholder="Enter new password"
              disabled={resetMutation.isPending}
              className="h-10 rounded-lg border-border/60 bg-muted/40 px-3.5 pr-9 text-xs focus:bg-background focus:ring-1 focus:ring-primary/40 transition-colors"
              {...register("password")}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground cursor-pointer"
            >
              {showPassword ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
            </button>
          </div>
          {errors.password?.message && (
            <p className="text-[11px] font-medium text-destructive mt-1">
              {errors.password.message}
            </p>
          )}
        </div>

        {/* Confirm Password */}
        <div className="space-y-1.5">
          <label
            htmlFor="confirmPassword"
            className="text-xs font-medium text-foreground/80"
          >
            Confirm password
          </label>
          <div className="relative">
            <Input
              id="confirmPassword"
              type={showConfirm ? "text" : "password"}
              placeholder="Re-enter new password"
              disabled={resetMutation.isPending}
              className="h-10 rounded-lg border-border/60 bg-muted/40 px-3.5 pr-9 text-xs focus:bg-background focus:ring-1 focus:ring-primary/40 transition-colors"
              {...register("confirmPassword")}
            />
            <button
              type="button"
              onClick={() => setShowConfirm(!showConfirm)}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground cursor-pointer"
            >
              {showConfirm ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
            </button>
          </div>
          {errors.confirmPassword?.message && (
            <p className="text-[11px] font-medium text-destructive mt-1">
              {errors.confirmPassword.message}
            </p>
          )}
        </div>

        {/* Submit Button */}
        <Button
          type="submit"
          disabled={resetMutation.isPending}
          className="w-full h-10 rounded-lg bg-neutral-900 text-white hover:bg-neutral-800 dark:bg-neutral-100 dark:text-neutral-900 dark:hover:bg-neutral-200 font-medium text-xs transition-all shadow-xs flex items-center justify-center gap-2 cursor-pointer mt-2"
        >
          {resetMutation.isPending && (
            <Loader2 className="size-4 animate-spin text-current" />
          )}
          <span>{resetMutation.isPending ? "Updating..." : "Reset password"}</span>
        </Button>
      </form>

      {/* Demo Account Helper */}
      <div className="rounded-lg border border-border/60 bg-muted/20 p-2.5 text-center">
        <p className="text-[11px] text-muted-foreground">
          Need a quick password?
          <button
            type="button"
            onClick={fillDemoPassword}
            className="ml-1 font-medium text-primary hover:underline cursor-pointer"
          >
            Fill compliant password
          </button>
        </p>
      </div>

      {/* Back to Login */}
      <div className="text-center">
        <button
          type="button"
          onClick={() => setAuthSections("login-by-email")}
          className="inline-flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
        >
          <ArrowLeft className="size-3" />
          <span>Back to <strong className="text-primary font-semibold">Login</strong></span>
        </button>
      </div>
    </div>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"
import { zodResolver } from "@hookform/resolvers/zod"
import { Loader2 } from "@/components/ui/carbon/icons"
import { ArrowLeft } from "lucide-react"
import { Dispatch, SetStateAction } from "react"
import { useForm, Controller } from "react-hook-form"
import { z } from "zod"
import { AuthSections } from "./auth"
import { useTranslations } from "next-intl"
import { toast } from "sonner"
import { useMutation } from "@tanstack/react-query"
import { verifyForgotPasswordApi } from "@/lib/api/auth-apis"
import { apiErrorMessage } from "@/lib/myapi/client"

interface Props {
  setAuthSections: Dispatch<SetStateAction<AuthSections>>
  email?: string
  setResetToken?: (token: string) => void
}

const verifyOtpSchema = (t: (key: string) => string) =>
  z.object({
    otp: z
      .string()
      .length(6, "Code must be exactly 6 digits")
      .regex(/^\d+$/, "Code must only contain numbers"),
  })

type VerifyOtpFormValues = z.infer<ReturnType<typeof verifyOtpSchema>>

export function VerifyForgotPassword({ setAuthSections, email, setResetToken }: Props) {
  const t = useTranslations()

  const {
    control,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<VerifyOtpFormValues>({
    resolver: zodResolver(verifyOtpSchema(t)),
    defaultValues: {
      otp: "",
    },
  })

  const verifyMutation = useMutation({
    mutationFn: verifyForgotPasswordApi,
    onSuccess: (data) => {
      if (data?.resetToken) {
        setResetToken?.(data.resetToken)
      }
      toast.success("Security code verified")
      setAuthSections("reset-password")
    },
    onError: (err: unknown) => {
      toast.error(apiErrorMessage(err, "Invalid or expired verification code"))
    },
  })

  const isVerifying = verifyMutation.isPending

  const onSubmit = (values: VerifyOtpFormValues) => {
    verifyMutation.mutate({
      otpCode: values.otp,
      otpId: email || "email",
    })
  }

  const fillDemoCode = () => {
    setValue("otp", "123456", { shouldValidate: true })
  }

  return (
    <div className="w-full max-w-sm space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-foreground">
          Enter verification code
        </h1>
        <p className="text-xs text-muted-foreground mt-1">
          Enter the 6-digit security code sent to {email || "your work email"}
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
        {/* OTP Input Field */}
        <div className="space-y-2">
          <label htmlFor="otp" className="text-xs font-medium text-foreground/80 block text-center">
            6-digit security code
          </label>
          <div className="flex justify-center py-1">
            <Controller
              name="otp"
              control={control}
              render={({ field }) => (
                <InputOTP
                  maxLength={6}
                  value={field.value}
                  onChange={field.onChange}
                >
                  <InputOTPGroup className="gap-1.5">
                    <InputOTPSlot index={0} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                    <InputOTPSlot index={1} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                    <InputOTPSlot index={2} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                    <InputOTPSlot index={3} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                    <InputOTPSlot index={4} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                    <InputOTPSlot index={5} className="h-10 w-10 rounded-md border-border/60 text-sm font-mono" />
                  </InputOTPGroup>
                </InputOTP>
              )}
            />
          </div>
          {errors.otp?.message && (
            <p className="text-center text-[11px] font-medium text-destructive mt-1">
              {errors.otp.message}
            </p>
          )}
        </div>

        {/* Continue Button */}
