  icon?: LucideIcon
  onClick: () => void
  variant?: "default" | "primary" | "outline" | "ghost" | "destructive"
  className?: string
  disabled?: boolean
  /** Show as icon only (no text) */
  iconOnly?: boolean
}

interface DataTableToolbarProps<TData> {
  table: Table<TData>
  searchColumnId?: string
  searchPlaceholder?: string
  filters?: FacetedFilterConfig[]
  bulkActions?: React.ReactNode
  title?: string
  /** @deprecated Use `actions` instead */
  onAddClick?: () => void
  /** Array of toolbar actions */
  actions?: ToolbarAction[]
  searchValue?: string
  onSearchChange?: (value: string) => void
  /** Base filename for CSV and JSON exports */
  exportFilename?: string
  /** Custom data supplier for export; defaults to filtered table rows */
  getExportData?: () => any[]
  /** Whether export dropdown is enabled (defaults to true) */
  enableExport?: boolean
}

export function DataTableToolbar<TData>({
  table,
  searchColumnId,
  searchPlaceholder = "Search...",
  filters = [],
  bulkActions,
  title = "Items",
  onAddClick,
  actions = [],
  searchValue,
  onSearchChange,
  exportFilename,
  getExportData,
  enableExport = true,
}: DataTableToolbarProps<TData>) {
  const t = useTranslations()
  const { dir } = useGetDirection()
  const isFiltered = table.getState().columnFilters.length > 0
  const selectedCount = table.getFilteredSelectedRowModel().rows.length

  const isControlledSearch = onSearchChange !== undefined
  const currentSearchValue = isControlledSearch
    ? (searchValue ?? "")
    : ((table.getColumn(searchColumnId ?? "")?.getFilterValue() as string) ??
      "")

  function handleSearchChange(value: string) {
    if (isControlledSearch) {
      onSearchChange?.(value)
    } else {
      table.getColumn(searchColumnId ?? "")?.setFilterValue(value)
    }
  }

  // Merge onAddClick into actions for backward compatibility
  const toolbarActions = [...actions]
  if (onAddClick) {
    const hasAddAction = toolbarActions.some(
      (action) => action.label === "Add" || action.label === "Create"
    )
    if (!hasAddAction) {
      toolbarActions.push({
        label: t("add"),
        icon: Plus,
        onClick: onAddClick,
        variant: "primary",
      })
    }
  }

  // Get button variant styles
  const getButtonVariant = (variant?: string) => {
    switch (variant) {
      case "primary":
        return "primary"
      case "destructive":
        return "destructive"
      case "outline":
        return "outline"
      case "ghost":
        return "ghost"
      default:
        return "default"
    }
  }

  if (selectedCount > 0 && bulkActions) {
    return (
      <div className="relative z-10 flex w-full items-center justify-between gap-3 p-4">
        <span className="font-medium">
          {t("selectedCount", { count: selectedCount })}
        </span>
        <div className="ml-auto flex gap-2">{bulkActions}</div>
      </div>
    )
  }

  return (
    <div className="flex flex-wrap items-center justify-between gap-3 px-4 py-3 border-b border-border/50 bg-card">
      <div className={cn(dir === "rtl" ? "md:pr-1" : "md:pl-1")}>
        <h3 className="text-base font-semibold tracking-tight text-foreground whitespace-nowrap capitalize">
          {title}
        </h3>
      </div>

      <div className="flex flex-wrap items-center gap-2.5 ml-auto">
        {(searchColumnId || isControlledSearch) && (
          <div className="relative w-full sm:w-60 md:w-72">
            <Search className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder={searchPlaceholder}
              value={currentSearchValue}
              onChange={(e) => handleSearchChange(e.target.value)}
              className="h-9 w-full rounded-lg border border-border/60 bg-background/60 pr-8 pl-9 text-xs placeholder:text-muted-foreground focus-visible:ring-1 focus-visible:ring-primary md:text-sm"
            />
            {currentSearchValue && (
              <button
                type="button"
                onClick={() => handleSearchChange("")}
                className="absolute top-1/2 right-2.5 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </button>
            )}
          </div>
        )}

        <DataTableFiltersPopover table={table} filters={filters} />

        {enableExport && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="outline"
                size="sm"
                className="h-9 px-3 text-xs rounded-lg gap-1.5 border-border/60 hover:bg-muted/60"
              >
                <Download className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">Export</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align={dir === "rtl" ? "start" : "end"} className="w-44">
              <DropdownMenuItem
                className="text-xs cursor-pointer gap-2"
                onClick={() => {
                  const data = getExportData
                    ? getExportData()
                    : table.getFilteredRowModel().rows.map((r) => r.original)
                  exportToCsv(
                    data,
                    exportFilename || `${title.toLowerCase().replace(/\s+/g, "-")}-export`
                  )
                }}
              >
                <FileSpreadsheet className="size-3.5 text-emerald-600" />
                <span>Export CSV (.csv)</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                className="text-xs cursor-pointer gap-2"
                onClick={() => {
                  const data = getExportData
                    ? getExportData()
                    : table.getFilteredRowModel().rows.map((r) => r.original)
                  exportToJson(
                    data,
                    exportFilename || `${title.toLowerCase().replace(/\s+/g, "-")}-export`
                  )
                }}
              >
                <FileCode className="size-3.5 text-blue-600" />
                <span>Export JSON (.json)</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        {/* Actions */}
        {toolbarActions.map((action, index) => {
          const Icon = action.icon
          const variant = getButtonVariant(action.variant)

          return (
            <Button
              key={`action-${index}`}
              size={action.iconOnly ? "icon" : "sm"}
              variant={variant as any}
              className={cn(
                action.iconOnly
                  ? "h-9 w-9 rounded-lg"
                  : "h-9 px-3 text-xs rounded-lg gap-1.5",
                action.className
              )}
              onClick={action.onClick}
              disabled={action.disabled}
            >
              {Icon && (
                <Icon className={action.iconOnly ? "size-4" : "h-3.5 w-3.5"} />
              )}
              {!action.iconOnly && action.label}
            </Button>
          )
        })}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  PaginationState,
  SortingState,
  VisibilityState,
  flexRender,
  getCoreRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Skeleton } from "@/components/ui/skeleton"
import {
  DataTableToolbar,
  FacetedFilterConfig,
  ToolbarAction,
} from "./data-table-toolbar"
import { Plus } from "@/components/ui/carbon/icons"
import { DataTablePagination } from "./data-table-pagination"
import { cn } from "@/lib/utils"
import { useTranslations } from "next-intl"

declare module "@tanstack/react-table" {
  interface ColumnMeta<TData, TValue> {
    className?: string
  }
}

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  searchColumnId?: string
  searchPlaceholder?: string
  filters?: FacetedFilterConfig[]
  bulkActions?: React.ReactNode
  emptyMessage?: string
  className?: string
  isLoading?: boolean
  isFetching?: boolean
  title?: string
  /** @deprecated Use `actions` instead */
  onAddClick?: () => void
  /** Array of toolbar actions */
  actions?: ToolbarAction[]

  manual?: boolean
  pageCount?: number
  rowCount?: number
  pagination?: PaginationState
  onPaginationChange?: OnChangeFn<PaginationState>
  columnFilters?: ColumnFiltersState
  onColumnFiltersChange?: OnChangeFn<ColumnFiltersState>
  sorting?: SortingState
  onSortingChange?: OnChangeFn<SortingState>
  searchValue?: string
  onSearchChange?: (value: string) => void
  renderAfterJsxToolbar?: () => React.ReactNode
  renderBeforeJsxToolbar?: () => React.ReactNode
  defaultColumnVisibility?: VisibilityState
  /** Custom export filename */
  exportFilename?: string
  /** Custom export data accessor */
  getExportData?: () => any[]
  /** Whether export is enabled (defaults to true) */
  enableExport?: boolean
}

export function DataTable<TData, TValue>({
  columns,
  data,
  searchColumnId,
  searchPlaceholder,
  filters,
  bulkActions,
  className,
  emptyMessage = "No results.",
  isLoading,
  isFetching,
  title,
  onAddClick,
  actions = [],
  manual = false,
  pageCount,
  rowCount,
  pagination: controlledPagination,
  onPaginationChange,
  columnFilters: controlledColumnFilters,
  onColumnFiltersChange,
  sorting: controlledSorting,
  onSortingChange,
  searchValue,
  onSearchChange,
  renderAfterJsxToolbar,
  renderBeforeJsxToolbar,
  defaultColumnVisibility,
  exportFilename,
  getExportData,
  enableExport = true,
}: DataTableProps<TData, TValue>) {
  const t = useTranslations()
  const [rowSelection, setRowSelection] = React.useState({})
  const [columnVisibility, setColumnVisibility] =
    React.useState<VisibilityState>(defaultColumnVisibility ?? {})

  const [internalColumnFilters, setInternalColumnFilters] =
    React.useState<ColumnFiltersState>([])
  const [internalSorting, setInternalSorting] = React.useState<SortingState>([])
  const [internalPagination, setInternalPagination] =
    React.useState<PaginationState>({ pageIndex: 0, pageSize: 10 })

  const columnFilters = manual
    ? (controlledColumnFilters ?? [])
    : internalColumnFilters
  const sorting = manual ? (controlledSorting ?? []) : internalSorting
  const paginationState = manual
    ? (controlledPagination ?? { pageIndex: 0, pageSize: 10 })
    : internalPagination

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      columnFilters,
      pagination: paginationState,
    },
    manualPagination: manual,
    manualFiltering: manual,
    manualSorting: manual,
    // TODO: sorting is temporarily disabled — remove this line to re-enable it.
    enableSorting: false,
    pageCount: manual ? (pageCount ?? -1) : undefined,
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onSortingChange: manual ? onSortingChange : setInternalSorting,
    onColumnFiltersChange: manual
      ? onColumnFiltersChange
      : setInternalColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onPaginationChange: manual ? onPaginationChange : setInternalPagination,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: manual ? undefined : getFilteredRowModel(),
    getPaginationRowModel: manual ? undefined : getPaginationRowModel(),
    getSortedRowModel: manual ? undefined : getSortedRowModel(),
    getFacetedUniqueValues: manual ? undefined : getFacetedUniqueValues(),
  })

  const skeletonRowCount = paginationState.pageSize || 10
  const visibleColumnsCount = table.getVisibleLeafColumns().length

  // Merge onAddClick into actions for backward compatibility
  const toolbarActions = React.useMemo(() => {
    const mergedActions = [...actions]
    if (onAddClick) {
      // Check if there's already an action with the same label
      const hasAddAction = mergedActions.some(
        (action) => action.label === "Add" || action.label === "Create"
      )
      if (!hasAddAction) {
        mergedActions.push({
          label: t("add"),
          icon: Plus,
          onClick: onAddClick,
          variant: "primary",
        })
      }
    }
    return mergedActions
  }, [actions, onAddClick, t])

  return (
    <div
      className={cn(
        "relative flex w-full flex-col",
        className
      )}
    >
      <div className="flex w-full flex-col rounded-xl border border-border/60 bg-card shadow-xs overflow-hidden">
        {renderBeforeJsxToolbar && renderBeforeJsxToolbar()}
        <DataTableToolbar
          table={table}
          title={title}
          actions={toolbarActions}
          searchColumnId={searchColumnId}
          searchPlaceholder={searchPlaceholder}
          filters={filters}
          bulkActions={bulkActions}
          searchValue={manual ? searchValue : undefined}
          onSearchChange={manual ? onSearchChange : undefined}
          exportFilename={exportFilename}
          getExportData={getExportData}
          enableExport={enableExport}
        />
        {renderAfterJsxToolbar && renderAfterJsxToolbar()}
        <div className="w-full overflow-auto">
          <Table>
            <TableHeader>
              {table.getHeaderGroups().map((headerGroup) => (
                <TableRow key={headerGroup.id} className="hover:bg-transparent">
                  {headerGroup.headers.map((header) => (
                    <TableHead
                      key={header.id}
                      className={cn(header.column.columnDef.meta?.className)}
                    >
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  ))}
                </TableRow>
              ))}
            </TableHeader>
            <TableBody>
              {isLoading ? (
                Array.from({ length: skeletonRowCount }).map((_, rowIndex) => (
                  <TableRow
                    key={`skeleton-row-${rowIndex}`}
                    className="hover:bg-transparent"
                  >
                    {Array.from({ length: visibleColumnsCount }).map(
                      (_, colIndex) => (
                        <TableCell key={`skeleton-cell-${colIndex}`}>
                          <Skeleton className="h-9 w-full max-w-[140px] bg-background" />
                        </TableCell>
                      )
                    )}
                  </TableRow>
                ))
              ) : table.getRowModel().rows.length ? (
                table.getRowModel().rows.map((row) => (
                  <TableRow
                    key={row.id}
                    data-state={row.getIsSelected() && "selected"}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell
                        key={cell.id}
                        className={cn(cell.column.columnDef.meta?.className)}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext()
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={columns.length}
                    className="h-24 text-center text-muted-foreground"
                  >
                    {emptyMessage}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
        <DataTablePagination
          table={table}
          total={manual ? rowCount : undefined}
        />
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { FileItem, FileVisibility, FileType } from "@/types/files"
import { useTranslations } from "next-intl"
import {
  Download,
  File,
  FileText,
  Image as ImageIcon,
  Music,
  Video,
  AlertCircle,
} from "@/components/ui/carbon/icons"
import { VISIBILITY_COLORS, VISIBILITY_ICONS } from "./files-columns"

interface FileDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  file: FileItem | null
  mode: "rename" | "move" | "details" | "visibility" | "share" | "preview"
  onConfirm?: (file: FileItem, data: any) => void
  onDownload?: (file: FileItem) => void
}

// Helper: Get file icon based on type
const getFileIcon = (type: FileType) => {
  switch (type) {
    case FileType.IMAGE:
      return <ImageIcon className="h-16 w-16 text-purple-500" />
    case FileType.VIDEO:
      return <Video className="h-16 w-16 text-pink-500" />
    case FileType.AUDIO:
      return <Music className="h-16 w-16 text-emerald-500" />
    case FileType.DOCUMENT:
      return <FileText className="h-16 w-16 text-blue-500" />
    default:
      return <File className="h-16 w-16 text-muted-foreground" />
  }
}

// Helper: Get file type label
const getFileTypeLabel = (type: FileType) => {
  switch (type) {
    case FileType.IMAGE:
      return "Image"
    case FileType.VIDEO:
      return "Video"
    case FileType.AUDIO:
      return "Audio"
    case FileType.DOCUMENT:
      return "Document"
    case FileType.ARCHIVE:
      return "Archive"
    case FileType.FOLDER:
      return "Folder"
    default:
      return "File"
  }
}

export function FileDialog({
  open,
  onOpenChange,
  file,
  mode,
  onConfirm,
  onDownload,
}: FileDialogProps) {
  const t = useTranslations()
  const [newName, setNewName] = useState(file?.name || "")
  const [selectedVisibility, setSelectedVisibility] = useState<FileVisibility>(
    file?.visibility || FileVisibility.PRIVATE
  )
  const [imageError, setImageError] = useState(false)

  if (!file) return null

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return "0 B"
    const k = 1024
    const sizes = ["B", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`
  }

  const handleConfirm = () => {
    if (mode === "rename") {
      onConfirm?.(file, { name: newName })
    } else if (mode === "visibility") {
      onConfirm?.(file, { visibility: selectedVisibility })
    } else {
      onConfirm?.(file, {})
    }
  }

  const handleDownload = () => {
    if (onDownload) {
      onDownload(file)
    }
  }

  // Render file preview based on type
  const renderFilePreview = () => {
    const isImage = file.type === FileType.IMAGE
    const isVideo = file.type === FileType.VIDEO
    const isAudio = file.type === FileType.AUDIO
    const isDocument = file.type === FileType.DOCUMENT
    const isArchive = file.type === FileType.ARCHIVE
    const isFolder = file.type === FileType.FOLDER

    const fileUrl = file.cloudinaryUrl || `/api/files/${file.id}/stream`

    // Image Preview
    if (isImage) {
      return (
        <div className="flex flex-col items-center gap-4">
          <div className="relative w-full overflow-hidden rounded-lg border bg-muted/20">
            {!imageError ? (
              <img
                src={fileUrl}
                alt={file.name}
                className="max-h-[400px] w-full object-contain"
                onError={() => setImageError(true)}
              />
            ) : (
              <div className="flex min-h-[200px] w-full flex-col items-center justify-center p-8 text-center">
                <AlertCircle className="h-12 w-12 text-muted-foreground" />
                <p className="mt-2 text-sm text-muted-foreground">
                  {t("imageNotAvailable")}
                </p>
                <Button
                  variant="outline"
                  size="sm"
                  className="mt-4"
                  onClick={handleDownload}
                >
                  <Download className="mr-2 h-4 w-4" />
                  {t("download")}
                </Button>
              </div>
            )}
          </div>
          <p className="text-sm text-muted-foreground">
            {formatFileSize(file.size)} •{" "}
            {t(getFileTypeLabel(file.type).toLowerCase())}
          </p>
        </div>
      )
    }

    // Video Preview
    if (isVideo) {
      return (
        <div className="flex flex-col items-center gap-4">
          <div className="w-full overflow-hidden rounded-lg border bg-muted/20">
            <video
              controls
              className="max-h-[400px] w-full"
              poster={file.thumbnail}
              onError={(e) => {
                e.currentTarget.style.display = "none"
                const parent = e.currentTarget.parentElement
                if (parent) {
                  const fallback = document.createElement("div")
                  fallback.className =
                    "flex min-h-[200px] flex-col items-center justify-center p-8 text-center"
                  fallback.innerHTML = `
                    <div class="text-6xl mb-4">🎬</div>
                    <p class="text-sm text-muted-foreground">${t("videoNotAvailable")}</p>
                    <button class="mt-4 inline-flex items-center justify-center rounded-md border px-4 py-2 text-sm font-medium">${t("download")}</button>
                  `
                  parent.appendChild(fallback)
                  const btn = fallback.querySelector("button")
                  if (btn) btn.onclick = handleDownload
                }
              }}
            >
              <source src={fileUrl} type={file.mimeType || "video/mp4"} />
              {t("videoNotSupported")}
            </video>
          </div>
          <p className="text-sm text-muted-foreground">
            {formatFileSize(file.size)} • {t("video")}
          </p>
        </div>
      )
    }

    // Audio Preview
    if (isAudio) {
      return (
        <div className="flex flex-col items-center gap-4">
          <div className="w-full rounded-lg border bg-muted/20 p-6">
            <div className="flex flex-col items-center gap-4">
              <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/10">
                <Music className="h-10 w-10 text-primary" />
              </div>
              <div className="text-center">
                <p className="font-medium">{file.name}</p>
                <p className="text-sm text-muted-foreground">
                  {formatFileSize(file.size)} • {t("audio")}
                </p>
              </div>
              <audio
                controls
                className="w-full max-w-md"
                onError={handleDownload}
              >
                <source src={fileUrl} type={file.mimeType || "audio/mpeg"} />
                {t("audioNotSupported")}
              </audio>
            </div>
          </div>
        </div>
      )
    }

    // Document Preview (PDF, DOCX, etc.)
    if (isDocument) {
      const isPDF = file.extension?.toLowerCase() === "pdf"

      if (isPDF) {
        return (
          <div className="flex flex-col items-center gap-4">
            <div className="w-full overflow-hidden rounded-lg border bg-muted/20">
              <iframe
                src={`${fileUrl}#toolbar=0`}
                className="h-[400px] w-full"
                title={file.name}
                sandbox="allow-scripts allow-modals"
              />
            </div>
            <p className="text-sm text-muted-foreground">
              {formatFileSize(file.size)} • {t("pdf")}
            </p>
          </div>
        )
      }

      return (
        <div className="flex flex-col items-center gap-4">
          <div className="flex w-full flex-col items-center justify-center rounded-lg border bg-muted/20 p-8">
            {getFileIcon(file.type)}
            <p className="mt-4 text-lg font-medium">{file.name}</p>
            <p className="text-sm text-muted-foreground">
              {formatFileSize(file.size)} •{" "}
              {file.extension?.toUpperCase() || t("document")}
            </p>
            <Button className="mt-4" variant="outline" onClick={handleDownload}>
              <Download className="mr-2 h-4 w-4" />
              {t("download")}
            </Button>
          </div>
        </div>
      )
    }

    // Archive Preview
    if (isArchive) {
      return (
        <div className="flex flex-col items-center gap-4">
          <div className="flex w-full flex-col items-center justify-center rounded-lg border bg-muted/20 p-8">
            <div className="mb-4 text-6xl">📦</div>
            <p className="text-lg font-medium">{file.name}</p>
            <p className="text-sm text-muted-foreground">
              {formatFileSize(file.size)} •{" "}
              {file.extension?.toUpperCase() || t("archive")}
            </p>
            <Button className="mt-4" variant="outline" onClick={handleDownload}>
              <Download className="mr-2 h-4 w-4" />
              {t("download")}
            </Button>
          </div>
        </div>
      )
    }

    // Folder Preview
    if (isFolder) {
      return (
        <div className="flex flex-col items-center gap-4">
          <div className="flex w-full flex-col items-center justify-center rounded-lg border bg-muted/20 p-8">
            <div className="mb-4 text-6xl">📁</div>
            <p className="text-lg font-medium">{file.name}</p>
            <p className="text-sm text-muted-foreground">{t("folder")}</p>
          </div>
        </div>
      )
    }

    // Default / Other
    return (
      <div className="flex flex-col items-center gap-4">
        <div className="flex w-full flex-col items-center justify-center rounded-lg border bg-muted/20 p-8">
          {getFileIcon(file.type)}
          <p className="mt-4 text-lg font-medium">{file.name}</p>
          <p className="text-sm text-muted-foreground">
            {formatFileSize(file.size)} •{" "}
            {file.extension?.toUpperCase() || t("file")}
          </p>
          <Button className="mt-4" variant="outline" onClick={handleDownload}>
            <Download className="mr-2 h-4 w-4" />
            {t("download")}
          </Button>
        </div>
      </div>
    )
  }

  const renderContent = () => {
    switch (mode) {
      case "rename":
        return (
          <div className="space-y-2">
            <Label>{t("fileName")}</Label>
            <Input
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder={t("enterNewName")}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  handleConfirm()
                }
              }}
            />
          </div>
        )

      case "visibility":
        return (
          <div className="space-y-2">
            <Label>{t("visibility")}</Label>
            <Select
              value={selectedVisibility}
              onValueChange={(value: FileVisibility) =>
                setSelectedVisibility(value)
              }
            >
              <SelectTrigger className="w-full py-6">
                <SelectValue placeholder={t("selectVisibility")} />
              </SelectTrigger>
              <SelectContent>
                {Object.values(FileVisibility).map((visibility) => (
                  <SelectItem key={visibility} value={visibility}>
                    <div className="flex items-center gap-2">
                      <Badge
                        variant="outline"
                        className={`${VISIBILITY_COLORS[visibility]} border-transparent`}
                      >
                        <span className="flex items-center gap-1">
                          {VISIBILITY_ICONS[visibility]}
                          {t(visibility.toLowerCase())}
                        </span>
                      </Badge>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )

      case "details":
        return (
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label className="text-muted-foreground">{t("name")}</Label>
              <p className="font-medium">{file.name}</p>
            </div>
            <div>
              <Label className="text-muted-foreground">{t("type")}</Label>
              <p className="font-medium capitalize">
                {t(getFileTypeLabel(file.type).toLowerCase())}
              </p>
            </div>
            <div>
              <Label className="text-muted-foreground">{t("size")}</Label>
              <p className="font-medium">{formatFileSize(file.size)}</p>
            </div>
            <div>
              <Label className="text-muted-foreground">{t("visibility")}</Label>
              <div className="mt-1">
                <Badge
                  variant="outline"
                  className={`${VISIBILITY_COLORS[file.visibility]} border-transparent`}
                >
                  <span className="flex items-center gap-1">
                    {VISIBILITY_ICONS[file.visibility]}
                    {t(file.visibility.toLowerCase())}
                  </span>
                </Badge>
              </div>
            </div>
            <div>
              <Label className="text-muted-foreground">{t("owner")}</Label>
              <p className="font-medium">{file.owner.name}</p>
            </div>
            <div>
              <Label className="text-muted-foreground">{t("modified")}</Label>
              <p className="font-medium">
                {new Date(file.modifiedAt).toLocaleString()}
              </p>
            </div>
            {file.projectName && (
              <div className="col-span-2">
                <Label className="text-muted-foreground">{t("project")}</Label>
                <p className="font-medium">{file.projectName}</p>
              </div>
            )}
            {file.downloadedCount !== undefined && (
              <div className="col-span-2">
                <Label className="text-muted-foreground">
                  {t("downloads")}
                </Label>
                <p className="font-medium">{file.downloadedCount}</p>
              </div>
            )}
          </div>
        )

      case "share":
        return (
          <div className="rounded-lg border p-4">
            <div className="flex items-center gap-3">
              <span className="text-2xl">🔗</span>
              <div className="flex-1">
                <p className="text-sm font-medium">{t("shareLink")}</p>
                <p className="text-xs break-all text-muted-foreground">
                  {`${window.location.origin}/share/${file.id}`}
                </p>
              </div>
            </div>
          </div>
        )

      case "preview":
        return <div className="py-2">{renderFilePreview()}</div>

      default:
        return null
    }
  }

  const getTitle = () => {
    switch (mode) {
      case "rename":
        return t("renameFile")
      case "visibility":
        return t("changeVisibility")
      case "details":
        return t("fileDetails")
      case "share":
        return t("shareFile")
      case "preview":
        return t("previewFile")
      default:
        return ""
    }
  }

  const getDescription = () => {
    switch (mode) {
      case "rename":
        return t("renameFileDescription", { name: file.name })
      case "visibility":
        return t("changeVisibilityDescription", { name: file.name })
      case "details":
        return t("fileDetailsDescription", { name: file.name })
      case "share":
        return t("shareFileDescription", { name: file.name })
      case "preview":
        return t("previewFileDescription", { name: file.name })
      default:
        return ""
    }
  }

  const showFooter = mode !== "details" && mode !== "preview"

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{getTitle()}</DialogTitle>
          <DialogDescription>{getDescription()}</DialogDescription>
        </DialogHeader>

        <div className="px-4 py-3">{renderContent()}</div>

        {showFooter && (
          <DialogFooter>
            <Button
              className="flex-1"
              variant="destructive"
              onClick={() => onOpenChange(false)}
            >
              {t("cancel")}
            </Button>
            <Button
              className="flex-1"
              onClick={handleConfirm}
              variant="primary"
            >
              {mode === "rename" && t("rename")}
              {mode === "visibility" && t("change")}
              {mode === "share" && t("share")}
            </Button>
          </DialogFooter>
        )}

        {mode === "details" && (
          <DialogFooter>
            <Button
              variant="destructive"
              className="flex-1"
              onClick={() => onOpenChange(false)}
            >
              {t("close")}
            </Button>
          </DialogFooter>
        )}

        {mode === "preview" && (
          <DialogFooter>
            <Button
              className="flex-1"
              variant="destructive"
              onClick={() => onOpenChange(false)}
            >
              {t("close")}
            </Button>
            <Button
              className="flex-1"
              variant="primary"
              onClick={handleDownload}
            >
              <Download className="mr-2 h-4 w-4" />
              {t("download")}
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  )
}

