"use client"

import { useMemo, useState } from "react"
import { useTranslations } from "next-intl"
import { DataTable } from "@/components/shared/data-table-chunks/data-table"
import {
  uploadFileApi,
  deleteFileApi,
  renameFileApi,
  toggleStarFileApi,
  fetchFilesSummaryApi,
  updateFileApi,
} from "@/lib/api/files-api"
import { FileItem, FileType, FileVisibility } from "@/types/files"
import { useFilesTable } from "@/hooks/files/use-files-table"
import { useEntityMutations } from "@/hooks/tables/use-table-entity-mutations"
import { ConfirmAlertDialog } from "@/components/ui/confirm-alert-dialog"
import { toast } from "@/lib/utils/toast"
import { FileUploadDialog } from "@/components/ui/upload-file"
import { Upload } from "@/components/ui/carbon/icons"
import { useQuery } from "@tanstack/react-query"
import { getFilesColumns } from "./files-columns"
import { FilesSummaryCards } from "./files-summary-cards"
import { FileDialog } from "./file-dialog"

type PendingAction = { type: "delete"; file: FileItem } | null

type FileDialogMode =
  "rename" | "move" | "details" | "visibility" | "share" | "preview" | null

export default function FilesPage() {
  const t = useTranslations()
  const [uploadOpen, setUploadOpen] = useState(false)
  const [isUploading, setIsUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState<Record<string, number>>(
    {}
  )

  const [dialogOpen, setDialogOpen] = useState(false)
  const [dialogMode, setDialogMode] = useState<FileDialogMode>(null)
  const [selectedFile, setSelectedFile] = useState<FileItem | null>(null)

  const {
    items: files,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useFilesTable()

  const { data: summaryData, refetch: refetchSummary } = useQuery({
    queryKey: ["files-summary"],
    queryFn: fetchFilesSummaryApi,
    staleTime: 60 * 1000,
  })

  const { remove, isDeleting } = useEntityMutations({
    queryKey: "files",
    createFn: () => Promise.resolve({}),
    updateFn: () => Promise.resolve({}),
    deleteFn: deleteFileApi,
    entityLabel: "File",
  })

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)

  const handleUpload = async (files: File[], projectId?: string) => {
    setIsUploading(true)
    setUploadProgress({})

    for (const file of files) {
      const formData = new FormData()
      formData.append("file", file)
      if (projectId) {
        formData.append("projectId", projectId)
      }

      try {
        for (let progress = 0; progress <= 100; progress += 10) {
          setUploadProgress((prev) => ({
            ...prev,
            [file.name]: progress,
          }))
          await new Promise((resolve) => setTimeout(resolve, 100))
        }

        await uploadFileApi(formData)
        toast.success(`${file.name} ${t("uploadedSuccessfully")}`)
      } catch (_error) {
        setUploadProgress((prev) => ({
          ...prev,
          [`${file.name}_error`]: 1,
        }))
        toast.error(`${file.name} ${t("uploadFailed")}`)
      }
    }

    setIsUploading(false)
    setUploadProgress({})
    setUploadOpen(false)
    refresh()
    refetchSummary()
  }

  const handleDownload = async (file: FileItem) => {
    try {
      const { cloudinaryUrl: url, name: filename } = file
      if (!url) return

      const response = await fetch(url)
      if (!response.ok) throw new Error("Failed to fetch file")
      const blob = await response.blob()
      const blobUrl = window.URL.createObjectURL(blob)

      const link = document.createElement("a")
      link.addEventListener("click", (e) => e.stopPropagation())
      link.href = blobUrl
      link.download = filename
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)

      // Release the blob from memory now that the download has been triggered
      window.URL.revokeObjectURL(blobUrl)

      toast.success(t("downloadStarted"))
    } catch (error) {
      console.error("Download error:", error)
      toast.error(t("downloadFailed"))
    }
  }

  const openDialog = (mode: FileDialogMode, file: FileItem) => {
    setSelectedFile(file)
    setDialogMode(mode)
    setDialogOpen(true)
  }

  const handleDialogConfirm = async (file: FileItem, data: Record<string, unknown>) => {
    try {
      if (dialogMode === "rename") {
        await renameFileApi(file.id, data.name as string)
        toast.success(t("fileRenamed"))
      } else if (dialogMode === "visibility") {
        await updateFileApi(file.id, { visibility: data.visibility as FileVisibility })
        toast.success(t("visibilityChanged"))
      } else if (dialogMode === "share") {
        toast.success(t("shareLinkCopied"))
      } else if (dialogMode === "preview") {
        await handleDownload(file)
      }

      refresh()
      refetchSummary()
      setDialogOpen(false)
      setSelectedFile(null)
    } catch (_error) {
      toast.error(t("actionFailed"))
    }
  }

  const handleStar = async (file: FileItem) => {
    try {
      await toggleStarFileApi(file.id)
      toast.success(file.starred ? t("unstarred") : t("starred"))
      refresh()
      refetchSummary()
    } catch (_error) {
      toast.error(t("starFailed"))
    }
  }

  const handleConfirm = async () => {
    if (!pendingAction) return

    if (pendingAction.type === "delete") {
      remove(pendingAction.file.id, {
        onSuccess: () => {
          setPendingAction(null)
          refetchSummary()
        },
      })
    }
  }

  const columns = useMemo(
    () =>
      getFilesColumns(
        {
          onPreview: (file) => openDialog("preview", file),
          onDownload: handleDownload,
          onStar: handleStar,
          onRename: (file) => openDialog("rename", file),
          onDelete: (file) => setPendingAction({ type: "delete", file }),
          onShare: (file) => openDialog("share", file),
          onDetails: (file) => openDialog("details", file),
          onChangeVisibility: (file) => openDialog("visibility", file),
          onCopy: async (file) => {
            try {
              await navigator.clipboard.writeText(file.name)
              toast.success(t("copied"))
            } catch (_error) {
              toast.error(t("copyFailed"))
            }
          },
        },
        t
      ),
    [t, handleDownload, handleStar]
  )

  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.file.name

    return {
      title: t("deleteFile"),
      description: t("deleteFileConfirmation", { name }),
      confirmLabel: t("delete"),
      destructive: true,
      isLoading: isDeleting,
    }
  }, [pendingAction, isDeleting, t])

  return (
    <div className="p-4 md:p-6 space-y-6">
      <FilesSummaryCards
        files={files}
        summary={summaryData}
        isLoading={isLoading}
      />

      <DataTable
        manual
        title={t("files")}
        isLoading={isLoading}
        isFetching={isFetching}
        columns={columns}
        data={files}
        rowCount={totalItems}
        pageCount={pageCount}
        pagination={pagination}
        onPaginationChange={setPagination}
        columnFilters={columnFilters}
        onColumnFiltersChange={setColumnFilters}
        sorting={sorting}
        onSortingChange={setSorting}
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder={t("searchFiles")}
        actions={[
          {
            label: t("upload"),
            icon: Upload,
            onClick: () => setUploadOpen(true),
            variant: "primary",
            iconOnly: true,
          },
        ]}
        filters={[
          {
            columnId: "type",
            title: t("type"),
            options: [
              { label: t("documents"), value: FileType.DOCUMENT },
              { label: t("images"), value: FileType.IMAGE },
              { label: t("videos"), value: FileType.VIDEO },
              { label: t("archives"), value: FileType.ARCHIVE },
              { label: t("others"), value: FileType.OTHER },
            ],
          },
          {
            columnId: "visibility",
            title: t("visibility"),
            options: [
              { label: t("private"), value: FileVisibility.PRIVATE },
              { label: t("team"), value: FileVisibility.TEAM },
              { label: t("public"), value: FileVisibility.PUBLIC },
            ],
          },
        ]}
      />

      <FileUploadDialog
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        onUpload={handleUpload}
        isUploading={isUploading}
        uploadProgress={uploadProgress}
        projects={[
          { id: "p1", name: t("websiteRedesign") },
          { id: "p2", name: t("mobileAppDevelopment") },
          { id: "p3", name: t("dashboardAnalytics") },
          { id: "p4", name: t("marketingCampaign") },
        ]}
      />

      <FileDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        file={selectedFile}
        mode={dialogMode || "details"}
        onDownload={handleDownload}
        onConfirm={handleDialogConfirm}
      />

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </div>
  )
}

// components/files/files-summary-cards.tsx

"use client"

import { useMemo } from "react"
import { useTranslations } from "next-intl"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { File, FileText, Image, Video, Archive, Upload } from "@/components/ui/carbon/icons"
import { FileItem, FileType, FileSummary } from "@/types/files"

interface FilesSummaryCardsProps {
  files?: FileItem[]
  summary?: FileSummary
  isLoading?: boolean
  useApi?: boolean
}

export function FilesSummaryCards({
  files,
  summary: apiSummary,
  isLoading = false,
  useApi = true,
}: FilesSummaryCardsProps) {
  const t = useTranslations()

  const localSummary = useMemo(() => {
    if (!files || files.length === 0) {
      return {
        totalFiles: 0,
        totalSize: 0,
        documents: 0,
        images: 0,
        videos: 0,
        archives: 0,
        others: 0,
      }
    }

    let totalFiles = 0
    let totalSize = 0
    let documents = 0
    let images = 0
    let videos = 0
    let archives = 0
    let others = 0

    files.forEach((file) => {
      if (file.type === FileType.FOLDER) return
      totalFiles += 1
      totalSize += file.size

      switch (file.type) {
        case FileType.DOCUMENT:
          documents += 1
          break
        case FileType.IMAGE:
          images += 1
          break
        case FileType.VIDEO:
          videos += 1
          break
        case FileType.ARCHIVE:
          archives += 1
          break
        default:
          others += 1
          break
      }
    })

    return {
      totalFiles,
      totalSize,
      documents,
      images,
      videos,
      archives,
      others,
    }
  }, [files])

  const summary = useApi ? apiSummary : localSummary

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return "0 B"
    const k = 1024
    const sizes = ["B", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`
  }

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
        {[1, 2, 3, 4].map((i) => (
          <Card key={i} className="animate-pulse h-full flex flex-col justify-between">
            <CardHeader className="p-5 pb-3">
              <div className="h-4 w-24 rounded bg-muted" />
              <div className="mt-2 h-8 w-16 rounded bg-muted" />
            </CardHeader>
            <CardFooter className="px-5 py-3 pt-0 border-t-0 mt-auto">
              <div className="h-3 w-32 rounded bg-muted" />
            </CardFooter>
          </Card>
        ))}
      </div>
    )
  }

  if (!summary) {
    return (
      <div className="p-4 text-center text-muted-foreground">
        {t("noDataAvailable")}
      </div>
    )
  }

  const cards = [
    {
      key: "total",
      title: t("totalFiles"),
      value: summary.totalFiles.toString(),
      valueClassName: "",
      badge: {
        label: formatFileSize(summary.totalSize),
        icon: File,
        variant: "outline" as const,
        className: "gap-1",
      },
      footer: {
        icon: Upload,
        text: t("totalFilesDescription"),
        subtext: t("totalFilesSubtext"),
        className: "",
      },
    },
    {
      key: "documents",
      title: t("documents"),
      value: summary.documents.toString(),
      valueClassName: "text-blue-600",
      badge: {
        label: t("documents"),
        icon: FileText,
        variant: "outline" as const,
        className: "gap-1 border-blue-500/20 bg-blue-500/10 text-blue-600",
      },
      footer: {
        icon: FileText,
        text: t("documentsDescription"),
        subtext: t("documentsSubtext"),
        className: "text-blue-600",
      },
    },
    {
      key: "images",
      title: t("images"),
      value: summary.images.toString(),
      valueClassName: "text-purple-600",
      badge: {
        label: t("images"),
        icon: Image,
        variant: "outline" as const,
        className:
          "gap-1 border-purple-500/20 bg-purple-500/10 text-purple-600",
      },
      footer: {
        icon: Image,
        text: t("imagesDescription"),
        subtext: t("imagesSubtext"),
        className: "text-purple-600",
      },
    },
    {
      key: "media",
      title: t("mediaArchives"),
      value: (summary.videos + summary.archives).toString(),
      valueClassName: "text-orange-600",
      badge: {
        label: t("media"),
        icon: Video,
        variant: "outline" as const,
        className:
          "gap-1 border-orange-500/20 bg-orange-500/10 text-orange-600",
      },
      footer: {
        icon: Archive,
        text: t("mediaDescription"),
        subtext: t("mediaSubtext"),
        className: "text-orange-600",
      },
    },
  ]

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
      {cards.map((card) => (
        <Card key={card.key} className="h-full flex flex-col justify-between">
          <CardHeader className="p-5 pb-3">
            <div className="flex items-center justify-between gap-2">
              <CardDescription className="text-xs font-medium uppercase tracking-wider">{card.title}</CardDescription>
              <Badge
                variant={card.badge.variant}
                className={card.badge.className}
              >
                <card.badge.icon className="size-3" />
                {card.badge.label}
              </Badge>
            </div>
            <CardTitle
              className={`text-2xl font-bold font-mono tabular-nums @[250px]/card:text-3xl mt-2 ${card.valueClassName}`}
            >
              {card.value}
            </CardTitle>
          </CardHeader>
          <CardFooter className="px-5 py-3 pt-0 border-t-0 flex items-center gap-1.5 text-xs text-muted-foreground mt-auto">
            <card.footer.icon className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="truncate font-medium">{card.footer.text}</span>
          </CardFooter>
        </Card>
      ))}
    </div>
  )
}

"use client"

import { Invoice } from "@/types/invoices"
import { Button } from "@/components/ui/button"
import { Download, Send } from "@/components/ui/carbon/icons"
import { useTranslations, useLocale } from "next-intl"

interface InvoicePreviewProps {
  invoice: Invoice
}

export function InvoicePreview({ invoice }: InvoicePreviewProps) {
  const t = useTranslations()
  const locale = useLocale()

  const formatCurrency = (value: number | string | undefined | null) => {
    const n = typeof value === "number" ? value : Number(value ?? 0)
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency: "USD", // swap for invoice.currency if/when you add one
    }).format(Number.isFinite(n) ? n : 0)
  }

  const formatDate = (value: Date | string | undefined | null) => {
    if (!value) return "—"
    const d = new Date(value)
    return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString(locale)
  }

  // user may or may not be populated depending on the API call that fetched this invoice
  const customerName =
    typeof invoice.user === "object" && invoice.user !== null
      ? invoice.user.name
      : t("unknownCustomer")
  const customerEmail =
    typeof invoice.user === "object" && invoice.user !== null
      ? invoice.user.email
      : null

  return (
    <div className="space-y-6 p-3 py-0">
      {/* Invoice Header */}
      <div className="flex items-start justify-between">
        <div>
          <h2 className="text-2xl font-bold">{invoice.invoiceNumber}</h2>
          <p className="text-sm text-muted-foreground">
            {t("invoiceDate")}: {formatDate(invoice.date)}
          </p>
          {invoice.dueDate && (
            <p className="text-sm text-muted-foreground">
              {t("dueDate")}: {formatDate(invoice.dueDate)}
            </p>
          )}
        </div>
        <div className="text-right">
          <p className="text-sm font-medium">{t("yourCompany")}</p>
          <p className="text-sm text-muted-foreground">company@example.com</p>
        </div>
      </div>

      {/* Customer Info */}
      <div className="rounded-md border bg-background p-3">
        <p className="text-sm font-medium">{t("customer")}</p>
        <p className="text-base font-semibold">{customerName}</p>
        {customerEmail && (
          <p className="text-sm text-muted-foreground">{customerEmail}</p>
        )}
      </div>

      {/* Items Table */}
      <div className="rounded-md border bg-background">
        <table className="w-full">
          <thead className="border-b bg-muted/50">
            <tr>
              <th className="px-4 py-2 text-left text-sm font-medium">
                {t("description")}
              </th>
              <th className="px-4 py-2 text-right text-sm font-medium">
                {t("quantity")}
              </th>
              <th className="px-4 py-2 text-right text-sm font-medium">
                {t("unitPrice")}
              </th>
              <th className="px-4 py-2 text-right text-sm font-medium">
                {t("total")}
              </th>
            </tr>
          </thead>
          <tbody>
            {invoice.items.length > 0 ? (
              invoice.items.map((item, index) => (
                <tr
                  key={(item as any).id ?? (item as any)._id ?? index}
                  className="border-b last:border-0"
                >
                  <td className="px-4 py-2 text-sm">{item.description}</td>
                  <td className="px-4 py-2 text-right text-sm">
                    {item.quantity}
                  </td>
                  <td className="px-4 py-2 text-right text-sm">
                    {formatCurrency(item.unitPrice)}
                  </td>
                  <td className="px-4 py-2 text-right text-sm font-medium">
                    {formatCurrency(item.total)}
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td
                  colSpan={4}
                  className="px-4 py-6 text-center text-sm text-muted-foreground"
                >
                  {t("noItems")}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Totals */}
      <div className="flex flex-col items-end space-y-2 px-2">
        <div className="flex w-full justify-between text-sm">
          <span className="text-muted-foreground">{t("subtotal")}</span>
          <span>{formatCurrency(invoice.subtotal)}</span>
        </div>
        <div className="flex w-full justify-between text-sm">
          <span className="text-muted-foreground">{t("tax")}</span>
          <span>{formatCurrency(invoice.tax)}</span>
        </div>
        <div className="flex w-full justify-between border-t pt-2 text-lg font-bold">
          <span>{t("total")}</span>
          <span>{formatCurrency(invoice.total)}</span>
        </div>
      </div>

      {/* Notes */}
      {invoice.notes && (
        <div className="rounded-md border bg-background p-3">
          <p className="text-sm font-medium">{t("notes")}</p>
          <p className="text-sm text-muted-foreground">{invoice.notes}</p>
        </div>
      )}
    </div>
  )
}

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { DataTableColumnHeader } from "@/components/shared/data-table-chunks/data-table-column-header"
import {
  DataTableRowActions,
  RowAction,
} from "@/components/shared/data-table-chunks/data-table-row-actions"
import { StatusBadge } from "@/components/ui/status-badge"
import { Invoice, InvoiceMethod, InvoiceStatus } from "@/types/invoices"
import {
  Eye,
  Send,
  Download,
  Ban,
  CheckCircle,
  Pencil,
  Copy,
  Printer,
  XCircle,
  Bell,
} from "@/components/ui/carbon/icons"
import { SpaceAvatar } from "@/components/ui/space-avatar"

export interface InvoicesColumnActions {
  onView: (invoice: Invoice) => void
  onEdit: (invoice: Invoice) => void
  onDownload: (invoice: Invoice) => void
  onSend: (invoice: Invoice) => void
  onMarkAsPaid: (invoice: Invoice) => void
  onDelete: (invoice: Invoice) => void
  onDuplicate?: (invoice: Invoice) => void
  onPrint?: (invoice: Invoice) => void
  onCancel?: (invoice: Invoice) => void
  onSendReminder?: (invoice: Invoice) => void
}

export function getInvoicesColumns(
  actions: InvoicesColumnActions,
  t: (key: string) => string
): ColumnDef<Invoice, any>[] {
  const STATUS_CONFIG: Record<
    InvoiceStatus,
    { label: string; className: string }
  > = {
    [InvoiceStatus.PAID]: {
      label: t("paid"),
      className:
        "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-transparent",
    },
    [InvoiceStatus.PENDING]: {
      label: t("pending"),
      className:
        "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-transparent",
    },
    [InvoiceStatus.OVERDUE]: {
      label: t("overdue"),
      className: "bg-destructive/10 text-destructive border-transparent",
    },
    [InvoiceStatus.CANCELLED]: {
      label: t("cancelled"),
      className: "bg-muted text-muted-foreground border-transparent",
    },
    [InvoiceStatus.DRAFT]: {
      label: t("draft"),
      className: "bg-muted text-muted-foreground border-transparent",
    },
  }

  return [
    {
      id: "customer",
      accessorFn: (row) => row.user.name,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("customer")} />
      ),
      cell: ({ row }) => {
        const invoice = row.original
        return (
          <div className="flex items-center gap-3">
            <SpaceAvatar
              name={invoice.user.name}
              profileColor={invoice.user.profileColor}
              src={invoice.user.avatar || ""}
              size="sm"
            />
            <div>
              <p className="text-sm font-medium md:text-base">
                {invoice.user.name}
              </p>
              <p className="text-xs text-muted-foreground md:text-sm">
                {invoice.user.email}
              </p>
            </div>
          </div>
        )
      },
    },
    {
      id: "invoiceNumber",
      accessorKey: "invoiceNumber",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("invoice")} />
      ),
      cell: ({ row }) => (
        <span className="font-mono text-sm font-medium">
          {row.original.invoiceNumber}
        </span>
      ),
    },
    {
      id: "amount",
      accessorFn: (row) => row.total,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("amount")} />
      ),
      cell: ({ row }) => (
        <span className="font-mono text-sm font-medium tabular-nums">
          ${row.original.total.toFixed(2)}
        </span>
      ),
    },
    {
      id: "method",
      accessorKey: "method",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("method")} />
      ),
      cell: ({ row }) => {
        const method = row.original.method
        const methodColors: Record<InvoiceMethod, string> = {
          [InvoiceMethod.STRIPE]:
            "bg-indigo-500/10 text-indigo-600 dark:text-indigo-400",
          [InvoiceMethod.PAYPAL]:
            "bg-blue-500/10 text-blue-600 dark:text-blue-400",
          [InvoiceMethod.BANK_TRANSFER]:
            "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
          [InvoiceMethod.CARD]:
            "bg-purple-500/10 text-purple-600 dark:text-purple-400",
        }
        return (
          <span
            className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${methodColors[method] || "bg-muted text-muted-foreground"}`}
          >
            {method}
          </span>
        )
      },
    },
    {
      id: "status",
      accessorKey: "status",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("status")} />
      ),
      cell: ({ row }) => (
        <StatusBadge value={row.original.status} config={STATUS_CONFIG} />
      ),
    },
    {
      id: "date",
      accessorKey: "date",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("date")} />
      ),
      cell: ({ row }) => {
        const date = row.original.date
        return (
          <span className="font-mono text-sm tabular-nums">
            {new Date(date).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            })}
          </span>
        )
      },
    },
    {
      id: "actions",
      cell: ({ row }) => {
        const invoice = row.original
        const rowActions: RowAction<Invoice>[] = []

        rowActions.push({
          label: t("view"),
          icon: Eye,
          onClick: actions.onView,
        })

        rowActions.push({
          label: t("edit"),
          icon: Pencil,
          onClick: actions.onEdit,
        })

        if (actions.onDuplicate) {
          rowActions.push({
            label: t("duplicate"),
            icon: Copy,
            onClick: actions.onDuplicate,
          })
        }

        rowActions.push({
          label: t("download"),
          icon: Download,
          separatorBefore: true,
          onClick: actions.onDownload,
        })

        if (actions.onPrint) {
          rowActions.push({
            label: t("print"),
            icon: Printer,
            onClick: actions.onPrint,
          })
        }

        if (
          invoice.status !== InvoiceStatus.PAID &&
          invoice.status !== InvoiceStatus.CANCELLED
        ) {
          rowActions.push({
            label: t("send"),
            icon: Send,
            onClick: actions.onSend,
          })
        }

        if (
          actions.onSendReminder &&
          (invoice.status === InvoiceStatus.PENDING ||
            invoice.status === InvoiceStatus.OVERDUE)
        ) {
          rowActions.push({
            label: t("sendReminder"),
            icon: Bell,
            onClick: actions.onSendReminder,
          })
        }

        if (
          invoice.status === InvoiceStatus.PENDING ||
          invoice.status === InvoiceStatus.OVERDUE
        ) {
          rowActions.push({
            label: t("markAsPaid"),
            icon: CheckCircle,
            variant: "default",
            separatorBefore: true,
            onClick: actions.onMarkAsPaid,
          })
        }

        if (
          actions.onCancel &&
          (invoice.status === InvoiceStatus.DRAFT ||
            invoice.status === InvoiceStatus.PENDING)
        ) {
          rowActions.push({
            label: t("cancel"),
            icon: XCircle,
            variant: "destructive",
            onClick: actions.onCancel,
          })
        }

        if (invoice.status !== InvoiceStatus.PAID) {
          rowActions.push({
            label: t("delete"),
            icon: Ban,
            variant: "destructive",
            separatorBefore: true,
            onClick: actions.onDelete,
          })
        }

        return <DataTableRowActions row={invoice} actions={rowActions} />
      },
    },
  ]
}

