  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<"create" | "edit">("create")
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null)
  const formRef = useRef<InvoiceFormHandle>(null)

  const [previewOpen, setPreviewOpen] = useState(false)
  const [previewInvoice, setPreviewInvoice] = useState<Invoice | null>(null)

  const {
    items: invoices,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useInvoicesTable()

  const { create, isCreating, update, isUpdating, remove, isDeleting } =
    useEntityMutations({
      queryKey: "invoices",
      createFn: createInvoiceApi,
      updateFn: updateInvoiceApi,
      deleteFn: deleteInvoiceApi,
      entityLabel: "Invoice",
    })

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)
  const [isProcessing, setIsProcessing] = useState(false)

  function openCreateForm() {
    setFormMode("create")
    setEditingInvoice(null)
    setFormOpen(true)
  }

  function openEditForm(invoice: Invoice) {
    setFormMode("edit")
    setEditingInvoice(invoice)
    setFormOpen(true)
  }

  function handleFormValid(values: any) {
    if (formMode === "create") {
      create(values, { onSuccess: () => setFormOpen(false) })
    } else if (editingInvoice) {
      update(editingInvoice.id, values)
      setFormOpen(false)
    }
  }

  async function handleDownload(invoice: Invoice) {
    try {
      await downloadInvoiceApi(invoice.id)
      toast.success(t("downloadStarted"))
    } catch (_error) {
      toast.error(t("downloadFailed"))
    }
  }

  async function handleSend(invoice: Invoice) {
    try {
      await sendInvoiceApi(invoice.id)
      toast.success(t("invoiceSent"))
    } catch (_error) {
      toast.error(t("sendFailed"))
    }
  }

  async function handleMarkAsPaid(invoice: Invoice) {
    setPendingAction({ type: "markAsPaid", invoice })
  }

  const handleCancel = (invoice: Invoice) => {
    setPendingAction({ type: "cancel", invoice })
  }

  const handleDuplicate = (invoice: Invoice) => {
    const newInvoice = {
      user: invoice.user.id,
      items: invoice.items.map((item) => ({
        description: item.description,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
      method: invoice.method,
      taxRate: invoice.taxRate,
      dueDate: invoice.dueDate,
      notes: invoice.notes,
    }
    create(newInvoice, {
      onSuccess: () => {
        toast.success(t("invoiceDuplicated"))
        refresh()
      },
    })
  }

  const handlePrint = (invoice: Invoice) => {
    const printWindow = window.open("", "_blank")
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head><title>${t("invoice")} ${invoice.invoiceNumber}</title></head>
          <body>
            <h1>${t("invoice")} ${invoice.invoiceNumber}</h1>
            <p><strong>${t("customer")}:</strong> ${invoice.user.name}</p>
            <p><strong>${t("email")}:</strong> ${invoice.user.email}</p>
            <p><strong>${t("amount")}:</strong> $${invoice.total.toFixed(2)}</p>
            <p><strong>${t("status")}:</strong> ${t(invoice.status.toLowerCase())}</p>
            <p><strong>${t("date")}:</strong> ${new Date(invoice.date).toLocaleString()}</p>
            <table border="1" cellpadding="5">
              <tr><th>${t("description")}</th><th>${t("qty")}</th><th>${t("unitPrice")}</th><th>${t("total")}</th></tr>
              ${invoice.items
                .map(
                  (item) => `
                <tr>
                  <td>${item.description}</td>
                  <td>${item.quantity}</td>
                  <td>$${item.unitPrice.toFixed(2)}</td>
                  <td>$${item.total.toFixed(2)}</td>
                </tr>
              `
                )
                .join("")}
            </table>
            <p><strong>${t("subtotal")}:</strong> $${invoice.subtotal.toFixed(2)}</p>
            <p><strong>${t("tax")}:</strong> $${invoice.tax.toFixed(2)}</p>
            <p><strong>${t("total")}:</strong> $${invoice.total.toFixed(2)}</p>
          </body>
        </html>
      `)
      printWindow.document.close()
      printWindow.print()
    }
  }

  const handleSendReminder = async (invoice: Invoice) => {
    try {
      await sendInvoiceApi(invoice.id)
      toast.success(t("reminderSent"))
    } catch (_error) {
      toast.error(t("reminderFailed"))
    }
  }

  async function handleConfirm() {
    if (!pendingAction) return

    if (pendingAction.type === "delete") {
      remove(pendingAction.invoice.id, {
        onSuccess: () => setPendingAction(null),
      })
      return
    }

    if (pendingAction.type === "markAsPaid") {
      setIsProcessing(true)
      try {
        await markAsPaidApi(pendingAction.invoice.id)
        refresh()
        setPendingAction(null)
        toast.success(t("invoiceMarkedAsPaid"))
      } finally {
        setIsProcessing(false)
      }
      return
    }

    if (pendingAction.type === "cancel") {
      setIsProcessing(true)
      try {
        await updateInvoiceApi(pendingAction.invoice.id, {
          status: InvoiceStatus.CANCELLED,
        })
        refresh()
        setPendingAction(null)
        toast.success(t("invoiceCancelled"))
      } finally {
        setIsProcessing(false)
      }
      return
    }
  }

  const columns = useMemo(
    () =>
      getInvoicesColumns(
        {
          onView: (invoice) => {
            setPreviewInvoice(invoice)
            setPreviewOpen(true)
          },
          onEdit: openEditForm,
          onDownload: handleDownload,
          onSend: handleSend,
          onMarkAsPaid: handleMarkAsPaid,
          onDelete: (invoice) => setPendingAction({ type: "delete", invoice }),
          onDuplicate: handleDuplicate,
          onPrint: handlePrint,
          onCancel: handleCancel,
          onSendReminder: handleSendReminder,
        },
        t
      ),
    [t, handleDownload, handleSend, handleDuplicate, handlePrint, handleSendReminder]
  )

  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.invoice.user.name

    switch (pendingAction.type) {
      case "delete":
        return {
          title: t("deleteInvoice"),
          description: t("deleteInvoiceConfirmation", { name }),
          confirmLabel: t("delete"),
          destructive: true,
          isLoading: isDeleting,
        }
      case "markAsPaid":
        return {
          title: t("markAsPaid"),
          description: t("markAsPaidConfirmation", { name }),
          confirmLabel: t("markAsPaid"),
          destructive: false,
          isLoading: isProcessing,
        }
      case "cancel":
        return {
          title: t("cancelInvoice"),
          description: t("cancelInvoiceConfirmation", { name }),
          confirmLabel: t("cancel"),
          destructive: true,
          isLoading: isProcessing,
        }
      default:
        return null
    }
  }, [pendingAction, isDeleting, isProcessing, t])

  const getDefaultValues = (invoice: Invoice | null) => {
    if (!invoice) return undefined

    return {
      user: invoice.user.id,
      items: invoice.items,
      status: invoice.status,
      method: invoice.method,
      taxRate: invoice.taxRate,
      dueDate: invoice.dueDate,
      notes: invoice.notes,
    }
  }

  return (
    <>
      <div className="p-4 md:p-6 space-y-6">
        <InvoicesSummaryCards invoices={invoices} />

        <DataTable
          manual
          title={t("invoices")}
          isLoading={isLoading}
          isFetching={isFetching}
          columns={columns}
          data={invoices}
          rowCount={totalItems}
          pageCount={pageCount}
          pagination={pagination}
          onPaginationChange={setPagination}
          columnFilters={columnFilters}
          onColumnFiltersChange={setColumnFilters}
          sorting={sorting}
          onSortingChange={setSorting}
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder={t("searchInvoices")}
          actions={[
            {
              label: t("create"),
              onClick: () => openCreateForm(),
              iconOnly: true,
              icon: Plus,
              variant: "primary",
            },
          ]}
          filters={[
            {
              columnId: "status",
              title: t("status"),
              options: [
                { label: t("paid"), value: InvoiceStatus.PAID },
                { label: t("pending"), value: InvoiceStatus.PENDING },
                { label: t("overdue"), value: InvoiceStatus.OVERDUE },
                { label: t("cancelled"), value: InvoiceStatus.CANCELLED },
                { label: t("draft"), value: InvoiceStatus.DRAFT },
              ],
            },
            {
              columnId: "method",
              title: t("method"),
              options: Object.values(InvoiceMethod).map((method) => ({
                label: t(method.toLowerCase()),
                value: method,
              })),
            },
          ]}
        />
      </div>

      <DataTableEntityFormSheet
        open={formOpen}
        onOpenChange={setFormOpen}
        mode={formMode}
        createTitle={t("addInvoice")}
        editTitle={t("editInvoice")}
        description={
          formMode === "create"
            ? t("createNewInvoice")
            : t("updateInvoiceDetails")
        }
        isSubmitting={isCreating || isUpdating}
        onSubmit={() => formRef.current?.submit()}
      >
        <InvoiceForm
          ref={formRef}
          mode={formMode}
          defaultValues={getDefaultValues(editingInvoice)}
          onValid={handleFormValid}
        />
      </DataTableEntityFormSheet>

      <InvoiceDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        invoice={previewInvoice}
        onDownload={handleDownload}
        onSend={handleSend}
      />

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </>
  )
}

"use client"

import { useMemo } from "react"
import { useTranslations } from "next-intl"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  Clock,
  AlertCircle,
  CheckCircle,
  FileText,
} from "@/components/ui/carbon/icons"
import { Invoice, InvoiceStatus } from "@/types/invoices"

interface InvoicesSummaryCardsProps {
  invoices: Invoice[]
}

export function InvoicesSummaryCards({ invoices }: InvoicesSummaryCardsProps) {
  const t = useTranslations()

  const summary = useMemo(() => {
    let totalRevenue = 0
    let paid = 0
    let pending = 0
    let overdue = 0
    let cancelled = 0

    invoices.forEach((invoice) => {
      if (invoice.status === InvoiceStatus.PAID) {
        totalRevenue += invoice.total
        paid += 1
      } else if (invoice.status === InvoiceStatus.PENDING) {
        pending += 1
      } else if (invoice.status === InvoiceStatus.OVERDUE) {
        overdue += 1
        totalRevenue += invoice.total // Still counts as revenue but overdue
      } else if (invoice.status === InvoiceStatus.CANCELLED) {
        cancelled += 1
      }
    })

    return { totalRevenue, paid, pending, overdue, cancelled }
  }, [invoices])

  const cards = [
    {
      key: "totalRevenue",
      title: t("totalRevenue"),
      value: `$${summary.totalRevenue.toFixed(2)}`,
      valueClassName: "",
      badge: {
        label: "+12.5%",
        icon: TrendingUp,
        variant: "outline" as const,
        className: "gap-1",
      },
      footer: {
        icon: DollarSign,
        text: t("totalRevenueDescription"),
        subtext: t("totalRevenueSubtext"),
        className: "",
      },
    },
    {
      key: "paid",
      title: t("paidInvoices"),
      value: summary.paid.toString(),
      valueClassName: "text-emerald-600",
      badge: {
        label: t("paid"),
        icon: CheckCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-emerald-500/20 bg-emerald-500/10 text-emerald-600",
      },
      footer: {
        icon: FileText,
        text: t("paidInvoices"),
        subtext: t("paidInvoicesSubtext"),
        className: "text-emerald-600",
      },
    },
    {
      key: "pending",
      title: t("pendingInvoices"),
      value: summary.pending.toString(),
      valueClassName: "text-amber-600",
      badge: {
        label: t("pending"),
        icon: Clock,
        variant: "outline" as const,
        className: "gap-1 border-amber-500/20 bg-amber-500/10 text-amber-600",
      },
      footer: {
        icon: Clock,
        text: t("pendingInvoices"),
        subtext: t("pendingInvoicesSubtext"),
        className: "text-amber-600",
      },
    },
    {
      key: "overdue",
      title: t("overdueInvoices"),
      value: summary.overdue.toString(),
      valueClassName: "text-destructive",
      badge: {
        label: t("overdue"),
        icon: AlertCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-destructive/20 bg-destructive/10 text-destructive",
      },
      footer: {
        icon: TrendingDown,
        text: t("overdueInvoices"),
        subtext: t("overdueInvoicesSubtext"),
        className: "text-destructive",
      },
    },
  ]

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
      {cards.map((card) => (
        <Card key={card.key} className="h-full flex flex-col justify-between">
          <CardHeader className="p-5 pb-3">
            <div className="flex items-center justify-between gap-2">
              <CardDescription className="text-xs font-medium uppercase tracking-wider">{card.title}</CardDescription>
              <Badge
                variant={card.badge.variant}
                className={card.badge.className}
              >
                <card.badge.icon className="size-3" />
                {card.badge.label}
              </Badge>
            </div>
            <CardTitle
              className={`text-2xl font-bold font-mono tabular-nums @[250px]/card:text-3xl mt-2 ${card.valueClassName}`}
            >
              {card.value}
            </CardTitle>
          </CardHeader>
          <CardFooter className="px-5 py-3 pt-0 border-t-0 flex items-center gap-1.5 text-xs text-muted-foreground mt-auto">
            <card.footer.icon className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="truncate font-medium">{card.footer.text}</span>
          </CardFooter>
        </Card>
      ))}
    </div>
  )
}

"use client"

import React, { createContext, useContext, useState, useMemo } from "react"

export type DateRangeOption = "Last 7 days" | "Last 30 days" | "Last 90 days" | "Year to date"
export type CompareModeOption =
  | "vs Prior period"
  | "vs Prior 7d"
  | "vs Prior 30d"
  | "vs Prior 90d"
  | "vs Same period 2025"
  | "No comparison"
export type CurrencyOption = "USD" | "EUR" | "GBP" | "JPY" | "CAD"

export interface AnalyticsFilterContextValue {
  dateRange: DateRangeOption
  setDateRange: (range: DateRangeOption) => void
  compareMode: CompareModeOption
  setCompareMode: (mode: CompareModeOption) => void
  currency: CurrencyOption
  setCurrency: (curr: CurrencyOption) => void
  workspace: string
  setWorkspace: (ws: string) => void
  currencySymbol: string
  formatCurrency: (amountInUSD: number, options?: { compact?: boolean; hideSign?: boolean }) => string
  currencyRate: number
  workspaceMultiplier: number
}

const CURRENCY_CONFIG: Record<CurrencyOption, { symbol: string; rate: number }> = {
  USD: { symbol: "$", rate: 1.0 },
  EUR: { symbol: "€", rate: 0.92 },
  GBP: { symbol: "£", rate: 0.78 },
  JPY: { symbol: "¥", rate: 155.0 },
  CAD: { symbol: "CA$", rate: 1.36 },
}

const WORKSPACE_MULTIPLIERS: Record<string, number> = {
  "All Workspaces": 1.0,
  "Acme Corp Prod": 0.285, // ~$48.2k MRR
  "Stark Industries": 0.192, // ~$32.4k MRR
  "Wayne Enterprises": 0.145, // ~$24.5k MRR
  "Cyberdyne Systems": 0.082, // ~$13.8k MRR
}

const AnalyticsFilterContext = createContext<AnalyticsFilterContextValue | null>(null)

export function AnalyticsFilterProvider({ children }: { children: React.ReactNode }) {
  const [dateRange, setDateRangeState] = useState<DateRangeOption>("Last 30 days")
  const [compareMode, setCompareMode] = useState<CompareModeOption>("vs Prior 30d")
  const [currency, setCurrency] = useState<CurrencyOption>("USD")
  const [workspace, setWorkspace] = useState<string>("All Workspaces")

  // When date range changes, automatically pick an intuitive default compare mode
  const setDateRange = (newRange: DateRangeOption) => {
    setDateRangeState(newRange)
    if (newRange === "Last 7 days") {
      setCompareMode("vs Prior 7d")
    } else if (newRange === "Last 30 days") {
      setCompareMode("vs Prior 30d")
    } else if (newRange === "Last 90 days") {
      setCompareMode("vs Prior 90d")
    } else if (newRange === "Year to date") {
      setCompareMode("vs Same period 2025")
    }
  }

  const { symbol, rate } = CURRENCY_CONFIG[currency] || CURRENCY_CONFIG.USD
  const workspaceMultiplier = WORKSPACE_MULTIPLIERS[workspace] ?? 1.0

  const formatCurrency = (
    amountInUSD: number,
    options?: { compact?: boolean; hideSign?: boolean }
  ): string => {
    const isNegative = amountInUSD < 0
    const absVal = Math.abs(amountInUSD) * rate * workspaceMultiplier

    let formattedValue: string
    if (options?.compact) {
      if (absVal >= 1_000_000) {
        formattedValue = `${(absVal / 1_000_000).toFixed(currency === "JPY" ? 1 : 2)}M`
      } else if (absVal >= 1_000) {
        formattedValue = `${(absVal / 1_000).toFixed(currency === "JPY" ? 0 : 1)}k`
      } else {
        formattedValue = Math.round(absVal).toLocaleString()
      }
    } else {
      formattedValue = Math.round(absVal).toLocaleString()
    }

    const sign = options?.hideSign ? "" : isNegative ? "-" : ""
    return `${sign}${symbol}${formattedValue}`
  }

  const contextValue = useMemo<AnalyticsFilterContextValue>(
    () => ({
      dateRange,
      setDateRange,
      compareMode,
      setCompareMode,
      currency,
      setCurrency,
      workspace,
      setWorkspace,
      currencySymbol: symbol,
      formatCurrency,
      currencyRate: rate,
      workspaceMultiplier,
    }),
    [dateRange, compareMode, currency, workspace, symbol, formatCurrency, rate, workspaceMultiplier]
  )

  return (
    <AnalyticsFilterContext.Provider value={contextValue}>
      {children}
    </AnalyticsFilterContext.Provider>
  )
}

export function useAnalyticsFilter() {
  const ctx = useContext(AnalyticsFilterContext)
  if (!ctx) {
    throw new Error("useAnalyticsFilter must be used within an AnalyticsFilterProvider")
  }
  return ctx
}

"use client"

import * as React from "react"
import { Label, Pie, PieChart, Sector } from "recharts"
import type {
  PieSectorDataItem,
  PieSectorShapeProps,
} from "recharts/types/polar/Pie"

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  ChartContainer,
  ChartStyle,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { useTranslations } from "next-intl"

export const description = "An interactive pie chart"

const desktopData = [
  { month: "january", desktop: 186, fill: "var(--color-january)" },
  { month: "february", desktop: 305, fill: "var(--color-february)" },
  { month: "march", desktop: 237, fill: "var(--color-march)" },
  { month: "april", desktop: 173, fill: "var(--color-april)" },
  { month: "may", desktop: 209, fill: "var(--color-may)" },
]

const chartConfig = {
  visitors: {
    label: "Visitors",
  },
  desktop: {
    label: "Desktop",
  },
  mobile: {
    label: "Mobile",
  },
  january: {
    label: "January",
    color: "var(--chart-1)",
  },
  february: {
    label: "February",
    color: "var(--chart-2)",
  },
  march: {
    label: "March",
    color: "var(--chart-3)",
  },
  april: {
    label: "April",
    color: "var(--chart-4)",
  },
  may: {
    label: "May",
    color: "var(--chart-5)",
  },
} satisfies ChartConfig

function ChartPieInteractive() {
  const t = useTranslations()
  const id = "pie-interactive"
  const [activeMonth, setActiveMonth] = React.useState(desktopData[0].month)

  const activeIndex = React.useMemo(
    () => desktopData.findIndex((item) => item.month === activeMonth),
    [activeMonth]
  )
  const months = React.useMemo(() => desktopData.map((item) => item.month), [])

  const renderPieShape = React.useCallback(
    ({ index, outerRadius = 0, ...props }: PieSectorShapeProps) => {
      if (index === activeIndex) {
        return (
          <g>
            <Sector {...props} outerRadius={outerRadius + 10} />
            <Sector
              {...props}
              outerRadius={outerRadius + 25}
              innerRadius={outerRadius + 12}
            />
          </g>
        )
      }

      return <Sector {...props} outerRadius={outerRadius} />
    },
    [activeIndex]
  )

  return (
    <Card data-chart={id} className="flex h-full flex-col">
      <ChartStyle id={id} config={chartConfig} />
      <CardHeader className="flex-row items-start space-y-0 pb-0">
        <div className="grid gap-1">
          <CardTitle>{t("pieChartInteractive")}</CardTitle>
          <CardDescription>{t("januaryJune2024")}</CardDescription>
        </div>
        <Select value={activeMonth} onValueChange={setActiveMonth}>
          <SelectTrigger
            className="ml-auto h-7 w-[130px] rounded-lg pl-2.5"
            aria-label={t("selectValue")}
          >
            <SelectValue placeholder={t("selectMonth")} />
          </SelectTrigger>
          <SelectContent align="end" className="rounded-xl">
            {months.map((key) => {
              const config = chartConfig[key as keyof typeof chartConfig]

              if (!config) {
                return null
              }

              return (
                <SelectItem
                  key={key}
                  value={key}
                  className="rounded-lg [&_span]:flex"
                >
                  <div className="flex items-center gap-2 text-xs">
                    <span
                      className="flex h-3 w-3 shrink-0 rounded-xs"
                      style={{
                        backgroundColor: `var(--color-${key})`,
                      }}
                    />
                    {config.label}
                  </div>
                </SelectItem>
              )
            })}
          </SelectContent>
        </Select>
      </CardHeader>
      <CardContent className="flex flex-1 justify-center pb-0">
        <ChartContainer
          id={id}
          config={chartConfig}
          className="mx-auto aspect-square w-full max-w-[300px]"
        >
          <PieChart>
            <ChartTooltip
              cursor={false}
              content={<ChartTooltipContent hideLabel />}
            />
            <Pie
              data={desktopData}
              dataKey="desktop"
              nameKey="month"
              innerRadius={60}
              strokeWidth={5}
              shape={renderPieShape}
            >
              <Label
                content={({ viewBox }) => {
                  if (viewBox && "cx" in viewBox && "cy" in viewBox) {
                    return (
                      <text
                        x={viewBox.cx}
                        y={viewBox.cy}
                        textAnchor="middle"
                        dominantBaseline="middle"
                      >
                        <tspan
                          x={viewBox.cx}
                          y={viewBox.cy}
                          className="fill-foreground text-3xl font-bold"
                        >
