  const minVal = Math.min(...chartData.map((d) => (compareMode !== "No comparison" ? Math.min(d.current, d.previous) : d.current)))
  const maxVal = Math.max(...chartData.map((d) => (compareMode !== "No comparison" ? Math.max(d.current, d.previous) : d.current)))
  const yDomainMin = Math.max(0, Math.floor((minVal * 0.95) / 1000) * 1000)
  const yDomainMax = Math.ceil((maxVal * 1.05) / 1000) * 1000

  const showComparison = compareMode !== "No comparison"

  return (
    <div className="flex h-full flex-col justify-between rounded-xl border border-border/70 bg-card p-5 shadow-2xs">
      {/* Header */}
      <div>
        <div className="flex items-center justify-between pb-1">
          <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <Information className="size-3.5 text-muted-foreground/70" />
            <span className="font-medium">MRR & Recurring Revenue Growth</span>
          </div>
          <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-semibold text-primary">
            {dateRange}
          </span>
        </div>
        <div className="mt-1 flex flex-wrap items-baseline gap-3">
          <span className="text-2xl font-bold tracking-tight text-foreground font-mono">
            {formatCurrency(latestCurrent / (currencyRate * workspaceMultiplier))}
          </span>
          <span className="text-xs font-medium text-emerald-600 dark:text-emerald-400">
            {deltaText}
          </span>
          <span className="hidden sm:inline-block text-xs text-muted-foreground font-mono">
            (ARR: {formatCurrency(arrRunRate / (currencyRate * workspaceMultiplier), { compact: true })})
          </span>
        </div>
      </div>

      {/* Chart Area */}
      <div className="mt-4 h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 10, right: 10, left: -10, bottom: 0 }}
          >
            <CartesianGrid
              strokeDasharray="3 3"
              vertical={false}
              className="stroke-border/40"
            />
            <XAxis
              dataKey="date"
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 11 }}
              className="fill-muted-foreground"
              ticks={xTicks}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 11 }}
              className="fill-muted-foreground"
              domain={[yDomainMin, yDomainMax]}
              tickFormatter={(v) => `${currencySymbol}${(v / 1000).toFixed(0)}k`}
            />
            <Tooltip
              content={({ active, payload, label }) => {
                if (!active || !payload?.length) return null
                const curr = Number(payload[0]?.value)
                const prev = payload[1] ? Number(payload[1]?.value) : null
                const delta = prev !== null ? curr - prev : null
                return (
                  <div className="rounded-lg border border-border/80 bg-popover px-3 py-2 text-xs shadow-md">
                    <p className="font-semibold text-foreground">{label}</p>
                    <div className="mt-1 space-y-1">
                      <p className="text-primary font-mono font-medium">
                        Current: {currencySymbol}{curr.toLocaleString()}
                      </p>
                      {prev !== null && (
                        <p className="text-muted-foreground font-mono text-[11px]">
                          {compareMode}: {currencySymbol}{prev.toLocaleString()}
                        </p>
                      )}
                      {delta !== null && (
                        <p className="text-emerald-600 dark:text-emerald-400 font-mono text-[11px]">
                          Variance: {delta >= 0 ? "+" : ""}{currencySymbol}{delta.toLocaleString()}
                        </p>
                      )}
                    </div>
                  </div>
                )
              }}
            />
            {/* Solid primary line for current period */}
            <Line
              type="monotone"
              dataKey="current"
              stroke="#0284c7"
              strokeWidth={2}
              dot={dateRange === "Last 7 days" ? { r: 3, fill: "#0284c7" } : false}
              activeDot={{ r: 5, fill: "#0284c7" }}
            />
            {/* Lighter dashed line for previous period comparison */}
            {showComparison && (
              <Line
                type="monotone"
                dataKey="previous"
                stroke="#94a3b8"
                strokeWidth={1.5}
                strokeDasharray="3 3"
                dot={dateRange === "Last 7 days" ? { r: 2.5, fill: "#94a3b8" } : false}
                activeDot={{ r: 4, fill: "#94a3b8" }}
              />
            )}
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Footer Legend */}
      <div className="mt-3 flex items-center justify-between border-t border-border/40 pt-3 text-xs text-muted-foreground">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-[#0284c7]" />
            <span className="font-medium text-foreground">Current ({dateRange})</span>
          </div>
          {showComparison && (
            <div className="flex items-center gap-1.5">
              <span className="size-2 rounded-full border border-dashed border-[#94a3b8]" />
              <span>{compareMode}</span>
            </div>
          )}
        </div>
        <span className="font-mono text-[11px] text-muted-foreground">
          Scope: {workspace}
        </span>
      </div>

      {/* Operational Explanation Paragraph */}
      <div className="mt-3 rounded-lg bg-muted/30 p-2.5 text-xs text-muted-foreground border border-border/40">
        <span className="font-semibold text-foreground">Executive Guidance: </span>
        {explanation}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { useTranslations } from "next-intl"
import { useQuery } from "@tanstack/react-query"
import { Purchase, Renew } from "@carbon/icons-react"
import { Button } from "@/components/ui/button"
import { FooterGradient } from "@/components/ui/footer-gradient"
import { PlanCard, PlanCardData } from "./plan-card"
import { billingApi, createCheckoutApi, createPortalApi } from "@/lib/api/billing-apis"
import { apiErrorMessage } from "@/lib/myapi/client"
import { toast } from "@/lib/utils/toast"
import { InlineNotification, ActionableNotification } from "@/components/ui/carbon/notification"

const TIERS: PlanCardData[] = [
  {
    id: "free",
    name: "Free",
    price: "$0",
    period: "month",
    description: "Essential tools for personal projects and exploring the platform.",
    featured: false,
    features: [
      "1 Workspace",
      "Up to 3 team members",
      "Community support",
      "Basic analytics",
      "Standard rate limits",
    ],
  },
  {
    id: "pro",
    name: "Pro",
    price: "$29",
    period: "month",
    description: "Advanced features and power tools for scaling businesses.",
    featured: true,
    features: [
      "Unlimited workspaces",
      "Up to 25 team members",
      "Priority email support",
      "Advanced analytics & audit logs",
      "Higher API rate limits",
      "Full API & Webhook access",
    ],
  },
  {
    id: "enterprise",
    name: "Enterprise",
    price: "$99",
    period: "month",
    description: "Maximum security, scalability, and dedicated assistance.",
    featured: false,
    features: [
      "Unlimited seats & usage",
      "Dedicated account manager",
      "99.99% uptime SLA",
      "Custom integrations & webhooks",
      "SSO / SAML authentication",
      "Custom billing & invoicing",
    ],
  },
]

export default function PlansPage() {
  const t = useTranslations()
  const [upgradingPlan, setUpgradingPlan] = useState<string | null>(null)
  const [isOpeningPortal, setIsOpeningPortal] = useState(false)
  const [billingNotice, setBillingNotice] = useState<string | null>(null)

  const {
    data: subscription,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["billing-subscription"],
    queryFn: billingApi.getSubscription,
    retry: false,
  })

  const currentPlan = subscription?.plan ?? "free"
  const isPastDue = subscription?.status === "past_due"
  const hasAccess = subscription?.access ?? true

  const [now] = useState(() => Date.now())

  // Dunning grace remaining calculation
  const dunningDaysRemaining = useMemo(() => {
    if (!isPastDue || !subscription?.graceUntil) return null
    const diffMs = new Date(subscription.graceUntil).getTime() - now
    return Math.max(0, Math.ceil(diffMs / (1000 * 60 * 60 * 24)))
  }, [isPastDue, subscription?.graceUntil, now])

  const handleUpgrade = async (plan: PlanCardData) => {
    if (plan.id !== "pro" && plan.id !== "enterprise") return
    setUpgradingPlan(plan.id)
    try {
      const { url } = await createCheckoutApi(plan.id)
      if (url) {
        window.location.assign(url)
      }
    } catch (err: any) {
      if (
        err?.response?.status === 501 ||
        err?.response?.data?.code === "billing_not_configured"
      ) {
        const msg = "Billing is not configured in this environment (Stripe keys not set)."
        setBillingNotice(msg)
        toast.info(msg)
      } else {
        toast.error(apiErrorMessage(err, "Failed to initiate checkout."))
      }
    } finally {
      setUpgradingPlan(null)
    }
  }

  const handleManageBilling = async () => {
    setIsOpeningPortal(true)
    try {
      const { url } = await createPortalApi()
      if (url) {
        window.location.assign(url)
      }
    } catch (err: any) {
      if (
        err?.response?.status === 501 ||
        err?.response?.data?.code === "billing_not_configured"
      ) {
        const msg = "Billing is not configured in this environment (Stripe keys not set)."
        setBillingNotice(msg)
        toast.info(msg)
      } else if (
        err?.response?.status === 400 &&
        err?.response?.data?.code === "no_customer"
      ) {
        toast.error("No billing profile found yet. Please subscribe to a plan first.")
      } else {
        toast.error(apiErrorMessage(err, "Failed to open billing portal."))
      }
    } finally {
      setIsOpeningPortal(false)
    }
  }

  if (isLoading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="h-10 w-10 animate-spin rounded-full border-b-2 border-primary" />
      </div>
    )
  }

  return (
    <div className="relative h-full w-full overflow-hidden">
      <div className="h-full w-full space-y-6 overflow-auto p-4 pb-24 md:p-6 md:pb-28">
        {/* Header */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-foreground md:text-3xl">
              {t("plans")}
            </h1>
            <p className="text-sm text-muted-foreground">
              {t("plansDescription")}
            </p>
          </div>
          {subscription?.hasPaymentMethod && (
            <Button
              variant="outline"
              onClick={handleManageBilling}
              disabled={isOpeningPortal}
              className="gap-2"
            >
              {isOpeningPortal ? (
                <Renew className="size-4 animate-spin" />
              ) : (
                <Purchase className="size-4" />
              )}
              Manage Billing
            </Button>
          )}
        </div>

        {/* Billing Service Unavailable Banner */}
        {isError && (
          <InlineNotification
            kind="error"
            title="Subscription Data Unavailable"
            subtitle="Unable to connect to the billing service. Plan details may be out of date."
            lowContrast
            hideCloseButton
            className="w-full mb-2"
          />
        )}

        {/* 501 Billing Not Configured Banner */}
        {billingNotice && (
          <InlineNotification
            kind="info"
            title="Billing Not Configured"
            subtitle={billingNotice}
            lowContrast
            onCloseButtonClick={() => setBillingNotice(null)}
            className="w-full mb-2"
          />
        )}

        {/* Past Due Dunning Banner */}
        {isPastDue && (
          <ActionableNotification
            kind={hasAccess ? "warning" : "error"}
            title={
              hasAccess
                ? "Payment Past Due (Grace Period Active)"
                : "Grace Period Expired — Access Restricted"
            }
            subtitle={
              hasAccess
                ? `Your payment method could not be charged. You have ${
                    dunningDaysRemaining ?? 7
                  } days remaining in your grace period before account features are restricted.`
                : "Your 7-day grace period has expired and premium workspace features have been suspended. Please update your payment method to restore access."
            }
            actionButtonLabel="Update Payment"
            onActionButtonClick={handleManageBilling}
            lowContrast
            hideCloseButton
            className="w-full"
          />
        )}

        {/* Plans Grid */}
        <div className="grid grid-cols-1 gap-6 md:grid-cols-3 max-w-6xl mx-auto pt-4">
          {TIERS.map((plan, index) => {
            const isCurrent = currentPlan.toLowerCase() === plan.id.toLowerCase()
            const isUpgradable = plan.id === "pro" || plan.id === "enterprise"

            let actionLabel = "Select Plan"
            if (plan.id === "pro") {
              actionLabel = currentPlan === "enterprise" ? "Downgrade to Pro" : "Upgrade to Pro"
            } else if (plan.id === "enterprise") {
              actionLabel = "Upgrade to Enterprise"
            }

            return (
              <PlanCard
                key={plan.id}
                plan={plan}
                index={index}
                isCurrent={isCurrent}
                isUpgrading={upgradingPlan === plan.id}
                actionLabel={actionLabel}
                disabled={!isUpgradable && !isCurrent}
                onUpgrade={isUpgradable && !isCurrent ? () => handleUpgrade(plan) : undefined}
              />
            )
          })}
        </div>
      </div>

      <FooterGradient position="absolute" height="lg" blur={false} />
    </div>
  )
}

// components/shared/select-plan.tsx

"use client"

import { useEffect, useMemo, useState } from "react"
import { ChevronsUpDown, Loader2, Gem, X, SearchIcon } from "@/components/ui/carbon/icons"
import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { useTranslations } from "next-intl"
import { usePlansOptions } from "@/hooks/plans/use-plans-options"

interface PlanOption {
  id: string
  name: string
  price: string
  featured: boolean
}

interface SelectPlanProps {
  value?: string
  onChange: (planId: string) => void
  placeholder?: string
  disabled?: boolean
  excludePlanId?: string
}

export function SelectPlan({
  value,
  onChange,
  placeholder,
  disabled = false,
  excludePlanId,
}: SelectPlanProps) {
  const t = useTranslations()
  const [open, setOpen] = useState(false)

  const {
    data: plans,
    isLoading,
    isFetching,
    search,
    setSearch,
  } = usePlansOptions()

  const placeholderText = placeholder || t("selectPlan")

  // Filter out excluded plan
  const filteredPlans = useMemo(() => {
    if (!plans) return []
    return excludePlanId
      ? plans.filter((p: PlanOption) => p.id !== excludePlanId)
      : plans
  }, [plans, excludePlanId])

  // Current selected plan object
  const selectedPlan = useMemo(() => {
    return plans?.find((p: PlanOption) => p.id === value)
  }, [plans, value])

  const selectPlan = (planId: string) => {
    onChange(planId)
    setOpen(false)
  }

  const clearSelection = () => {
    onChange("")
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <div
          role="combobox"
          aria-expanded={open}
          aria-controls="plan-listbox"
          tabIndex={disabled ? -1 : 0}
          aria-disabled={disabled}
          onKeyDown={(e) => {
            if (disabled) return
            if (e.key === "Enter" || e.key === " " || e.key === "ArrowDown") {
              e.preventDefault()
              setOpen(true)
            }
          }}
          className={cn(
            "flex h-auto min-h-[52px] w-full cursor-pointer items-center justify-between gap-2 overflow-hidden rounded-md border border-input bg-card px-3 py-2 text-sm font-normal shadow-sm transition-colors",
            "hover:bg-accent/50",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:outline-none",
            disabled && "pointer-events-none cursor-not-allowed opacity-50"
            // value && "border-primary/30 bg-primary/5 hover:bg-primary/10"
          )}
        >
          {isLoading && !value ? (
            <span className="flex items-center gap-2 text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
              {t("loadingPlans")}
            </span>
          ) : value && selectedPlan ? (
            <div className="flex items-center gap-2 truncate">
              <span className="truncate">{selectedPlan.name}</span>
              <span className="shrink-0 text-xs text-muted-foreground">
                ({selectedPlan.price})
              </span>
              {selectedPlan.featured && (
                <Badge variant="outline" className="shrink-0 text-xs">
                  {t("featured")}
                </Badge>
              )}
            </div>
          ) : (
            <span className="text-muted-foreground">{placeholderText}</span>
          )}
          <div className="flex shrink-0 items-center gap-1.5">
            {value && (
              <span
                role="button"
                tabIndex={0}
                onClick={(e) => {
                  e.stopPropagation()
                  clearSelection()
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault()
                    e.stopPropagation()
                    clearSelection()
                  }
                }}
                className="cursor-pointer rounded-sm p-0.5 text-muted-foreground transition-colors hover:bg-destructive/20 hover:text-destructive focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                aria-label={t("clearPlan")}
              >
                <X className="size-3.5" />
              </span>
            )}
            <ChevronsUpDown className="size-4 shrink-0 opacity-50" />
          </div>
        </div>
      </PopoverTrigger>

      <PopoverContent
        className="w-[var(--radix-popover-trigger-width)] rounded-xl p-0 shadow-xl"
        align="start"
        sideOffset={6}
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <div className="flex flex-col rounded-xl">
          {/* Header with count */}
          <div className="flex items-center justify-between border-b px-3 py-2">
            <div className="flex items-center gap-2">
              <Gem className="size-4 text-primary" />
              <span className="text-sm font-semibold">{t("plans")}</span>
            </div>
            {value && (
              <span className="text-xs text-muted-foreground">
                {t("selectedCount", { count: 1 })}
              </span>
            )}
          </div>

          {/* Plain search input instead of CommandInput */}
          <div className="flex items-center gap-2 border-b px-3 py-2">
            <SearchIcon className="size-4 shrink-0 text-muted-foreground" />
            <input
              autoFocus
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t("searchPlans")}
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>

          {/* Plain scrollable list — overflow works fine, no cmdk involved */}
          <div role="listbox" className="max-h-56 overflow-y-auto p-1">
            {isLoading || (isFetching && search) ? (
              <div className="flex items-center justify-center gap-2 py-8 text-sm text-muted-foreground">
                <Loader2 className="size-4 animate-spin" />
                {search ? t("searching") : t("loadingPlans")}
              </div>
            ) : filteredPlans.length === 0 ? (
              <div className="flex flex-col items-center gap-2 py-8 text-center">
                <Gem className="size-8 text-muted-foreground/50" />
                <p className="text-sm font-medium">{t("noPlansFound")}</p>
                <p className="text-xs text-muted-foreground">
                  {t("tryAdjustingSearch")}
                </p>
              </div>
            ) : (
              filteredPlans.map((plan: PlanOption) => {
                const checked = value === plan.id
                return (
                  <div
                    key={plan.id}
                    role="option"
                    aria-selected={checked}
                    tabIndex={0}
                    onClick={() => selectPlan(plan.id, plan.name)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault()
                        selectPlan(plan.id, plan.name)
                      }
                    }}
                    className={cn(
                      "flex cursor-pointer items-center gap-2.5 rounded-lg px-3 py-2.5 outline-none",
                      "hover:bg-accent focus-visible:bg-accent",
                      checked && "bg-primary/5"
                    )}
                  >
                    <Gem
                      className={cn(
                        "size-4 shrink-0",
                        checked ? "text-primary" : "text-muted-foreground"
                      )}
                    />
                    <div className="flex flex-1 items-center gap-2 truncate">
                      <span className="font-medium">{plan.name}</span>
                      <span className="text-xs text-muted-foreground">
                        ({plan.price})
                      </span>
                      {plan.featured && (
                        <Badge variant="outline" className="shrink-0 text-xs">
                          {t("featured")}
                        </Badge>
                      )}
                    </div>
                  </div>
                )
              })
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

