  open: boolean
  onOpenChange: (open: boolean) => void
  project: Project | null
}

export function ProjectDialog({
  open,
  onOpenChange,
  project,
}: ProjectDialogProps) {
  const t = useTranslations()

  if (!project) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] max-w-4xl overflow-hidden p-0">
        <ProjectDetail project={project} onClose={() => onOpenChange(false)} />
      </DialogContent>
    </Dialog>
  )
}

// components/projects/projects-columns.tsx

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { DataTableColumnHeader } from "@/components/shared/data-table-chunks/data-table-column-header"
import {
  DataTableRowActions,
  RowAction,
} from "@/components/shared/data-table-chunks/data-table-row-actions"
import { StatusBadge } from "@/components/ui/status-badge"
import { Project, ProjectStatus } from "@/types/projects"
import {
  Eye,
  Archive,
  Trash2,
  Pencil,
  Copy,
  CheckCircle,
  RotateCw,
  Download,
} from "@/components/ui/carbon/icons"
import { SpaceAvatar } from "@/components/ui/space-avatar"

export interface ProjectsColumnActions {
  onView: (project: Project) => void
  onEdit: (project: Project) => void
  onArchive: (project: Project) => void
  onDelete: (project: Project) => void
  onDuplicate?: (project: Project) => void
  onComplete?: (project: Project) => void
  onActivate?: (project: Project) => void
  onExport?: (project: Project) => void
}

export function getProjectsColumns(
  actions: ProjectsColumnActions,
  t: (key: string, values?: Record<string, string | number>) => string
): ColumnDef<Project, any>[] {
  const STATUS_CONFIG: Record<
    ProjectStatus,
    { label: string; className: string }
  > = {
    [ProjectStatus.ACTIVE]: {
      label: t("active"),
      className:
        "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-transparent",
    },
    [ProjectStatus.ARCHIVED]: {
      label: t("archived"),
      className: "bg-muted text-muted-foreground border-transparent",
    },
    [ProjectStatus.COMPLETED]: {
      label: t("completed"),
      className:
        "bg-blue-500/10 text-blue-600 dark:text-blue-400 border-transparent",
    },
    [ProjectStatus.ON_HOLD]: {
      label: t("onHold"),
      className:
        "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-transparent",
    },
  }

  return [
    {
      id: "name",
      accessorKey: "name",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("project")} />
      ),
      cell: ({ row }) => {
        const project = row.original
        return (
          <div>
            <p className="text-sm font-medium">{project.name}</p>
            {project.description && (
              <p className="max-w-[200px] truncate text-xs text-muted-foreground">
                {project.description}
              </p>
            )}
          </div>
        )
      },
    },
    {
      id: "owner",
      accessorFn: (row) => row.owner.name,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("owner")} />
      ),
      cell: ({ row }) => {
        const project = row.original
        return (
          <div className="flex items-center gap-2">
            <SpaceAvatar
              name={project.owner.name}
              src={project.owner.avatar || ""}
              profileColor={project.owner.profileColor}
              size="xs"
            />
            <span className="text-sm">{project.owner.name}</span>
          </div>
        )
      },
    },
    {
      id: "members",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("members")} />
      ),
      cell: ({ row }) => {
        const project = row.original
        const MAX_VISIBLE = 3
        const visibleMembers = project.members.slice(0, MAX_VISIBLE)
        const remaining = project.members.length - MAX_VISIBLE

        return (
          <div className="flex items-center">
            {visibleMembers.map((m, index) => (
              <div
                key={m.user.id}
                className="h-8 w-8"
                style={{
                  marginLeft: index === 0 ? 0 : "-8px",
                  zIndex: visibleMembers.length - index,
                }}
              >
                <SpaceAvatar
                  name={m.user.name}
                  profileColor={m.user.profileColor}
                  src={m.user.avatar || ""}
                  size="xs"
                  className="h-8 w-8 rounded-full ring-2 ring-background"
                />
              </div>
            ))}
            {remaining > 0 && (
              <div
                className="flex size-6 items-center justify-center rounded-full bg-muted text-[10px] font-medium text-muted-foreground ring-2 ring-background"
                style={{ marginLeft: "-8px", zIndex: 0 }}
              >
                +{remaining}
              </div>
            )}
          </div>
        )
      },
    },
    {
      id: "status",
      accessorKey: "status",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("status")} />
      ),
      cell: ({ row }) => (
        <StatusBadge value={row.original.status} config={STATUS_CONFIG} />
      ),
    },
    {
      id: "progress",
      accessorKey: "progress",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("progress")} />
      ),
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <div className="h-2 w-16 overflow-hidden rounded-full bg-muted">
            <div
              className="h-full rounded-full bg-emerald-500 transition-all"
              style={{ width: `${row.original.progress}%` }}
            />
          </div>
          <span className="font-mono text-sm tabular-nums">{row.original.progress}%</span>
        </div>
      ),
    },
    {
      id: "updated",
      accessorKey: "updatedAt",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("updated")} />
      ),
      cell: ({ row }) => {
        const date = row.original.updatedAt
        const now = new Date()
        const updated = new Date(date)
        const diffMs = now.getTime() - updated.getTime()
        const diffMin = Math.floor(diffMs / 60000)
        const diffHr = Math.floor(diffMs / 3600000)
        const diffDay = Math.floor(diffMs / 86400000)

        let timeAgo
        if (diffMin < 1) timeAgo = t("justNow")
        else if (diffMin < 60) timeAgo = t("minutesAgo", { count: diffMin })
        else if (diffHr < 24) timeAgo = t("hoursAgo", { count: diffHr })
        else if (diffDay < 7) timeAgo = t("daysAgo", { count: diffDay })
        else timeAgo = updated.toLocaleDateString()

        return <span className="text-sm">{timeAgo}</span>
      },
    },
    {
      id: "actions",
      cell: ({ row }) => {
        const project = row.original
        const rowActions: RowAction<Project>[] = []

        // View
        rowActions.push({
          label: t("view"),
          icon: Eye,
          onClick: actions.onView,
        })

        // Edit
        rowActions.push({
          label: t("edit"),
          icon: Pencil,
          onClick: actions.onEdit,
        })

        // Duplicate
        if (actions.onDuplicate) {
          rowActions.push({
            label: t("duplicate"),
            icon: Copy,
            onClick: actions.onDuplicate,
          })
        }

        // Complete (for ACTIVE or ON_HOLD projects)
        if (
          actions.onComplete &&
          (project.status === ProjectStatus.ACTIVE ||
            project.status === ProjectStatus.ON_HOLD)
        ) {
          rowActions.push({
            label: t("markAsCompleted"),
            icon: CheckCircle,
            variant: "default",
            separatorBefore: true,
            onClick: actions.onComplete,
          })
        }

        // Activate (for ARCHIVED projects)
        if (actions.onActivate && project.status === ProjectStatus.ARCHIVED) {
          rowActions.push({
            label: t("activate"),
            icon: RotateCw,
            onClick: actions.onActivate,
          })
        }

        // Archive (for ACTIVE, ON_HOLD, COMPLETED projects)
        if (
          project.status !== ProjectStatus.ARCHIVED &&
          project.status !== ProjectStatus.COMPLETED
        ) {
          rowActions.push({
            label: t("archive"),
            icon: Archive,
            separatorBefore: true,
            onClick: actions.onArchive,
          })
        }

        // Export
        if (actions.onExport) {
          rowActions.push({
            label: t("export"),
            icon: Download,
            onClick: actions.onExport,
          })
        }

        // Delete (always show)
        rowActions.push({
          label: t("delete"),
          icon: Trash2,
          variant: "destructive",
          separatorBefore: true,
          onClick: actions.onDelete,
        })

        return <DataTableRowActions row={project} actions={rowActions} />
      },
    },
  ]
}

"use client"

import { useMemo, useRef, useState } from "react"
import { DataTable } from "@/components/shared/data-table-chunks/data-table"
import {
  createProjectApi,
  updateProjectApi,
  deleteProjectApi,
  archiveProjectApi,
} from "@/lib/api/projects-api"
import { Project, ProjectStatus } from "@/types/projects"
import { useProjectsTable } from "@/hooks/projects/use-projects-table"
import { useEntityMutations } from "@/hooks/tables/use-table-entity-mutations"
import { DataTableEntityFormSheet } from "@/components/shared/data-table-chunks/data-table-entity-form-sheet"
import { ConfirmAlertDialog } from "@/components/ui/confirm-alert-dialog"
import { useTranslations } from "next-intl"
import { toast } from "@/lib/utils/toast"
import { Plus } from "@/components/ui/carbon/icons"
import { ProjectForm, ProjectFormHandle } from "./project-form"
import { getProjectsColumns } from "./projects-columns"
import { ProjectsSummaryCards } from "./projects-summary-cards"
import { ProjectDialog } from "./project-dialog"

type PendingAction =
  | { type: "delete"; project: Project }
  | { type: "archive"; project: Project }
  | { type: "complete"; project: Project }
  | { type: "activate"; project: Project }
  | null

export default function ProjectsPage() {
  const t = useTranslations()
  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<"create" | "edit">("create")
  const [editingProject, setEditingProject] = useState<Project | null>(null)
  const formRef = useRef<ProjectFormHandle>(null)

  const [detailOpen, setDetailOpen] = useState(false)
  const [selectedProject, setSelectedProject] = useState<Project | null>(null)

  const {
    items: projects,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useProjectsTable()

  const { create, isCreating, update, isUpdating, remove, isDeleting } =
    useEntityMutations({
      queryKey: "projects",
      createFn: createProjectApi,
      updateFn: updateProjectApi,
      deleteFn: deleteProjectApi,
      entityLabel: "Project",
    })

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)
  const [isProcessing, setIsProcessing] = useState(false)

  function openCreateForm() {
    setFormMode("create")
    setEditingProject(null)
    setFormOpen(true)
  }

  function openEditForm(project: Project) {
    setFormMode("edit")
    setEditingProject(project)
    setFormOpen(true)
  }

  function handleFormValid(values: any) {
    if (formMode === "create") {
      create(values, { onSuccess: () => setFormOpen(false) })
    } else if (editingProject) {
      update(editingProject.id, values)
      setFormOpen(false)
    }
  }

  async function handleArchive(project: Project) {
    setPendingAction({ type: "archive", project })
  }

  const handleComplete = (project: Project) => {
    setPendingAction({ type: "complete", project })
  }

  const handleActivate = (project: Project) => {
    setPendingAction({ type: "activate", project })
  }

  const handleDuplicate = (project: Project) => {
    const newProject = {
      name: `${project.name} (${t("copy")})`,
      description: project.description,
      status: ProjectStatus.ACTIVE,
      owner: project.owner.id,
      members: project.members.map((m) => m.user.id),
      startDate: new Date().toISOString().split("T")[0],
      endDate: project.endDate,
    }
    create(newProject, {
      onSuccess: () => {
        toast.success(t("projectDuplicated"))
        refresh()
      },
    })
  }

  const handleExport = (project: Project) => {
    const data = JSON.stringify(project, null, 2)
    const blob = new Blob([data], { type: "application/json" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `${project.name}-export.json`
    a.click()
    URL.revokeObjectURL(url)
    toast.success(t("projectExported"))
  }

  async function handleConfirm() {
    if (!pendingAction) return

    setIsProcessing(true)
    try {
      switch (pendingAction.type) {
        case "delete":
          remove(pendingAction.project.id, {
            onSuccess: () => setPendingAction(null),
          })
          break
        case "archive":
          await archiveProjectApi(pendingAction.project.id)
          refresh()
          setPendingAction(null)
          toast.success(t("projectArchived"))
          break
        case "complete":
          await updateProjectApi(pendingAction.project.id, {
            status: ProjectStatus.COMPLETED,
          })
          refresh()
          setPendingAction(null)
          toast.success(t("projectCompleted"))
          break
        case "activate":
          await updateProjectApi(pendingAction.project.id, {
            status: ProjectStatus.ACTIVE,
          })
          refresh()
          setPendingAction(null)
          toast.success(t("projectActivated"))
          break
      }
    } catch (error: any) {
      toast.error(error.message || t("actionFailed"))
    } finally {
      setIsProcessing(false)
    }
  }

  const getDefaultValues = (project: Project | null) => {
    if (!project) return undefined

    return {
      name: project.name,
      description: project.description || "",
      status: project.status,
      owner: project.owner.id,
      members: project.members.map((m) => m.user.id),
      startDate:
        project.startDate?.split("T")[0] ||
        new Date().toISOString().split("T")[0],
      endDate: project.endDate?.split("T")[0] || "",
    }
  }

  const columns = useMemo(
    () =>
      getProjectsColumns(
        {
          onView: (project) => {
            setSelectedProject(project)
            setDetailOpen(true)
          },
          onEdit: openEditForm,
          onArchive: handleArchive,
          onDelete: (project) => setPendingAction({ type: "delete", project }),
          onDuplicate: handleDuplicate,
          onComplete: handleComplete,
          onActivate: handleActivate,
          onExport: handleExport,
        },
        t
      ),
    [t, handleArchive, handleComplete, handleActivate, handleDuplicate, handleExport]
  )

  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.project.name

    switch (pendingAction.type) {
      case "delete":
        return {
          title: t("deleteProject"),
          description: t("deleteProjectConfirmation", { name }),
          confirmLabel: t("delete"),
          destructive: true,
          isLoading: isDeleting || isProcessing,
        }
      case "archive":
        return {
          title: t("archiveProject"),
          description: t("archiveProjectConfirmation", { name }),
          confirmLabel: t("archive"),
          destructive: false,
          isLoading: isProcessing,
        }
      case "complete":
        return {
          title: t("completeProject"),
          description: t("completeProjectConfirmation", { name }),
          confirmLabel: t("complete"),
          destructive: false,
          isLoading: isProcessing,
        }
      case "activate":
        return {
          title: t("activateProject"),
          description: t("activateProjectConfirmation", { name }),
          confirmLabel: t("activate"),
          destructive: false,
          isLoading: isProcessing,
        }
      default:
        return null
    }
  }, [pendingAction, isDeleting, isProcessing, t])

  return (
    <>
      <div className="p-4 md:p-6 space-y-6">
        <ProjectsSummaryCards />

        <DataTable
          manual
          title={t("projects")}
          isLoading={isLoading}
          isFetching={isFetching}
          columns={columns}
          data={projects}
          rowCount={totalItems}
          pageCount={pageCount}
          pagination={pagination}
          onPaginationChange={setPagination}
          columnFilters={columnFilters}
          onColumnFiltersChange={setColumnFilters}
          sorting={sorting}
          onSortingChange={setSorting}
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder={t("searchProjects")}
          actions={[
            {
              label: t("create"),
              onClick: openCreateForm,
              iconOnly: true,
              icon: Plus,
              variant: "primary",
            },
          ]}
          filters={[
            {
              columnId: "status",
              title: t("status"),
              options: [
                { label: t("active"), value: ProjectStatus.ACTIVE },
                { label: t("archived"), value: ProjectStatus.ARCHIVED },
                { label: t("completed"), value: ProjectStatus.COMPLETED },
                { label: t("onHold"), value: ProjectStatus.ON_HOLD },
              ],
            },
          ]}
        />
      </div>

      <DataTableEntityFormSheet
        open={formOpen}
        onOpenChange={setFormOpen}
        mode={formMode}
        createTitle={t("createProject")}
        editTitle={t("editProject")}
        description={
          formMode === "create"
            ? t("createNewProject")
            : t("updateProjectDetails")
        }
        isSubmitting={isCreating || isUpdating}
        onSubmit={() => formRef.current?.submit()}
      >
        <ProjectForm
          ref={formRef}
          mode={formMode}
          defaultValues={getDefaultValues(editingProject)}
          onValid={handleFormValid}
        />
      </DataTableEntityFormSheet>

      <ProjectDialog
        open={detailOpen}
        onOpenChange={setDetailOpen}
        project={selectedProject}
      />

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </>
  )
}

"use client"

import { useMemo } from "react"
import { useTranslations } from "next-intl"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  TrendingUp,
  TrendingDown,
  Users,
  ClipboardCheck,
  Clock,
  FolderArchive,
  Plus,
  Loader2,
} from "@/components/ui/carbon/icons"
import { Project, ProjectStatus } from "@/types/projects"
import { useProjectsSummary } from "@/hooks/projects/use-projects-summary"

interface ProjectsSummaryCardsProps {
  projects?: Project[]
  useApi?: boolean
}

export function ProjectsSummaryCards({
  projects,
  useApi = true,
}: ProjectsSummaryCardsProps) {
  const t = useTranslations()

  const { summary: apiSummary, isLoading, isError } = useProjectsSummary()

  const localSummary = useMemo(() => {
    if (!projects || projects.length === 0) {
      return {
        total: 0,
        active: 0,
        archived: 0,
        completed: 0,
        onHold: 0,
        totalMembers: 0,
        totalTasks: 0,
        completedTasks: 0,
        avgProgress: 0,
      }
    }

    const total = projects.length
    let active = 0
    let archived = 0
    let completed = 0
    let onHold = 0
    let totalMembers = 0
    let totalTasks = 0
    let completedTasks = 0
    let totalProgress = 0

    projects.forEach((project) => {
      if (project.status === ProjectStatus.ACTIVE) active += 1
      else if (project.status === ProjectStatus.ARCHIVED) archived += 1
      else if (project.status === ProjectStatus.COMPLETED) completed += 1
      else if (project.status === ProjectStatus.ON_HOLD) onHold += 1

      totalMembers += project.members?.length || 0
      totalTasks += project.tasks?.length || 0
      completedTasks +=
        project.tasks?.filter((t) => t.status === "done").length || 0
      totalProgress += project.progress || 0
    })

    const avgProgress = total > 0 ? Math.round(totalProgress / total) : 0

    return {
      total,
      active,
      archived,
      completed,
      onHold,
      totalMembers,
      totalTasks,
      completedTasks,
      avgProgress,
    }
  }, [projects])

  const summary = useApi ? apiSummary : localSummary

  if (isLoading && useApi) {
    return (
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
        {[1, 2, 3, 4].map((i) => (
          <Card key={i} className="animate-pulse h-full flex flex-col justify-between">
            <CardHeader className="p-5 pb-3">
              <div className="h-4 w-24 rounded bg-muted" />
              <div className="mt-2 h-8 w-16 rounded bg-muted" />
            </CardHeader>
            <CardFooter className="px-5 py-3 pt-0 border-t-0 mt-auto">
              <div className="h-3 w-32 rounded bg-muted" />
            </CardFooter>
          </Card>
        ))}
      </div>
    )
  }

  if (isError && useApi) {
    return (
      <div className="p-4 text-center text-destructive">
        {t("failedToLoadSummary")}
      </div>
    )
  }

  if (!summary) {
    return (
      <div className="p-4 text-center text-muted-foreground">
        {t("noDataAvailable")}
      </div>
    )
  }

  const cards = [
    {
      key: "total",
      title: t("totalProjects"),
      value: summary.total.toString(),
      valueClassName: "",
      badge: {
        label: `${summary.avgProgress}% ${t("avgProgress")}`,
        icon: TrendingUp,
        variant: "outline" as const,
        className: "gap-1",
      },
      footer: {
        icon: Plus,
        text: t("totalProjectsDescription"),
        subtext: t("totalProjectsSubtext", { members: summary.totalMembers }),
        className: "",
      },
    },
    {
      key: "active",
      title: t("activeProjects"),
      value: summary.active.toString(),
      valueClassName: "text-emerald-600",
      badge: {
        label: t("active"),
        icon: Users,
        variant: "outline" as const,
        className:
          "gap-1 border-emerald-500/20 bg-emerald-500/10 text-emerald-600",
      },
      footer: {
        icon: Clock,
        text: t("activeProjectsDescription"),
        subtext: t("activeProjectsSubtext"),
        className: "text-emerald-600",
      },
    },
    {
      key: "completed",
      title: t("completedProjects"),
      value: (summary.completed + summary.archived).toString(),
      valueClassName: "text-blue-600",
      badge: {
        label: t("completed"),
        icon: ClipboardCheck,
        variant: "outline" as const,
        className: "gap-1 border-blue-500/20 bg-blue-500/10 text-blue-600",
      },
      footer: {
        icon: ClipboardCheck,
        text: t("completedTasksDescription"),
        subtext: t("completedTasksSubtext", {
          tasks: summary.completedTasks,
          total: summary.totalTasks,
        }),
        className: "text-blue-600",
      },
    },
    {
      key: "onHold",
      title: t("onHoldProjects"),
      value: (summary.onHold + summary.archived).toString(),
      valueClassName: "text-amber-600",
      badge: {
        label: t("onHold"),
        icon: FolderArchive,
        variant: "outline" as const,
        className: "gap-1 border-amber-500/20 bg-amber-500/10 text-amber-600",
      },
      footer: {
        icon: TrendingDown,
        text: t("onHoldProjectsDescription"),
        subtext: t("onHoldProjectsSubtext"),
        className: "text-amber-600",
      },
    },
  ]

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
      {cards.map((card) => (
        <Card key={card.key} className="h-full flex flex-col justify-between">
          <CardHeader className="p-5 pb-3">
            <div className="flex items-center justify-between gap-2">
              <CardDescription className="text-xs font-medium uppercase tracking-wider">{card.title}</CardDescription>
              <Badge
                variant={card.badge.variant}
                className={card.badge.className}
              >
                <card.badge.icon className="size-3" />
                {card.badge.label}
              </Badge>
            </div>
