"use client"

import { MouseEvent, useState } from "react"
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion"
import { Checkbox } from "@/components/ui/checkbox"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import { ShieldCheck } from "@/components/ui/carbon/icons"
import {
  PERMISSION_GROUPS,
  AdminPermissionsPlatform,
  RESOURCE_ICONS,
} from "@/types/roles"
import { useTranslations } from "next-intl"

export function PermissionsSelector({
  value,
  onChange,
}: {
  value: AdminPermissionsPlatform[]
  onChange: (permissions: AdminPermissionsPlatform[]) => void
}) {
  const t = useTranslations()
  const [openGroups, setOpenGroups] = useState<string[]>(() =>
    PERMISSION_GROUPS.filter((group) =>
      group.permissions.some((p) => value.includes(p.value))
    ).map((g) => g.resource)
  )

  const toggle = (permission: AdminPermissionsPlatform) => {
    onChange(
      value.includes(permission)
        ? value.filter((p) => p !== permission)
        : [...value, permission]
    )
  }

  const toggleGroup = (
    groupPermissions: AdminPermissionsPlatform[],
    checked: boolean
  ) => {
    onChange(
      checked
        ? Array.from(new Set([...value, ...groupPermissions]))
        : value.filter((p) => !groupPermissions.includes(p))
    )
  }

  return (
    <Accordion
      type="multiple"
      value={openGroups}
      onValueChange={setOpenGroups}
      className="w-full space-y-2"
    >
      {PERMISSION_GROUPS.map((group) => {
        const groupValues = group.permissions.map((p) => p.value)
        const selectedCount = groupValues.filter((p) =>
          value.includes(p)
        ).length
        const allChecked =
          selectedCount === groupValues.length && groupValues.length > 0
        const someChecked = selectedCount > 0 && !allChecked
        const Icon = RESOURCE_ICONS[group.resource]
        const isOpen = openGroups.includes(group.resource)

        // Handle "Select all" click without triggering accordion
        const handleSelectAllClick = (e: MouseEvent) => {
          e.stopPropagation()
        }

        return (
          <AccordionItem
            key={group.resource}
            value={group.resource}
            className={cn(
              "group overflow-hidden rounded-xl border bg-background shadow-sm transition-all duration-200",
              isOpen && "shadow-md ring-1 ring-primary/10"
            )}
          >
            <AccordionTrigger className="px-4 py-3.5 hover:no-underline [&>svg]:size-4 [&>svg]:shrink-0 [&>svg]:transition-transform [&>svg]:duration-200">
              <div className="flex flex-1 items-center gap-3">
                <div onClick={handleSelectAllClick}>
                  <Checkbox
                    checked={
                      allChecked ? true : someChecked ? "indeterminate" : false
                    }
                    onCheckedChange={(checked) =>
                      toggleGroup(groupValues, checked === true)
                    }
                    className="size-5"
                  />
                </div>
                <div
                  className={cn(
                    "flex size-9 shrink-0 items-center justify-center rounded-lg transition-colors",
                    selectedCount > 0
                      ? "bg-primary/10 text-primary"
                      : "bg-muted text-muted-foreground"
                  )}
                >
                  {Icon ? (
                    <Icon className="size-4" />
                  ) : (
                    <ShieldCheck className="size-4" />
                  )}
                </div>

                <span className="text-sm font-semibold text-foreground">
                  {group.label}
                </span>

                <div className="ml-auto flex items-center gap-2">
                  <Badge
                    variant={selectedCount > 0 ? "default" : "secondary"}
                    className={cn(
                      "px-2 py-0.5 text-xs font-medium tabular-nums",
                      selectedCount === 0
                        ? "bg-muted text-muted-foreground"
                        : "bg-primary/10 text-primary"
                    )}
                  >
                    {selectedCount}/{groupValues.length}
                  </Badge>
                </div>
              </div>
            </AccordionTrigger>

            <AccordionContent className="px-4 pb-4">
              {/* Permission checkboxes grid */}
              <div className="flex flex-wrap items-center justify-center gap-3">
                {group.permissions.map((permission) => {
                  const checked = value.includes(permission.value)
                  return (
                    <label
                      key={permission.value}
                      className={cn(
                        "flex grow cursor-pointer items-center justify-center gap-2.5 rounded-lg border px-3 py-2.5 text-sm transition-all duration-150",
                        "hover:border-primary/30",
                        checked
                          ? "border-primary/40 bg-primary/15 shadow-sm"
                          : "border-transparent bg-muted/50 hover:bg-muted"
                      )}
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => toggle(permission.value)}
                        className={cn(
                          "size-4 transition-transform",
                          checked && "scale-110"
                        )}
                      />
                      <span
                        className={cn(
                          "truncate font-medium transition-colors",
                          checked ? "text-foreground" : "text-muted-foreground"
                        )}
                      >
                        {permission.label}
                      </span>
                    </label>
                  )
                })}
              </div>
            </AccordionContent>
          </AccordionItem>
        )
      })}
    </Accordion>
  )
}

"use client"

import { useMemo, useRef, useState } from "react"
import { DataTable } from "../data-table-chunks/data-table"
import { getRolesColumns } from "./roles-columns"
import { RoleForm, RoleFormHandle } from "./role-form"
import {
  createRoleApi,
  updateRoleApi,
  deleteRoleApi,
  toggleRoleStatusApi,
} from "@/lib/api/roles-apis"
import { Role } from "@/types/roles"
import { useFetchRolesTable } from "@/hooks/roles/use-fetch-roles-table"
import { useEntityMutations } from "@/hooks/tables/use-table-entity-mutations"
import { ConfirmAlertDialog } from "@/components/ui/confirm-alert-dialog"
import { DataTableEntityFormDialog } from "../data-table-chunks/data-table-entity-form-dialog"
import { useTranslations } from "next-intl"
import { ActivationStatus } from "@/types/users"
import { Plus } from "@/components/ui/carbon/icons"

type PendingAction =
  | { type: "delete"; role: Role }
  | { type: "deactivate"; role: Role }
  | { type: "activate"; role: Role }
  | null

export default function RolesPage() {
  const t = useTranslations()

  const {
    items: roles,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useFetchRolesTable()

  const { create, isCreating, update, isUpdating, remove, isDeleting } =
    useEntityMutations({
      queryKey: "roles",
      createFn: createRoleApi,
      updateFn: updateRoleApi,
      deleteFn: deleteRoleApi,
      entityLabel: "Role",
    })

  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<"create" | "edit">("create")
  const [editingRole, setEditingRole] = useState<Role | null>(null)
  const formRef = useRef<RoleFormHandle>(null)

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)
  const [isStatusLoading, setIsStatusLoading] = useState(false)

  function openCreateForm() {
    setFormMode("create")
    setEditingRole(null)
    setFormOpen(true)
  }

  function openEditForm(role: Role) {
    setFormMode("edit")
    setEditingRole(role)
    setFormOpen(true)
  }

  function handleFormValid(values: any) {
    if (formMode === "create") {
      create(values, { onSuccess: () => setFormOpen(false) })
    } else if (editingRole) {
      update(editingRole.id, values)
      setFormOpen(false)
    }
  }

  async function handleConfirm() {
    if (!pendingAction) return

    if (pendingAction.type === "delete") {
      remove(pendingAction.role.id, {
        onSuccess: () => setPendingAction(null),
      })
      return
    }

    // Activate/Deactivate go through a dedicated status toggle, so we
    // handle their loading state locally, same as ban/activate for users
    setIsStatusLoading(true)
    try {
      const nextStatus =
        pendingAction.type === "deactivate"
          ? ActivationStatus.INACTIVE
          : ActivationStatus.ACTIVE

      await toggleRoleStatusApi(pendingAction.role.id, nextStatus)
      refresh()
      setPendingAction(null)
    } finally {
      setIsStatusLoading(false)
    }
  }

  const columns = useMemo(
    () =>
      getRolesColumns(
        {
          onEdit: openEditForm,
          onDeactivate: (role) =>
            setPendingAction({ type: "deactivate", role }),
          onActivate: (role) => setPendingAction({ type: "activate", role }),
          onDelete: (role) => setPendingAction({ type: "delete", role }),
        },
        t
      ),
    [t]
  )

  // Dialog copy per action type, kept in one place
  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.role.name

    switch (pendingAction.type) {
      case "delete":
        return {
          title: t("deleteRoleTitle"),
          description: t("deleteRoleConfirmation", { name }),
          confirmLabel: t("delete"),
          destructive: true,
          isLoading: isDeleting,
        }
      case "deactivate":
        return {
          title: t("deactivateRoleTitle"),
          description: t("deactivateRoleConfirmation", { name }),
          confirmLabel: t("deactivate"),
          destructive: true,
          isLoading: isStatusLoading,
        }
      case "activate":
        return {
          title: t("activateRoleTitle"),
          description: t("activateRoleConfirmation", { name }),
          confirmLabel: t("activate"),
          destructive: false,
          isLoading: isStatusLoading,
        }
    }
  }, [pendingAction, isDeleting, isStatusLoading, t])

  return (
    <div className="p-4 md:p-6 space-y-6">
      <DataTable
        manual
        title={t("roles")}
        isLoading={isLoading}
        isFetching={isFetching}
        columns={columns}
        data={roles}
        rowCount={totalItems}
        pageCount={pageCount}
        pagination={pagination}
        onPaginationChange={setPagination}
        columnFilters={columnFilters}
        onColumnFiltersChange={setColumnFilters}
        sorting={sorting}
        onSortingChange={setSorting}
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder={t("searchRoles")}
        actions={[
          {
            label: t("create"),
            onClick: () => openCreateForm(),
            iconOnly: true,
            icon: Plus,
            variant: "primary",
          },
        ]}
        filters={[
          {
            columnId: "status",
            title: t("status"),
            options: [
              { label: t("active"), value: ActivationStatus.ACTIVE },
              { label: t("inactive"), value: ActivationStatus.INACTIVE },
            ],
          },
        ]}
      />
      <DataTableEntityFormDialog
        open={formOpen}
        onOpenChange={setFormOpen}
        mode={formMode}
        createTitle={t("addRole")}
        style={{ maxWidth: "600px" }}
        editTitle={t("editRole")}
        description={
          formMode === "create" ? t("createNewRole") : t("updateRoleDetails")
        }
        isSubmitting={isCreating || isUpdating}
        onSubmit={() => formRef.current?.submit()}
      >
        <RoleForm
          ref={formRef}
          mode={formMode}
          defaultValues={editingRole ?? undefined}
          onValid={handleFormValid}
        />
      </DataTableEntityFormDialog>

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </div>
  )
}

"use client"

import { useMemo, useRef, useState } from "react"
import { useRouter } from "next/navigation"
import { DataTable } from "../data-table-chunks/data-table"
import { getStaffsColumns } from "./staffs-columns"
import { StaffForm, UserFormHandle } from "./staff-form"
import {
  createUserApi,
  updateUserApi,
  deleteUserApi,
  toggleBanUserApi,
} from "@/lib/api/users-apis"
import { User, UserStatus, UserType } from "@/types/users"
import { useUsersTable } from "@/hooks/users/use-users-table"
import { useEntityMutations } from "@/hooks/tables/use-table-entity-mutations"
import { DataTableEntityFormSheet } from "../data-table-chunks/data-table-entity-form-sheet"
import { ConfirmAlertDialog } from "@/components/ui/confirm-alert-dialog"
import { useTranslations } from "next-intl"
import { Plus } from "@/components/ui/carbon/icons"
import { StaffsSummaryCards } from "./staffs-summary-cards"

type PendingAction =
  | { type: "delete"; user: User }
  | { type: "ban"; user: User }
  | { type: "activate"; user: User }
  | null

export default function StaffsPage() {
  const t = useTranslations()
  const router = useRouter()

  const {
    items: users,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useUsersTable({
    defaultFilters: [
      {
        field: "userType",
        operator: "eq",
        value: UserType.STAFF,
      },
    ],
  })

  const { create, isCreating, update, isUpdating, remove, isDeleting } =
    useEntityMutations({
      queryKey: "users",
      createFn: createUserApi,
      updateFn: updateUserApi,
      deleteFn: deleteUserApi,
      entityLabel: "Staff",
    })

  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<"create" | "edit">("create")
  const [editingUser, setEditingUser] = useState<User | null>(null)
  const formRef = useRef<UserFormHandle>(null)

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)
  const [isBanLoading, setIsBanLoading] = useState(false)

  function openCreateForm() {
    setFormMode("create")
    setEditingUser(null)
    setFormOpen(true)
  }

  function openEditForm(user: User) {
    setFormMode("edit")
    setEditingUser(user)
    setFormOpen(true)
  }

  function handleFormValid(values: any) {
    if (formMode === "create") {
      create(values, { onSuccess: () => setFormOpen(false) })
    } else if (editingUser) {
      update(editingUser.id, values)
      setFormOpen(false)
    }
  }

  async function handleConfirm() {
    if (!pendingAction) return

    if (pendingAction.type === "delete") {
      remove(pendingAction.user.id, {
        onSuccess: () => setPendingAction(null),
      })
      return
    }

    // Ban/Activate don't go through useEntityMutations (they use a
    // dedicated toggle endpoint), so we handle their loading state locally
    setIsBanLoading(true)
    try {
      if (pendingAction.type === "ban") {
        await toggleBanUserApi(pendingAction.user.id, true)
      } else if (pendingAction.type === "activate") {
        await toggleBanUserApi(pendingAction.user.id, false)
      }
      refresh()
      setPendingAction(null)
    } finally {
      setIsBanLoading(false)
    }
  }

  const columns = useMemo(
    () =>
      getStaffsColumns(
        {
          onView: (user) => router.push(`/users/${user.id}`),
          onEdit: openEditForm,
          onSuspend: (user) => setPendingAction({ type: "ban", user }),
          onActivate: (user) => setPendingAction({ type: "activate", user }),
          onDelete: (user) => setPendingAction({ type: "delete", user }),
        },
        t
      ),
    [router, t]
  )

  // Dialog copy per action type, kept in one place
  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.user.name

    switch (pendingAction.type) {
      case "delete":
        return {
          title: t("deleteUser"),
          description: t("deleteUserConfirmation", { name }),
          confirmLabel: t("delete"),
          destructive: true,
          isLoading: isDeleting,
        }
      case "ban":
        return {
          title: t("banUser"),
          description: t("banUserConfirmation", { name }),
          confirmLabel: t("ban"),
          destructive: true,
          isLoading: isBanLoading,
        }
      case "activate":
        return {
          title: t("unbanUser"),
          description: t("unbanUserConfirmation", { name }),
          confirmLabel: t("unban"),
          destructive: false,
          isLoading: isBanLoading,
        }
    }
  }, [pendingAction, isDeleting, isBanLoading, t])

  return (
    <div className="p-4 md:p-6 space-y-6">
      <StaffsSummaryCards
        users={users}
        totalCount={totalItems}
        isLoading={isLoading}
      />
      <DataTable
        manual
        title={t("staffs")}
        isLoading={isLoading}
        isFetching={isFetching}
        columns={columns}
        data={users}
        rowCount={totalItems}
        pageCount={pageCount}
        pagination={pagination}
        onPaginationChange={setPagination}
        columnFilters={columnFilters}
        onColumnFiltersChange={setColumnFilters}
        sorting={sorting}
        onSortingChange={setSorting}
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder={t("searchByNameEmailUsername")}
        actions={[
          {
            label: t("create"),
            onClick: () => openCreateForm(),
            iconOnly: true,
            icon: Plus,
            variant: "primary",
          },
        ]}
        filters={[
          {
            columnId: "status",
            title: t("status"),
            options: [
              { label: t("active"), value: UserStatus.ACTIVE },
              { label: t("inactive"), value: UserStatus.INACTIVE },
              { label: t("notVerified"), value: UserStatus.NOT_VERIFIED },
              { label: t("banned"), value: UserStatus.BANNED },
            ],
          },
        ]}
      />

      <DataTableEntityFormSheet
        open={formOpen}
        onOpenChange={setFormOpen}
        mode={formMode}
        createTitle={t("addStaff")}
        editTitle={t("editStaff")}
        description={
          formMode === "create" ? t("createNewStaff") : t("updateStaffDetails")
        }
        isSubmitting={isCreating || isUpdating}
        onSubmit={() => formRef.current?.submit()}
      >
        <StaffForm
          ref={formRef}
          mode={formMode}
          defaultValues={editingUser ?? undefined}
          onValid={handleFormValid}
        />
      </DataTableEntityFormSheet>

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </div>
  )
}

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { StatusBadge } from "@/components/ui/status-badge"
import {
  Ban,
  ExternalLink,
  Pencil,
  Trash2,
  Eye,
  CheckCircle,
  RefreshCw,
} from "@/components/ui/carbon/icons"
import { DataTableColumnHeader } from "@/components/shared/data-table-chunks/data-table-column-header"
import {
  DataTableRowActions,
  RowAction,
} from "@/components/shared/data-table-chunks/data-table-row-actions"
import { SpaceAvatar } from "@/components/ui/space-avatar"
import { Subscription, SubscriptionStatus } from "@/types/subscriptions"

export interface SubscriptionsColumnActions {
  onViewUser: (subscription: Subscription) => void
  onEdit: (subscription: Subscription) => void
  onDelete: (subscription: Subscription) => void
  onCancel: (subscription: Subscription) => void
  onActivate?: (subscription: Subscription) => void
  onViewDetails?: (subscription: Subscription) => void
  onRenew?: (subscription: Subscription) => void
}

export function getSubscriptionsColumns(
  actions: SubscriptionsColumnActions,
  t: (key: string) => string
): ColumnDef<Subscription, any>[] {
  const STATUS_CONFIG: Record<
    SubscriptionStatus,
    { label: string; className: string }
  > = {
    [SubscriptionStatus.ACTIVE]: {
      label: t("active"),
      className:
        "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-transparent",
    },

    [SubscriptionStatus.INACTIVE]: {
      label: t("inactive"),
      className:
        "bg-slate-500/10 text-slate-700 dark:text-slate-400 border-transparent",
    },

    [SubscriptionStatus.CANCELED]: {
      label: t("canceled"),
      className:
        "bg-red-500/10 text-red-700 dark:text-red-400 border-transparent",
    },

    [SubscriptionStatus.EXPIRED]: {
      label: t("expired"),
      className:
        "bg-orange-500/10 text-orange-700 dark:text-orange-400 border-transparent",
    },

    [SubscriptionStatus.PAST_DUE]: {
      label: t("pastDue"),
      className:
        "bg-rose-500/10 text-rose-700 dark:text-rose-400 border-transparent",
    },
  }

  return [
    {
      id: "user",
      accessorFn: (row) => row.user?.name ?? row.name,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("user")} />
      ),
      cell: ({ row }) => {
        const sub = row.original
        return (
          <div className="flex items-center gap-3">
            <SpaceAvatar
              name={sub.user?.name ?? sub.name}
              src={sub.user?.avatar || ""}
              size="sm"
            />
            <div>
              <p className="text-sm font-medium md:text-base">
                {sub.user?.name ?? sub.name}
              </p>
              <p className="text-xs text-muted-foreground md:text-sm">
                {sub.user?.email ?? sub.description}
              </p>
            </div>
          </div>
        )
      },
    },
    {
      id: "planName",
      accessorFn: (row) => row.plan?.name ?? row.name,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("plan")} />
      ),
      cell: ({ row }) => (
        <span className="text-sm font-medium">
          {row.original.plan?.name ?? row.original.name}
        </span>
      ),
    },
    {
      id: "price",
      accessorFn: (row) => row.plan?.price ?? row.price,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("price")} />
      ),
      cell: ({ row }) => {
        const plan = row.original.plan
        const price = row.original.price
        return (
          <span className="text-sm tabular-nums">
            {plan ? `$${plan.price}` : price}
            <span className="text-muted-foreground">
              {" "}
              / {plan?.period ?? row.original.period ?? t("month")}
            </span>
          </span>
        )
      },
    },
    {
      accessorKey: "billingCycle",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("billingCycle")} />
      ),
      cell: ({ row }) => (
        <span className="inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium text-muted-foreground capitalize">
          {row.original.billingCycle ?? t("monthly")}
        </span>
      ),
    },
    {
      accessorKey: "status",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("status")} />
      ),
      cell: ({ row }) => (
        <StatusBadge value={row.original.status} config={STATUS_CONFIG} />
      ),
    },
    {
      accessorKey: "nextBilling",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("nextBilling")} />
      ),
      cell: ({ row }) => {
        const date = row.original.nextBilling
        return date ? (
          <span className="text-sm tabular-nums">
            {new Date(date).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            })}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">—</span>
        )
      },
    },
    {
      id: "actions",
      cell: ({ row }) => {
        const sub = row.original
        const rowActions: RowAction<Subscription>[] = []

        rowActions.push({
          label: t("viewUser"),
          icon: ExternalLink,
          onClick: actions.onViewUser,
        })

        if (actions.onViewDetails) {
          rowActions.push({
            label: t("viewDetails"),
            icon: Eye,
            onClick: actions.onViewDetails,
          })
        }

        rowActions.push({
          label: t("edit"),
          icon: Pencil,
          separatorBefore: true,
          onClick: actions.onEdit,
        })

        if (
          actions.onActivate &&
          (sub.status === SubscriptionStatus.INACTIVE ||
            sub.status === SubscriptionStatus.CANCELED)
        ) {
          rowActions.push({
            label: t("activate"),
            icon: CheckCircle,
            onClick: actions.onActivate,
          })
        }

        if (sub.status === SubscriptionStatus.ACTIVE) {
          rowActions.push({
            label: t("cancel"),
            icon: Ban,
            variant: "destructive",
            separatorBefore: true,
            onClick: actions.onCancel,
          })
        }

        if (
          actions.onRenew &&
          (sub.status === SubscriptionStatus.EXPIRED ||
            sub.status === SubscriptionStatus.PAST_DUE)
        ) {
          rowActions.push({
            label: t("renew"),
            icon: RefreshCw,
            onClick: actions.onRenew,
          })
        }

        rowActions.push({
          label: t("delete"),
          icon: Trash2,
          variant: "destructive",
          separatorBefore: true,
          onClick: actions.onDelete,
        })

        return <DataTableRowActions row={sub} actions={rowActions} />
      },
    },
  ]
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { useTranslations } from "next-intl"
import { useQuery } from "@tanstack/react-query"
import {
  Purchase,
  Security,
  ArrowUpRight,
  Launch,
  Renew,
  Calendar,
  CheckmarkFilled,
} from "@carbon/icons-react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { billingApi, createPortalApi } from "@/lib/api/billing-apis"
import { apiErrorMessage } from "@/lib/myapi/client"
import { toast } from "@/lib/utils/toast"
import { InlineNotification, ActionableNotification } from "@/components/ui/carbon/notification"
import { UsageMeteringCard } from "./usage-metering-card"

export default function SubscriptionsPage() {
  const t = useTranslations()
  const router = useRouter()
  const [isOpeningPortal, setIsOpeningPortal] = useState(false)
  const [billingNotice, setBillingNotice] = useState<string | null>(null)

  const {
    data: subscription,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["billing-subscription"],
    queryFn: billingApi.getSubscription,
    retry: false,
  })

  const currentPlan = (subscription?.plan ?? "free").toUpperCase()
  const status = subscription?.status ?? "active"
  const isPastDue = status === "past_due"
  const hasAccess = subscription?.access ?? true

  const [now] = useState(() => Date.now())

  // Dunning calculation
  const dunningDaysRemaining = useMemo(() => {
    if (!isPastDue || !subscription?.graceUntil) return null
    const diffMs = new Date(subscription.graceUntil).getTime() - now
    return Math.max(0, Math.ceil(diffMs / (1000 * 60 * 60 * 24)))
  }, [isPastDue, subscription?.graceUntil, now])

  const handleManageBilling = async () => {
    setIsOpeningPortal(true)
    try {
      const { url } = await createPortalApi()
      if (url) {
        window.location.assign(url)
      }
    } catch (err: any) {
      if (
        err?.response?.status === 501 ||
        err?.response?.data?.code === "billing_not_configured"
      ) {
        const msg = "Billing is not configured in this environment (Stripe keys not set)."
        setBillingNotice(msg)
        toast.info(msg)
      } else if (
        err?.response?.status === 400 &&
        err?.response?.data?.code === "no_customer"
      ) {
        toast.error("No billing profile found yet. Please subscribe to a plan first.")
      } else {
        toast.error(apiErrorMessage(err, "Failed to open billing portal."))
      }
    } finally {
      setIsOpeningPortal(false)
    }
  }

  if (isLoading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="h-10 w-10 animate-spin rounded-full border-b-2 border-primary" />
      </div>
    )
  }

  return (
    <div className="h-full w-full space-y-6 overflow-auto p-4 pb-24 md:p-6 md:pb-28">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground md:text-3xl">
            {t("subscriptions")}
          </h1>
          <p className="text-sm text-muted-foreground">
            Manage your workspace subscription, billing details, and payment method.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            onClick={() => router.push("/dashboard/plans")}
            className="gap-2"
          >
            Change Plan
            <ArrowUpRight className="size-4" />
          </Button>
          <Button
            variant="primary"
            onClick={handleManageBilling}
            disabled={isOpeningPortal}
            className="gap-2"
          >
            {isOpeningPortal ? (
              <Renew className="size-4 animate-spin" />
            ) : (
              <Purchase className="size-4" />
            )}
            Manage Subscription
          </Button>
        </div>
      </div>

      {/* Subscription Service Unavailable Banner */}
      {isError && (
        <InlineNotification
          kind="error"
          title="Subscription Data Unavailable"
          subtitle="Unable to connect to the billing service. Subscription status cannot be refreshed."
          lowContrast
          hideCloseButton
          className="w-full mb-2"
        />
      )}

      {/* 501 Billing Not Configured Banner */}
      {billingNotice && (
        <InlineNotification
          kind="info"
          title="Billing Not Configured"
          subtitle={billingNotice}
          lowContrast
          onCloseButtonClick={() => setBillingNotice(null)}
          className="w-full mb-2"
        />
      )}

      {/* Dunning Grace Banner */}
      {isPastDue && (
        <ActionableNotification
          kind={hasAccess ? "warning" : "error"}
          title={
            hasAccess
              ? "Payment Past Due — Grace Period Active"
              : "Grace Period Expired — Access Suspended"
          }
          subtitle={
            hasAccess
              ? `Your recent payment failed. You have ${
                  dunningDaysRemaining ?? 7
                } days remaining in your dunning grace period before workspace features are locked.`
              : "Your 7-day grace period has expired. Account access is now locked. Please update your payment method to regain full access."
          }
          actionButtonLabel="Update Payment Method"
          onActionButtonClick={handleManageBilling}
          lowContrast
          hideCloseButton
          className="w-full mb-2"
        />
      )}

      {/* Current Plan Overview Card */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        <Card className="md:col-span-2">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardDescription>Current Workspace Tier</CardDescription>
                <CardTitle className="text-2xl font-bold flex items-center gap-3 mt-1">
                  <span>{currentPlan} Plan</span>
                  <Badge
                    variant={status === "active" ? "outline" : "destructive"}
                    className={
                      status === "active"
                        ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 capitalize"
                        : "border-red-500/30 bg-red-500/15 text-red-700 dark:text-red-300 capitalize font-semibold"
                    }
                  >
                    {status}
                  </Badge>
                </CardTitle>
              </div>
              <Security className="size-8 text-primary opacity-80" />
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              {currentPlan === "ENTERPRISE"
                ? "Your workspace is on the Enterprise tier with unlimited scale and dedicated SLA."
                : currentPlan === "PRO"
                ? "Your workspace is on the Pro tier with power tools, priority support, and higher limits."
                : "Your workspace is currently on the Free tier. Upgrade at any time for advanced features."}
            </p>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
              <div className="flex items-center gap-3 rounded-lg border p-3">
                <Calendar className="size-4 text-muted-foreground" />
                <div>
                  <div className="text-xs text-muted-foreground">Renewal Date</div>
                  <div className="text-sm font-medium">
                    {subscription?.currentPeriodEnd
                      ? new Date(subscription.currentPeriodEnd).toLocaleDateString()
                      : "No active renewal"}
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 rounded-lg border p-3">
                <Purchase className="size-4 text-muted-foreground" />
                <div>
                  <div className="text-xs text-muted-foreground">Payment Method</div>
                  <div className="text-sm font-medium">
                    {subscription?.hasPaymentMethod
                      ? "Card on file (Stripe)"
                      : "None configured"}
                  </div>
                </div>
              </div>
            </div>
          </CardContent>
          <CardFooter className="flex items-center justify-between border-t pt-4">
            <div className="text-xs text-muted-foreground flex items-center gap-1.5">
              <CheckmarkFilled className="size-4 text-emerald-600" />
              <span>
                {hasAccess
                  ? "All plan features active and accessible"
                  : "Access temporarily suspended"}
              </span>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleManageBilling}
              disabled={isOpeningPortal}
              className="gap-1.5"
            >
              <span>Stripe Portal</span>
              <Launch className="size-3.5" />
            </Button>
          </CardFooter>
        </Card>

        {/* Quick Upgrade Callout */}
        <Card className="flex flex-col justify-between">
          <CardHeader>
            <CardTitle className="text-lg font-semibold">Need More Power?</CardTitle>
            <CardDescription>
              Explore plans to unlock higher rate limits, full API access, and team collaboration.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-2 text-sm text-muted-foreground">
            <div className="flex items-center gap-2">
              <CheckmarkFilled className="size-4 text-primary" />
              <span>Priority Support & SLA</span>
            </div>
            <div className="flex items-center gap-2">
              <CheckmarkFilled className="size-4 text-primary" />
              <span>Full API & Webhooks Access</span>
            </div>
            <div className="flex items-center gap-2">
              <CheckmarkFilled className="size-4 text-primary" />
              <span>Audit Logging & Analytics</span>
            </div>
          </CardContent>
          <CardFooter>
            <Button
              variant="primary"
              className="w-full"
              onClick={() => router.push("/dashboard/plans")}
            >
              View All Plans
            </Button>
          </CardFooter>
        </Card>
      </div>

      {/* Real-time Quota & Usage Metering */}
      <UsageMeteringCard className="mt-6" />
    </div>
  )
}

"use client"

import { useMemo } from "react"
import { useTranslations } from "next-intl"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  TrendingDown,
  TrendingUp,
  DollarSign,
  Clock,
  AlertCircle,
  CheckCircle,
  Users,
} from "@/components/ui/carbon/icons"
import {
  Subscription,
  SubscriptionStatus,
  SubscriptionsSummary,
} from "@/types/subscriptions"
import { useSubscriptionsSummary } from "@/hooks/subscriptions/use-subscriptions-summary"

interface SubscriptionsSummaryCardsProps {
  subscriptions?: Subscription[]
  useApi?: boolean
}

export function SubscriptionsSummaryCards({
  subscriptions,
  useApi = true,
}: SubscriptionsSummaryCardsProps) {
  const t = useTranslations()

  const { summary: apiSummary, isLoading, isError } = useSubscriptionsSummary()

  const localSummary = useMemo<SubscriptionsSummary>(() => {
    if (!subscriptions || subscriptions.length === 0) {
      return {
        totalRevenue: 0,
        totalSubscriptions: 0,
        active: 0,
        inactive: 0,
        pending: 0,
        expired: 0,
        canceled: 0,
        activePercentage: 0,
        revenueGrowth: 0,
      }
    }

    let totalRevenue = 0
    let active = 0
    let inactive = 0
    let pending = 0
    let expired = 0
    let canceled = 0

    subscriptions.forEach((subscription) => {
      switch (subscription.status) {
        case SubscriptionStatus.ACTIVE:
          const price =
            subscription.plan?.price ?? (parseFloat(subscription.price) || 0)
          totalRevenue += price
          active += 1
          break
        case SubscriptionStatus.INACTIVE:
          inactive += 1
          break
        case SubscriptionStatus.PAST_DUE:
          pending += 1
          break
        case SubscriptionStatus.EXPIRED:
          expired += 1
          break
        case SubscriptionStatus.CANCELED:
          canceled += 1
          break
        default:
          break
      }
    })

    return {
      totalRevenue,
      totalSubscriptions: subscriptions.length,
      active,
      inactive,
      pending,
      expired,
      canceled,
      activePercentage:
        subscriptions.length > 0
          ? Math.round((active / subscriptions.length) * 100)
          : 0,
      revenueGrowth: 12.5,
    }
  }, [subscriptions])

  const summary = useApi ? apiSummary : localSummary

  if (isLoading && useApi) {
    return (
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
        {[1, 2, 3, 4].map((i) => (
          <Card key={i} className="animate-pulse h-full flex flex-col justify-between">
            <CardHeader className="p-5 pb-3">
              <div className="h-4 w-24 rounded bg-muted" />
              <div className="mt-2 h-8 w-16 rounded bg-muted" />
            </CardHeader>
            <CardFooter className="px-5 py-3 pt-0 border-t-0 mt-auto">
              <div className="h-3 w-32 rounded bg-muted" />
            </CardFooter>
          </Card>
        ))}
      </div>
    )
  }

  if (isError && useApi) {
    return (
      <div className="p-4 text-center text-destructive">
        {t("failedToLoadSummary")}
      </div>
    )
  }

  if (!summary) {
    return (
      <div className="p-4 text-center text-muted-foreground">
        {t("noDataAvailable")}
      </div>
    )
  }

  // Helper function to safely format numbers
  const formatCurrency = (value: any): string => {
    const num = Number(value)
    return isNaN(num) ? "$0.00" : `$${num.toFixed(2)}`
  }

  const formatNumber = (value: any): string => {
    const num = Number(value)
    return isNaN(num) ? "0" : num.toString()
  }

  const formatPercentage = (value: any): string => {
    const num = Number(value)
    return isNaN(num) ? "0%" : `${num}%`
  }

  const cardsData = [
    {
      key: "totalRevenue",
      title: t("totalRevenue"),
      value: formatCurrency(summary.totalRevenue),
      valueClassName: "",
      badge: {
        label: `+${formatPercentage(summary.revenueGrowth)}`,
        icon: TrendingUp,
        variant: "outline" as const,
        className: "gap-1",
      },
      footer: {
        icon: DollarSign,
        text: t("totalRevenueDescription"),
        subtext: t("totalRevenueSubtext"),
        className: "",
      },
    },
    {
      key: "active",
      title: t("activeSubscriptions"),
      value: formatNumber(summary.active),
      valueClassName: "text-emerald-600",
      badge: {
        label: formatPercentage(summary.activePercentage),
        icon: CheckCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-emerald-500/20 bg-emerald-500/10 text-emerald-600",
      },
      footer: {
        icon: Users,
        text: t("activeSubscriptions"),
        subtext: t("activeSubscriptionsSubtext"),
        className: "text-emerald-600",
      },
    },
    {
      key: "pending",
      title: t("pendingSubscriptions"),
      value: formatNumber((summary.pending || 0) + (summary.inactive || 0)),
      valueClassName: "text-amber-600",
      badge: {
        label: t("pending"),
        icon: Clock,
        variant: "outline" as const,
        className: "gap-1 border-amber-500/20 bg-amber-500/10 text-amber-600",
      },
      footer: {
        icon: Clock,
        text: t("pendingSubscriptions"),
        subtext: t("pendingSubscriptionsSubtext"),
        className: "text-amber-600",
      },
    },
    {
      key: "expired",
      title: t("expiredCancelled"),
      value: formatNumber((summary.expired || 0) + (summary.canceled || 0)),
      valueClassName: "text-destructive",
      badge: {
        label: t("inactive"),
        icon: AlertCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-destructive/20 bg-destructive/10 text-destructive",
      },
      footer: {
        icon: TrendingDown,
        text: t("expiredCancelledSubscriptions"),
        subtext: t("expiredCancelledSubtext"),
        className: "text-destructive",
      },
    },
  ]

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
      {cardsData.map((card) => (
        <Card key={card.key} className="h-full flex flex-col justify-between">
          <CardHeader className="p-5 pb-3">
            <div className="flex items-center justify-between gap-2">
              <CardDescription className="text-xs font-medium uppercase tracking-wider">{card.title}</CardDescription>
              <Badge
                variant={card.badge.variant}
                className={card.badge.className}
              >
                <card.badge.icon className="size-3" />
                {card.badge.label}
              </Badge>
            </div>
            <CardTitle
              className={`text-2xl font-bold font-mono tabular-nums @[250px]/card:text-3xl mt-2 ${card.valueClassName}`}
            >
              {card.value}
            </CardTitle>
          </CardHeader>
          <CardFooter className="px-5 py-3 pt-0 border-t-0 flex items-center gap-1.5 text-xs text-muted-foreground mt-auto">
            <card.footer.icon className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="truncate font-medium">{card.footer.text}</span>
          </CardFooter>
        </Card>
      ))}
    </div>
  )
}

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { DataTableColumnHeader } from "@/components/shared/data-table-chunks/data-table-column-header"
import {
  DataTableRowActions,
  RowAction,
} from "@/components/shared/data-table-chunks/data-table-row-actions"
import { SpaceAvatar } from "@/components/ui/space-avatar"
import { StatusBadge } from "@/components/ui/status-badge"
import {
  Transaction,
  TransactionStatus,
  TransactionMethod,
} from "@/types/transactions"
import {
  Eye,
  Ban,
  RotateCcw,
  Pencil,
  Trash2,
  RefreshCw,
  CheckCircle,
  FileText,
  Printer,
} from "@/components/ui/carbon/icons"

export interface TransactionsColumnActions {
  onView: (transaction: Transaction) => void
  onEdit: (transaction: Transaction) => void
  onDelete: (transaction: Transaction) => void
  onRefund: (transaction: Transaction) => void
  onCancel: (transaction: Transaction) => void
  onRetry?: (transaction: Transaction) => void
  onMarkAsPaid?: (transaction: Transaction) => void
  onDownloadReceipt?: (transaction: Transaction) => void
  onPrint?: (transaction: Transaction) => void
}

export function getTransactionsColumns(
  actions: TransactionsColumnActions,
  t: (key: string) => string
): ColumnDef<Transaction, any>[] {
  const STATUS_CONFIG: Record<
    TransactionStatus,
    { label: string; className: string }
  > = {
    [TransactionStatus.PAID]: {
      label: t("paid"),
      className:
        "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-transparent",
    },

    [TransactionStatus.PENDING]: {
      label: t("pending"),
      className:
        "bg-amber-500/10 text-amber-700 dark:text-amber-400 border-transparent",
    },

    [TransactionStatus.FAILED]: {
      label: t("failed"),
      className:
        "bg-red-500/10 text-red-700 dark:text-red-400 border-transparent",
    },

    [TransactionStatus.CANCELED]: {
      label: t("canceled"),
      className:
        "bg-slate-500/10 text-slate-700 dark:text-slate-400 border-transparent",
    },

    [TransactionStatus.REFUNDED]: {
      label: t("refunded"),
      className:
        "bg-blue-500/10 text-blue-700 dark:text-blue-400 border-transparent",
    },
  }

  const METHOD_CONFIG: Record<TransactionMethod, string> = {
    [TransactionMethod.STRIPE]:
      "bg-indigo-500/10 text-indigo-600 dark:text-indigo-400",
    [TransactionMethod.PAYPAL]:
      "bg-blue-500/10 text-blue-600 dark:text-blue-400",
    [TransactionMethod.CARD]:
      "bg-purple-500/10 text-purple-600 dark:text-purple-400",
    [TransactionMethod.BANK_TRANSFER]:
      "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
  }

  return [
    {
      id: "user",
      accessorFn: (row) => row.user.name,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("user")} />
      ),
      cell: ({ row }) => {
        const txn = row.original
        return (
          <div className="flex items-center gap-3">
            <SpaceAvatar
              name={txn.user.name}
              src={txn.user.avatar || ""}
              size="sm"
            />
            <div>
              <p className="text-sm font-medium md:text-base">
                {txn.user.name}
              </p>
              <p className="text-xs text-muted-foreground md:text-sm">
                {txn.user.email}
              </p>
            </div>
          </div>
        )
      },
    },
    {
      id: "amount",
      accessorFn: (row) => row.amount,
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("amount")} />
      ),
      cell: ({ row }) => (
        <span className="text-sm font-medium tabular-nums">
          ${row.original.amount.toFixed(2)}
        </span>
      ),
    },
    {
      id: "method",
      accessorKey: "method",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("method")} />
      ),
      cell: ({ row }) => (
        <span
          className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${
            METHOD_CONFIG[row.original.method] ||
            "bg-muted text-muted-foreground"
          }`}
        >
          {t(row.original.method.toLowerCase())}
        </span>
      ),
    },
    {
      id: "status",
      accessorKey: "status",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("status")} />
      ),
      cell: ({ row }) => (
        <StatusBadge value={row.original.status} config={STATUS_CONFIG} />
      ),
    },
    {
      id: "createdAt",
      accessorKey: "createdAt",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title={t("date")} />
      ),
      cell: ({ row }) => {
        const date = row.original.createdAt || row.original.updatedAt || ""
        return (
          <span className="text-sm tabular-nums">
            {new Date(date).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            })}
          </span>
        )
      },
    },
    {
      id: "actions",
      cell: ({ row }) => {
        const txn = row.original
        const rowActions: RowAction<Transaction>[] = []

        rowActions.push({
          label: t("view"),
          icon: Eye,
          onClick: actions.onView,
        })

        rowActions.push({
          label: t("edit"),
          icon: Pencil,
          separatorBefore: true,
          onClick: actions.onEdit,
        })

        if (actions.onMarkAsPaid && txn.status === TransactionStatus.PENDING) {
          rowActions.push({
            label: t("markAsPaid"),
            icon: CheckCircle,
            onClick: actions.onMarkAsPaid,
          })
        }

        if (actions.onRetry && txn.status === TransactionStatus.FAILED) {
          rowActions.push({
            label: t("retry"),
            icon: RefreshCw,
            onClick: actions.onRetry,
          })
        }

        if (txn.status === TransactionStatus.PAID) {
          rowActions.push({
            label: t("refund"),
            icon: RotateCcw,
            variant: "default",
            separatorBefore: true,
            onClick: actions.onRefund,
          })
        }

        if (txn.status === TransactionStatus.PENDING) {
          rowActions.push({
            label: t("cancel"),
            icon: Ban,
            variant: "destructive",
            separatorBefore: true,
            onClick: actions.onCancel,
          })
        }

        if (
          actions.onDownloadReceipt &&
          txn.status === TransactionStatus.PAID
        ) {
          rowActions.push({
            label: t("downloadReceipt"),
            icon: FileText,
            onClick: actions.onDownloadReceipt,
          })
        }

        if (actions.onPrint && txn.status === TransactionStatus.PAID) {
          rowActions.push({
            label: t("print"),
            icon: Printer,
            onClick: actions.onPrint,
          })
        }

        rowActions.push({
          label: t("delete"),
          icon: Trash2,
          variant: "destructive",
          separatorBefore: true,
          onClick: actions.onDelete,
        })

        return <DataTableRowActions row={txn} actions={rowActions} />
      },
    },
  ]
}

// app/transactions/page.tsx

"use client"

import { useMemo, useRef, useState } from "react"
import { DataTable } from "@/components/shared/data-table-chunks/data-table"
import {
  createTransactionApi,
  updateTransactionApi,
  deleteTransactionApi,
  refundTransactionApi,
} from "@/lib/api/transactions-api"
import {
  Transaction,
  TransactionStatus,
  TransactionMethod,
} from "@/types/transactions"
import { useTransactionsTable } from "@/hooks/transactions/use-transactions-table"
import { useEntityMutations } from "@/hooks/tables/use-table-entity-mutations"
import { DataTableEntityFormSheet } from "@/components/shared/data-table-chunks/data-table-entity-form-sheet"
import { ConfirmAlertDialog } from "@/components/ui/confirm-alert-dialog"
import { useTranslations } from "next-intl"
import { TransactionForm, TransactionFormHandle } from "./transaction-form"
import { getTransactionsColumns } from "./transactions-columns"
import { TransactionsSummaryCards } from "./transactions-summary-cards"
import { toast } from "@/lib/utils/toast"
import { Plus } from "@/components/ui/carbon/icons"

type PendingAction =
  | { type: "delete"; transaction: Transaction }
  | { type: "refund"; transaction: Transaction }
  | { type: "cancel"; transaction: Transaction }
  | { type: "markAsPaid"; transaction: Transaction }
  | { type: "retry"; transaction: Transaction }
  | null

export default function TransactionsPage() {
  const t = useTranslations()
  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<"create" | "edit">("create")
  const [editingTransaction, setEditingTransaction] =
    useState<Transaction | null>(null)
  const formRef = useRef<TransactionFormHandle>(null)

  const {
    items: transactions,
    pageCount,
    totalItems,
    isLoading,
    isFetching,
    search,
    setSearch,
    pagination,
    setPagination,
    columnFilters,
    setColumnFilters,
    sorting,
    setSorting,
    refresh,
  } = useTransactionsTable()

  const { create, isCreating, update, isUpdating, remove, isDeleting } =
    useEntityMutations({
      queryKey: "transactions",
      createFn: createTransactionApi,
      updateFn: updateTransactionApi,
      deleteFn: deleteTransactionApi,
      entityLabel: "Transaction",
    })

  const [pendingAction, setPendingAction] = useState<PendingAction>(null)
  const [isProcessing, setIsProcessing] = useState(false)

  function openCreateForm() {
    setFormMode("create")
    setEditingTransaction(null)
    setFormOpen(true)
  }

  function openEditForm(transaction: Transaction) {
    setFormMode("edit")
    setEditingTransaction(transaction)
    setFormOpen(true)
  }

  function handleFormValid(values: any) {
    if (formMode === "create") {
      create(values, { onSuccess: () => setFormOpen(false) })
    } else if (editingTransaction) {
      update(editingTransaction.id, values)
      setFormOpen(false)
    }
  }

  async function handleConfirm() {
    if (!pendingAction) return

    setIsProcessing(true)
    try {
      switch (pendingAction.type) {
        case "delete":
          remove(pendingAction.transaction.id, {
            onSuccess: () => setPendingAction(null),
          })
          break
        case "refund":
          await refundTransactionApi(pendingAction.transaction.id)
          refresh()
          setPendingAction(null)
          toast.success(t("transactionRefundedSuccess"))
          break
        case "cancel":
          await updateTransactionApi(pendingAction.transaction.id, {
            status: TransactionStatus.CANCELED,
          })
          refresh()
          setPendingAction(null)
          toast.success(t("transactionCanceledSuccess"))
          break
        case "markAsPaid":
          await updateTransactionApi(pendingAction.transaction.id, {
            status: TransactionStatus.PAID,
          })
          refresh()
          setPendingAction(null)
          toast.success(t("transactionMarkedAsPaid"))
          break
        case "retry":
          await updateTransactionApi(pendingAction.transaction.id, {
            status: TransactionStatus.PENDING,
          })
          refresh()
          setPendingAction(null)
          toast.success(t("transactionRetryInitiated"))
          break
      }
    } catch (error: any) {
      toast.error(error.message || t("actionFailed"))
    } finally {
      setIsProcessing(false)
    }
  }

  // Mark as paid handler
  const handleMarkAsPaid = (transaction: Transaction) => {
    setPendingAction({ type: "markAsPaid", transaction })
  }

  // Retry handler
  const handleRetry = (transaction: Transaction) => {
    setPendingAction({ type: "retry", transaction })
  }

  // Download receipt handler
  const handleDownloadReceipt = (transaction: Transaction) => {
    // Generate a simple receipt (you can make this more sophisticated)
    const receipt = {
      id: transaction.transactionId,
      user: transaction.user.name,
      amount: transaction.amount,
      method: transaction.method,
      date: transaction.date,
      status: transaction.status,
    }

    // Create a JSON blob and download
    const blob = new Blob([JSON.stringify(receipt, null, 2)], {
      type: "application/json",
    })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `receipt-${transaction.transactionId}.json`
    a.click()
    URL.revokeObjectURL(url)

    toast.success(t("receiptDownloaded"))
  }

  // Print handler
  const handlePrint = (transaction: Transaction) => {
    const printWindow = window.open("", "_blank")
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head><title>${t("receipt")} - ${transaction.transactionId}</title></head>
          <body>
            <h1>${t("transactionReceipt")}</h1>
            <p><strong>${t("id")}:</strong> ${transaction.transactionId}</p>
            <p><strong>${t("user")}:</strong> ${transaction.user.name}</p>
            <p><strong>${t("amount")}:</strong> $${transaction.amount.toFixed(2)}</p>
            <p><strong>${t("method")}:</strong> ${t(transaction.method.toLowerCase())}</p>
            <p><strong>${t("status")}:</strong> ${t(transaction.status.toLowerCase())}</p>
            <p><strong>${t("date")}:</strong> ${new Date(transaction.date).toLocaleString()}</p>
            <p><strong>${t("description")}:</strong> ${transaction.description || t("notAvailable")}</p>
          </body>
        </html>
      `)
      printWindow.document.close()
      printWindow.print()
    }
  }

  const columns = useMemo(
    () =>
      getTransactionsColumns(
        {
          onView: (txn) => openEditForm(txn),
          onEdit: (txn) => openEditForm(txn),
          onDelete: (txn) =>
            setPendingAction({ type: "delete", transaction: txn }),
          onRefund: (txn) =>
            setPendingAction({ type: "refund", transaction: txn }),
          onCancel: (txn) =>
            setPendingAction({ type: "cancel", transaction: txn }),
          onMarkAsPaid: handleMarkAsPaid,
          onRetry: handleRetry,
          onDownloadReceipt: handleDownloadReceipt,
          onPrint: handlePrint,
        },
        t
      ),
    [t, handleMarkAsPaid, handleRetry, handleDownloadReceipt, handlePrint]
  )

  const confirmConfig = useMemo(() => {
    if (!pendingAction) return null
    const name = pendingAction.transaction.user.name

    switch (pendingAction.type) {
      case "delete":
        return {
          title: t("deleteTransaction"),
          description: t("deleteTransactionConfirmation", { name }),
          confirmLabel: t("delete"),
          destructive: true,
          isLoading: isDeleting || isProcessing,
        }
      case "refund":
        return {
          title: t("refundTransaction"),
          description: t("refundTransactionConfirmation", { name }),
          confirmLabel: t("refund"),
          destructive: false,
          isLoading: isRefunding || isProcessing,
        }
      case "cancel":
        return {
          title: t("cancelTransaction"),
          description: t("cancelTransactionConfirmation", { name }),
          confirmLabel: t("cancel"),
          destructive: true,
          isLoading: isProcessing,
        }
      case "markAsPaid":
        return {
          title: t("markAsPaid"),
          description: t("markAsPaidConfirmation", { name }),
          confirmLabel: t("confirm"),
          destructive: false,
          isLoading: isProcessing,
        }
      case "retry":
        return {
          title: t("retryTransaction"),
          description: t("retryTransactionConfirmation", { name }),
          confirmLabel: t("retry"),
          destructive: false,
          isLoading: isProcessing,
        }
    }
  }, [pendingAction, isDeleting, isRefunding, isProcessing, t])

  const getDefaultValues = (transaction: Transaction | null) => {
    if (!transaction) return undefined

    return {
      user: transaction.user.id,
      amount: String(transaction.amount),
      method: transaction.method,
      status: transaction.status,
      description: transaction.description || "",
      reference: transaction.reference || "",
    }
  }

  return (
    <>
      <div className="p-4 md:p-6 space-y-6">
        <TransactionsSummaryCards transactions={transactions} />
        <DataTable
          manual
          title={t("transactions")}
          isLoading={isLoading}
          isFetching={isFetching}
          columns={columns}
          data={transactions}
          rowCount={totalItems}
          pageCount={pageCount}
          pagination={pagination}
          onPaginationChange={setPagination}
          columnFilters={columnFilters}
          onColumnFiltersChange={setColumnFilters}
          sorting={sorting}
          onSortingChange={setSorting}
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder={t("searchTransactions")}
          actions={[
            {
              label: t("create"),
              onClick: () => openCreateForm(),
              iconOnly: true,
              icon: Plus,
              variant: "primary",
            },
          ]}
          filters={[
            {
              columnId: "status",
              title: t("status"),
              options: [
                { label: t("paid"), value: TransactionStatus.PAID },
                { label: t("pending"), value: TransactionStatus.PENDING },
                { label: t("failed"), value: TransactionStatus.FAILED },
                { label: t("refunded"), value: TransactionStatus.REFUNDED },
                { label: t("canceled"), value: TransactionStatus.CANCELED },
              ],
            },
            {
              columnId: "method",
              title: t("method"),
              options: Object.values(TransactionMethod).map((method) => ({
                label: t(method.toLowerCase()),
                value: method,
              })),
            },
          ]}
        />
      </div>

      <DataTableEntityFormSheet
        open={formOpen}
        onOpenChange={setFormOpen}
        mode={formMode}
        createTitle={t("addTransaction")}
        editTitle={t("editTransaction")}
        description={
          formMode === "create"
            ? t("createNewTransaction")
            : t("updateTransactionDetails")
        }
        isSubmitting={isCreating || isUpdating}
        onSubmit={() => formRef.current?.submit()}
      >
        <TransactionForm
          ref={formRef}
          mode={formMode}
          defaultValues={getDefaultValues(editingTransaction)}
          onValid={handleFormValid}
        />
      </DataTableEntityFormSheet>

      {confirmConfig && (
        <ConfirmAlertDialog
          open={!!pendingAction}
          onOpenChange={(open) => !open && setPendingAction(null)}
          title={confirmConfig.title}
          description={confirmConfig.description}
          confirmLabel={confirmConfig.confirmLabel}
          destructive={confirmConfig.destructive}
          isLoading={confirmConfig.isLoading}
          onConfirm={handleConfirm}
        />
      )}
    </>
  )
}

"use client"

import { useMemo } from "react"
import { useTranslations } from "next-intl"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardAction,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  TrendingDown,
  TrendingUp,
  DollarSign,
  Clock,
  AlertCircle,
  CheckCircle,
} from "@/components/ui/carbon/icons"
import { Transaction, TransactionStatus } from "@/types/transactions"

interface TransactionsSummaryCardsProps {
  transactions: Transaction[]
}

interface SummaryData {
  totalRevenue: number
  successful: number
  pending: number
  failed: number
}

export function TransactionsSummaryCards({
  transactions,
}: TransactionsSummaryCardsProps) {
  const t = useTranslations()

  const summary = useMemo<SummaryData>(() => {
    return transactions.reduce(
      (acc, transaction) => {
        if (transaction.status === TransactionStatus.PAID) {
          acc.totalRevenue += transaction.amount
          acc.successful += transaction.amount
        } else if (transaction.status === TransactionStatus.PENDING) {
          acc.pending += transaction.amount
        } else if (transaction.status === TransactionStatus.FAILED) {
          acc.failed += transaction.amount
        }
        return acc
      },
      { totalRevenue: 0, successful: 0, pending: 0, failed: 0 }
    )
  }, [transactions])

  const cards = [
    {
      key: "totalRevenue",
      title: t("totalRevenue"),
      value: `$${summary.totalRevenue.toFixed(2)}`,
      valueClassName: "",
      badge: {
        label: "+12.5%",
        icon: TrendingUp,
        variant: "outline" as const,
        className: "gap-1",
      },
      footer: {
        icon: DollarSign,
        text: t("totalRevenueDescription"),
        subtext: t("totalRevenueSubtext"),
        className: "",
      },
    },
    {
      key: "successful",
      title: t("successful"),
      value: `$${summary.successful.toFixed(2)}`,
      valueClassName: "text-emerald-600",
      badge: {
        label: t("paid"),
        icon: CheckCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-emerald-500/20 bg-emerald-500/10 text-emerald-600",
      },
      footer: {
        icon: TrendingUp,
        text: t("successfulTransactions"),
        subtext: t("successfulTransactionsSubtext"),
        className: "text-emerald-600",
      },
    },
    {
      key: "pending",
      title: t("pending"),
      value: `$${summary.pending.toFixed(2)}`,
      valueClassName: "text-amber-600",
      badge: {
        label: t("pending"),
        icon: Clock,
        variant: "outline" as const,
        className: "gap-1 border-amber-500/20 bg-amber-500/10 text-amber-600",
      },
      footer: {
        icon: Clock,
        text: t("pendingTransactions"),
        subtext: t("pendingTransactionsSubtext"),
        className: "text-amber-600",
      },
    },
    {
      key: "failed",
      title: t("failed"),
      value: `$${summary.failed.toFixed(2)}`,
      valueClassName: "text-destructive",
      badge: {
        label: t("failed"),
        icon: AlertCircle,
        variant: "outline" as const,
        className:
          "gap-1 border-destructive/20 bg-destructive/10 text-destructive",
      },
      footer: {
        icon: TrendingDown,
        text: t("failedTransactions"),
        subtext: t("failedTransactionsSubtext"),
        className: "text-destructive",
      },
    },
  ]

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 w-full">
      {cards.map((card) => (
        <Card key={card.key} className="h-full flex flex-col justify-between">
          <CardHeader className="p-5 pb-3">
            <div className="flex items-center justify-between gap-2">
              <CardDescription className="text-xs font-medium uppercase tracking-wider">{card.title}</CardDescription>
              <Badge
                variant={card.badge.variant}
                className={card.badge.className}
              >
                <card.badge.icon className="size-3" />
                {card.badge.label}
              </Badge>
            </div>
            <CardTitle
              className={`text-2xl font-bold font-mono tabular-nums @[250px]/card:text-3xl mt-2 ${card.valueClassName}`}
            >
              {card.value}
            </CardTitle>
          </CardHeader>
          <CardFooter className="px-5 py-3 pt-0 border-t-0 flex items-center gap-1.5 text-xs text-muted-foreground mt-auto">
            <card.footer.icon className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="truncate font-medium">{card.footer.text}</span>
          </CardFooter>
        </Card>
      ))}
    </div>
  )
}

// components/shared/select-user.tsx

"use client"

import { useEffect, useMemo, useState } from "react"
import { ChevronsUpDown, Loader2, SearchIcon, Users, X } from "@/components/ui/carbon/icons"
import { cn } from "@/lib/utils"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { useTranslations } from "next-intl"
import { useUsersOptions } from "@/hooks/users/use-users-options"
import { SpaceAvatar } from "@/components/ui/space-avatar"

interface SelectUserProps {
  value?: string
  onChange: (userId: string) => void
  placeholder?: string
  disabled?: boolean
  excludeUserId?: string
}

export function SelectUser({
  value,
  onChange,
  placeholder,
  disabled = false,
  excludeUserId,
}: SelectUserProps) {
  const t = useTranslations()
  const [open, setOpen] = useState(false)

  const {
    data: users,
    isLoading,
    isFetching,
    search,
    setSearch,
  } = useUsersOptions()

  const placeholderText = placeholder || t("selectUser")

  // Filter out excluded user
  const filteredUsers = useMemo(() => {
    if (!users) return []
    return excludeUserId
      ? users.filter((user) => user.id !== excludeUserId)
      : users
  }, [users, excludeUserId])

  const selectedUser = useMemo(() => {
    if (!value || !users) return null
    return users.find((u) => u.id === value) || null
  }, [value, users])

  const selectUser = (userId: string) => {
    onChange(userId)
    setOpen(false)
  }

  const clearSelection = () => {
    onChange("")
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <div
          role="combobox"
          aria-expanded={open}
          aria-controls="user-listbox"
          tabIndex={disabled ? -1 : 0}
          aria-disabled={disabled}
          onKeyDown={(e) => {
            if (disabled) return
            if (e.key === "Enter" || e.key === " " || e.key === "ArrowDown") {
              e.preventDefault()
              setOpen(true)
            }
          }}
          className={cn(
            "flex h-auto min-h-[52px] w-full cursor-pointer items-center justify-between gap-2 overflow-hidden rounded-md border border-input bg-card px-3 py-2 text-sm font-normal shadow-sm transition-colors",
            "hover:bg-accent/50",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:outline-none",
            disabled && "pointer-events-none cursor-not-allowed opacity-50"
            // value && "border-primary/30 bg-primary/5 hover:bg-primary/10"
          )}
        >
          {isLoading && !value ? (
            <span className="flex items-center gap-2 text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
              {t("loadingUsers")}
            </span>
          ) : value && selectedUser ? (
            <div className="flex items-center gap-2 truncate">
              <span className="truncate">{selectedUser.name}</span>
              <span className="shrink-0 text-xs text-muted-foreground">
                ({selectedUser.email})
              </span>
            </div>
          ) : (
            <span className="text-muted-foreground">{placeholderText}</span>
          )}
          <div className="flex shrink-0 items-center gap-1.5">
            {value && (
              <span
                role="button"
                tabIndex={0}
                onClick={(e) => {
                  e.stopPropagation()
                  clearSelection()
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault()
                    e.stopPropagation()
                    clearSelection()
                  }
                }}
                className="cursor-pointer rounded-sm p-0.5 text-muted-foreground transition-colors hover:bg-destructive/20 hover:text-destructive focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                aria-label={t("clearUser")}
              >
                <X className="size-3.5" />
              </span>
            )}
            <ChevronsUpDown className="size-4 shrink-0 opacity-50" />
          </div>
        </div>
      </PopoverTrigger>

      <PopoverContent
        className="w-[var(--radix-popover-trigger-width)] rounded-xl p-0 shadow-xl"
        align="start"
        sideOffset={6}
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <div className="flex flex-col overflow-hidden rounded-xl">
          {/* Header with count */}
          <div className="flex items-center justify-between border-b px-3 py-2">
            <div className="flex items-center gap-2">
              <Users className="size-4 text-primary" />
              <span className="text-sm font-semibold">{t("users")}</span>
            </div>
            {value && (
              <span className="text-xs text-muted-foreground">
                {t("selectedCount", { count: 1 })}
              </span>
            )}
          </div>

          {/* Plain search input instead of CommandInput */}
          <div className="flex items-center gap-2 border-b px-3 py-2">
            <SearchIcon className="size-4 shrink-0 text-muted-foreground" />
            <input
              autoFocus
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t("searchUsers")}
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>

          {/* Plain scrollable list — overflow works fine, no cmdk involved */}
          <div role="listbox" className="max-h-56 overflow-y-auto p-1">
            {isLoading || (isFetching && search) ? (
              <div className="flex items-center justify-center gap-2 py-8 text-sm text-muted-foreground">
                <Loader2 className="size-4 animate-spin" />
                {search ? t("searching") : t("loadingUsers")}
              </div>
            ) : filteredUsers.length === 0 ? (
              <div className="flex flex-col items-center gap-2 py-8 text-center">
                <Users className="size-8 text-muted-foreground/50" />
                <p className="text-sm font-medium">{t("noUsersFound")}</p>
                <p className="text-xs text-muted-foreground">
                  {t("tryAdjustingSearch")}
                </p>
              </div>
            ) : (
              filteredUsers.map((user) => {
                const checked = value === user.id
                return (
                  <div
                    key={user.id}
                    role="option"
                    aria-selected={checked}
                    tabIndex={0}
                    onClick={() => selectUser(user.id, user.name)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault()
                        selectUser(user.id, user.name)
                      }
                    }}
                    className={cn(
                      "flex cursor-pointer items-center gap-2.5 rounded-lg px-3 py-2.5 outline-none",
                      "hover:bg-accent focus-visible:bg-accent",
                      checked && "bg-primary/5"
                    )}
                  >
                    <SpaceAvatar
                      name={user.name}
                      profileColor={user.profileColor}
                      src={user.avatar}
                      size="xs"
                    />
                    <div className="flex flex-1 flex-col truncate">
                      <span className="font-medium">{user.name}</span>
                      <span className="text-xs text-muted-foreground">
                        {user.email}
                      </span>
                    </div>
                  </div>
                )
              })
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

