import { User, UserRole, UserStatus, UserType } from "@/types/users"
import apiClient from "@/lib/myapi/client"
import { ApiPaginatedResponse, ServerTableParams } from "../../types/tables"
import {
  getDemoUsers,
  addDemoUser,
  updateDemoUser,
  deleteDemoUser,
  paginateDemoList,
} from "@/lib/demo-data"

/**
 * Shape of user records as returned by backend microservices or raw payloads.
 */
export interface RawBackendUser {
  id: string
  name: string
  email: string
  role?: string
  userType?: UserType
  status?: UserStatus
  isActive?: boolean
  isVerified?: boolean
  isBanned?: boolean
  orgId?: string
  createdAt?: string
  updatedAt?: string
  profileColor?: string
  avatar?: string | null
  roles?: any[]
  [key: string]: unknown
}

/**
 * Normalizes a raw user payload from either a microservice backend or demo fixtures
 * into the strict {@link User} domain model. Resolves user roles to UserType enums,
 * sets active/banned status defaults, and assigns profile colors and avatar paths.
 *
 * @param u - Raw user object from server or demo store
 * @returns Fully typed and normalized User entity
 */
function mapUser(u: RawBackendUser): User {
  let userType = u.userType
  if (!userType) {
    userType =
      u.role === "admin"
        ? UserType.ADMIN
        : u.role === "staff"
        ? UserType.STAFF
        : UserType.USER
  }
  let status = u.status
  if (!status) {
    status = u.isBanned
      ? UserStatus.BANNED
      : u.isActive === false
      ? UserStatus.INACTIVE
      : UserStatus.ACTIVE
  }

  return {
    id: u.id,
    name: u.name,
    email: u.email,
    role: u.role as UserRole,
    userType,
    status,
    isActive: u.isActive ?? !u.isBanned,
    isVerified: u.isVerified ?? false,
    isBanned: u.isBanned ?? status === UserStatus.BANNED,
    orgId: u.orgId,
    createdAt: u.createdAt,
    updatedAt: u.updatedAt,
    profileColor: u.profileColor || "#0f62fe",
    avatar: u.avatar || undefined,
    roles: u.roles || [],
  }
}

/**
 * Retrieves a paginated list of users matching query parameters.
 * Implements the Dual-Mode Resiliency Pattern: attempts to fetch live records
 * from `/users` via the backend proxy, falling back to the in-memory demo engine
 * upon network disconnect or HTTP failure.
 *
 * @param params - Server table parameters including page, limit, search, and filters
 * @returns Standardized paginated response containing normalized User records
 */
export const fetchUsersApi = async (
  params: Partial<ServerTableParams> = {}
): Promise<ApiPaginatedResponse<User>> => {
  try {
    const { data } = await apiClient.get("/users")
    const rawList: any[] = Array.isArray(data) ? data : data?.data || []
    if (rawList.length > 0) {
      const mappedList = rawList.map(mapUser)
      return paginateDemoList(
        mappedList,
        params,
        (u, search) =>
          (u.name?.toLowerCase().includes(search) ?? false) ||
          (u.email?.toLowerCase().includes(search) ?? false)
      )
    }
  } catch {
    // Fallback to demo users
  }

  return paginateDemoList(
    getDemoUsers(),
    params,
    (u, search) =>
      (u.name?.toLowerCase().includes(search) ?? false) ||
      (u.email?.toLowerCase().includes(search) ?? false)
  )
}

export const toggleStatusUserApi = async (
  id: string,
  isActive?: boolean
): Promise<User> => {
  try {
    const { data } = await apiClient.patch(
      `/users/${id}/status`,
      isActive !== undefined ? { isActive } : {}
    )
    return mapUser(data)
  } catch {
    return updateDemoUser(id, { isActive: isActive ?? true })
  }
}

export const toggleBanUserApi = async (
  id: string,
  isBanned?: boolean
): Promise<User> => {
  try {
    return await toggleStatusUserApi(id, isBanned !== undefined ? !isBanned : undefined)
  } catch {
    return updateDemoUser(id, {
      status: isBanned ? UserStatus.BANNED : UserStatus.ACTIVE,
      isActive: !isBanned,
    })
  }
}

export const activateUserApi = async (
  id: string,
  isActive?: boolean
): Promise<User> => {
  return toggleStatusUserApi(id, isActive)
}

export const deleteUserApi = async (id: string): Promise<void> => {
  try {
    await apiClient.delete(`/users/${id}`)
  } catch {
    deleteDemoUser(id)
  }
}

export const createUserApi = async (input: {
  name: string
  email: string
  role?: string
}): Promise<User> => {
  try {
    const { data } = await apiClient.post("/users", input)
    return mapUser(data)
  } catch {
    return addDemoUser({
      name: input.name,
      email: input.email,
      role: (input.role as UserRole) || "user",
    })
  }
}

export const getUserApi = async (id: string): Promise<User> => {
  try {
    const { data } = await apiClient.get(`/users/${id}`)
    return mapUser(data)
  } catch {
    const found = getDemoUsers().find((u) => u.id === id)
    return found || getDemoUsers()[0]
  }
}

export const updateUserApi = async (
  id: string,
  input: any
): Promise<User> => {
  try {
    const { data } = await apiClient.patch(`/users/${id}`, input)
    return mapUser(data)
  } catch {
    return updateDemoUser(id, input)
  }
}

import { User, UserType } from "@/types/users"
import { AdminPermissionsPlatform } from "@/types/roles"

/**
 * Extracts the full set of effective permissions for a user.
 * Merges direct permissions and active role permissions.
 */
export function getUserPermissions(user: User | undefined): Set<AdminPermissionsPlatform> {
  if (!user) return new Set()

  const permissions = new Set<AdminPermissionsPlatform>()

  // Direct user permissions
  if (user.permissions?.length) {
    user.permissions.forEach((p) => permissions.add(p))
  }

  // Active role permissions
  if (user.roles?.length) {
    user.roles
      .filter((role: any) => !role.status || role.status === "active")
      .forEach((role) => {
        role.permissions?.forEach((p) => permissions.add(p))
      })
  }

  return permissions
}

/**
 * Returns true if the user has super-admin or owner privileges that bypass granular checks.
 */
export function isSuperUser(user: User | undefined): boolean {
  if (!user) return false
  return (
    user.role === "admin" ||
    user.userType === UserType.ADMIN ||
    (user as any).userType === "owner" ||
    (user as any).teamRole === "owner"
  )
}

/**
 * Central RBAC gatekeeper. Checks whether a user has a specific permission.
 *
 * Rules:
 * 1. Unauthenticated users have NO permissions.
 * 2. Superusers (admin/owner) have ALL permissions.
 * 3. Users with `AdminPermissionsPlatform.ALL` have ALL permissions.
 * 4. Otherwise, user must possess the specific permission directly or via active roles.
 */
export function can(
  user: User | undefined,
  permission: AdminPermissionsPlatform
): boolean {
  if (!user) return false
  if (isSuperUser(user)) return true

  const perms = getUserPermissions(user)
  if (perms.has(AdminPermissionsPlatform.ALL)) return true

  return perms.has(permission)
}

/**
 * Checks whether a user possesses ALL of the specified permissions.
 */
export function canAll(
  user: User | undefined,
  permissions: AdminPermissionsPlatform[]
): boolean {
  if (!user) return false
  if (isSuperUser(user)) return true
  return permissions.every((p) => can(user, p))
}

/**
 * Checks whether a user possesses AT LEAST ONE of the specified permissions.
 */
export function canAny(
  user: User | undefined,
  permissions: AdminPermissionsPlatform[]
): boolean {
  if (!user) return false
  if (isSuperUser(user)) return true
  return permissions.some((p) => can(user, p))
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import {
  connectSocket,
  disconnectSocket,
  getSocket,
  getSocketAsync,
  getSocketUrl,
} from "./socket-client"
import { io } from "socket.io-client"

vi.mock("socket.io-client", () => {
  return {
    io: vi.fn(),
  }
})

describe("socket-client", () => {
  const originalEnv = process.env
  let mockSocket: any
  let eventListeners: Record<string, ((...args: any[]) => void)[]> = {}

  beforeEach(() => {
    process.env = { ...originalEnv }
    eventListeners = {}

    mockSocket = {
      connected: false,
      on: vi.fn((event: string, callback: (...args: any[]) => void) => {
        if (!eventListeners[event]) {
          eventListeners[event] = []
        }
        eventListeners[event].push(callback)
        return mockSocket
      }),
      off: vi.fn((event: string, callback: (...args: any[]) => void) => {
        if (eventListeners[event]) {
          eventListeners[event] = eventListeners[event].filter(
            (cb) => cb !== callback
          )
        }
        return mockSocket
      }),
      disconnect: vi.fn(() => {
        mockSocket.connected = false
      }),
      emit: vi.fn(),
    }

    vi.mocked(io).mockReturnValue(mockSocket)
    disconnectSocket()
  })

  afterEach(() => {
    process.env = originalEnv
    vi.clearAllMocks()
    disconnectSocket()
  })

  describe("getSocketUrl", () => {
    it("should prioritize NEXT_PUBLIC_SOCKET_URL if set", () => {
      process.env.NEXT_PUBLIC_SOCKET_URL = "https://socket.example.com"
      process.env.NEXT_PUBLIC_API_URL = "https://api.example.com/api"

      expect(getSocketUrl()).toBe("https://socket.example.com")
    })

    it("should strip trailing /api from NEXT_PUBLIC_API_URL if socket URL not set", () => {
      delete process.env.NEXT_PUBLIC_SOCKET_URL
      process.env.NEXT_PUBLIC_API_URL = "http://localhost:40001/api"

      expect(getSocketUrl()).toBe("http://localhost:40001")
    })

    it("should strip trailing /api/ with slash from NEXT_PUBLIC_API_URL", () => {
      delete process.env.NEXT_PUBLIC_SOCKET_URL
      process.env.NEXT_PUBLIC_API_URL = "https://backend.mycorp.internal/api/"

      expect(getSocketUrl()).toBe("https://backend.mycorp.internal")
    })

    it("should fall back to http://localhost:40001 when neither env var is defined", () => {
      delete process.env.NEXT_PUBLIC_SOCKET_URL
      delete process.env.NEXT_PUBLIC_API_URL

      expect(getSocketUrl()).toBe("http://localhost:40001")
    })
  })

  describe("connectSocket - Cookie-Based Auth Handshake", () => {
    it("should connect with withCredentials: true and omit auth payload when token is undefined", () => {
      process.env.NEXT_PUBLIC_API_URL = "http://localhost:40001/api"

      const s = connectSocket(undefined)

      expect(io).toHaveBeenCalledTimes(1)
      expect(io).toHaveBeenCalledWith(
        "http://localhost:40001",
        expect.objectContaining({
          withCredentials: true,
          transports: ["websocket"],
          reconnection: true,
          reconnectionAttempts: 10,
        })
      )

      // Ensure no auth object with undefined token is passed
      const callArgs = vi.mocked(io).mock.calls[0]
      const passedOptions = callArgs[1] as any
      expect(passedOptions.auth).toBeUndefined()
      expect(s).toBe(mockSocket)
    })

    it("should omit auth payload when token is empty or whitespace string", () => {
      connectSocket("   ")

      const callArgs = vi.mocked(io).mock.calls[0]
      const passedOptions = callArgs[1] as any
      expect(passedOptions.auth).toBeUndefined()
    })

    it("should return existing socket instance if already connected", () => {
      mockSocket.connected = true
      const s1 = connectSocket()
      const s2 = connectSocket()

      expect(io).toHaveBeenCalledTimes(1)
      expect(s1).toBe(s2)
    })
  })

  describe("connectSocket - Explicit Token", () => {
    it("should include auth: { token } when a valid token string is provided", () => {
      process.env.NEXT_PUBLIC_API_URL = "http://localhost:40001/api"

      connectSocket("short-lived-ticket-token-123")

      expect(io).toHaveBeenCalledWith(
        "http://localhost:40001",
        expect.objectContaining({
          withCredentials: true,
          transports: ["websocket"],
          auth: { token: "short-lived-ticket-token-123" },
        })
      )
    })
  })

  describe("Authentication Error Handling", () => {
    it("should disconnect socket and halt reconnection on unauthorized connect_error", () => {
      connectSocket()

      const errorHandler = eventListeners["connect_error"]?.[0]
      expect(errorHandler).toBeDefined()

      // Trigger auth error
      const authError = new Error("Unauthorized: Session cookie missing or invalid")
      errorHandler(authError)

      expect(mockSocket.disconnect).toHaveBeenCalledTimes(1)
    })

    it("should disconnect socket on forbidden connect_error", () => {
      connectSocket()

      const errorHandler = eventListeners["connect_error"]?.[0]
      expect(errorHandler).toBeDefined()

      const forbiddenError = new Error("Forbidden: Invalid origin")
      errorHandler(forbiddenError)

      expect(mockSocket.disconnect).toHaveBeenCalledTimes(1)
    })

    it("should not disconnect socket on normal network hiccup errors", () => {
      connectSocket()

      const errorHandler = eventListeners["connect_error"]?.[0]
      expect(errorHandler).toBeDefined()

      const networkError = new Error("websocket error: connection timeout")
      errorHandler(networkError)

      // Regular network errors should allow socket.io automatic reconnection attempts
      expect(mockSocket.disconnect).not.toHaveBeenCalled()
    })
  })

  describe("getSocket and getSocketAsync", () => {
    it("should throw if getSocket is called before connectSocket", () => {
      expect(() => getSocket()).toThrow("Socket not initialized. Call connectSocket() first.")
    })

    it("should return socket once connected", () => {
      connectSocket()
      expect(getSocket()).toBe(mockSocket)
    })

    it("should resolve immediately if socket already exists in getSocketAsync", async () => {
      connectSocket()
      const s = await getSocketAsync()
      expect(s).toBe(mockSocket)
    })

    it("should resolve once connectSocket is called after getSocketAsync", async () => {
      const promise = getSocketAsync(500)
      connectSocket()
      const s = await promise
      expect(s).toBe(mockSocket)
    })
  })

  describe("disconnectSocket", () => {
    it("should call socket.disconnect and reset singleton to null", () => {
      connectSocket()
      expect(getSocket()).toBe(mockSocket)

      disconnectSocket()
      expect(mockSocket.disconnect).toHaveBeenCalled()
      expect(() => getSocket()).toThrow("Socket not initialized")
    })
  })
})

